let a = getInts(count: N)

struct Update {
    let b, c: Int
    static func composition(_ u: Update, _ v: Update) -> Update {
        Update(
            b: u.b * v.b % MOD,
            c: (v.b * u.c + v.c) % MOD
        )
    }
}
var st = SegmentTree<Int, Update>(
    count: N,
    zero: 0,
    combine: { ($0+$1) % MOD },
    update: { x, u in (x * u.b + u.c) % MOD },
    updateDistributive: { x, u, w in (u.b * x + w * u.c) % MOD },
    updateComposition: Update.composition
)
