composition =  Proc(Tuple(Int64, Int64), Tuple(Int64, Int64), Tuple(Int64, Int64)).new{ |fl, fr| {(fl[0] * fr[0]) % M, ((fr[1] * fl[0]) % M + fl[1]) % M} }

