class RSQRUQ{
  public:
    using value_type = T;
    using lazy_type = E;
    const static T identity;
    const static E lazy_def;
    RSQRUQ(){}
    static T operation(T &l, T &r){
      return (l + r) % mod;
    }
    static E lazy_accumulate(E &l, E &r){
      if(l == lazy_def)return r;
      return mk(r.first * l.first % mod, (r.first * l.second % mod + r.second) % mod);
    }
    static T lazy_update(T &t, E &e, int len){
      return (t * e.first % mod + e.second * len % mod) % mod;
    }
};
