auto g = [](pll a, pll b) -> pll { return { ((a.first*b.first) % MOD + (a.second*b.second) % MOD) % MOD, a.second }; };
auto h = [](pll a, pll b) -> pll { return { (a.first*b.first) % MOD, ((a.second*b.first) % MOD + b.second) % MOD }; };

