struct RAfQRSQ : LazySegmentTree<T, U>{
    using Base = LazySegmentTree<T, U>;
    T f(const T& a, const T& b){ return a + b; }
    void m(ll rank, T& x, const U& val){ x *= val.first; x += val.second * (1 << rank); }
    void c(U& a, const U& b){ a = {a.first * b.first, a.second * b.first + b.second}; }
    RAfQRSQ(const vector<T>& v, const T& def_value = T(), const U& def_lazy = {1, 0}) : Base(v, def_value, def_lazy){
        for(ll i = Base::size; --i;) Base::data[i] = f(Base::data[i * 2], Base::data[i * 2 + 1]);
    }
};
