// Time Complexity: build O(N), query O(logN)
template <typename T, typename U = T>
struct LazySegmentTree {
    // T should be Monoid (Associativity, Identity element)
    using FuncTT = function<T(T, T)>;
    using FuncTU = function<T(T, U)>;
    using FuncUU = function<U(U, U)>;
    int sz;          // size of array
    vector<T> data;  // 1-indexed(size: sz*2)
    vector<U> lazy;
    T identity;  // identity element
    U identityLz;
    FuncTT f;
    FuncTU g;
    FuncUU h;

    // node k: parent k/2, children (2*k, 2*k+1)
    LazySegmentTree(int n, const T &identity, const U &identityLz,
                    FuncTT f, FuncTU g, FuncUU h)
        : identity(identity), identityLz(identityLz), f(f), g(g), h(h) {
        sz = 1;
        while (sz < n) sz <<= 1;
        data.assign(2 * sz, identity);
        lazy.assign(2 * sz, identityLz);
    }
    void set(int idx, const T &val) {
        data[idx + sz] = val;
    }
    void build() {
        for (int idx = sz - 1; idx > 0; idx--) {
            data[idx] = f(data[2 * idx], data[2 * idx + 1]);
        }
    }
    inline void evaluate(int idx) {
        if (lazy[idx] != identityLz) {
            if (idx < sz) {
                lazy[2 * idx] = h(lazy[2 * idx], lazy[idx]);
                lazy[2 * idx + 1] = h(lazy[2 * idx + 1], lazy[idx]);
            }
            data[idx] = reflect(idx);
            lazy[idx] = identityLz;
        }
    }
    inline T reflect(int idx) {
        if (lazy[idx] != identityLz)
            return g(data[idx], lazy[idx]);
        else
            return data[idx];
    }
    void update(int a, int b, const U &x) { update(a, b, x, 1, 0, sz); }
    void update(int a, int b, const U &x, int idx, int l, int r) {
        evaluate(idx);
        if (b <= l || r <= a) return;
        if (a <= l && r <= b) {
            lazy[idx] = h(lazy[idx], x);
            evaluate(idx);
        } else {
            update(a, b, x, 2 * idx, l, (l + r) / 2);
            update(a, b, x, 2 * idx + 1, (l + r) / 2, r);
            data[idx] = f(data[2 * idx], data[2 * idx + 1]);
        }
    }
    // [a, b)
    // recursive implementation
    T query(int a, int b) { return query(a, b, 1, 0, sz); }
    T query(int a, int b, int idx, int l, int r) {
        if (r <= a || b <= l) return identity;
        evaluate(idx);
        if (a <= l && r <= b)
            return data[idx];
        else {
            T vl = query(a, b, idx * 2, l, (l + r) / 2);
            T vr = query(a, b, idx * 2 + 1, (l + r) / 2, r);
            return f(vl, vr);
        }
    }
    // ToDo: for-loop implementation
    // T query(int l, int r)
    T operator[](const int &idx) {
        return query(idx, idx + 1);
    }
};

