  xy.val=x.val+y.val;
  xy.size=x.size+y.size;
  return xy;
}
vs e(){
  vs x;
  x.val=0;
  x.size=0;
  return x;
}
vs app(aff f,vs s){
  vs fs;
  fs.val=f.mul*s.val+f.add*s.size;
  fs.size=s.size;
  return fs;
}
aff com(aff f,aff g){
  aff fg;
  fg.mul=f.mul*g.mul;
  fg.add=f.mul*g.add+f.add;
  return fg;
}
aff id(){
  aff f;
  f.mul=1;
  f.add=0;
  return f;
}
