void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

int n;
ll a[500500],segtree[2002002][3];
bool delayed[2002002];

void init(int i=0, int l=0, int r=n){
	segtree[i][1] = 1ll;
	if(r-l>1){
		init(i*2+1,l,(l+r)/2);
		init(i*2+2,(l+r)/2,r);
		segtree[i][0] = (segtree[i*2+1][0]+segtree[i*2+2][0])%MOD;
	}else{
		segtree[i][0] = a[l];
	}
}
void eval(int i, int l, int r){
	if(delayed[i]){
		mul_mod(segtree[i][0],segtree[i][1]);
		add_mod(segtree[i][0],segtree[i][2]*(r-l)%MOD);
		if(r-l>1){
			mul_mod(segtree[i*2+1][1],segtree[i][1]);
			mul_mod(segtree[i*2+1][2],segtree[i][1]);
			add_mod(segtree[i*2+1][2],segtree[i][2]);
			mul_mod(segtree[i*2+2][1],segtree[i][1]);
			mul_mod(segtree[i*2+2][2],segtree[i][1]);
			add_mod(segtree[i*2+2][2],segtree[i][2]);
			delayed[i*2+1] = true;
			delayed[i*2+2] = true;
		}
		segtree[i][1] = 1ll;
		segtree[i][2] = 0ll;
		delayed[i] = false;
	}
}

ll query(int a, int b, int i=0, int l=0, int r=n){
	eval(i,l,r);
	if(r<=a || b<=l){
		return 0ll;
	}else if(a<=l && r<=b){
		return segtree[i][0];
	}else{
		return (query(a,b,i*2+1,l,(l+r)/2)+query(a,b,i*2+2,(l+r)/2,r))%MOD;
	}
}

void update(int a, int b, ll c, ll d, int i=0, int l=0, int r=n){
	eval(i,l,r);
	if(r<=a || b<=l){
		return;
	}else if(a<=l && r<=b){
		delayed[i] = true;
		segtree[i][1] = c;
		segtree[i][2] = d;
		eval(i,l,r);
	}else{
		update(a,b,c,d,i*2+1,l,(l+r)/2);
		update(a,b,c,d,i*2+2,(l+r)/2,r);
		segtree[i][0] = (segtree[i*2+1][0]+segtree[i*2+2][0])%MOD;
	}
}

