struct S {
  mint a;
  int size;
};

struct F
{
  mint b, c;
};

S op(S l, S r)
{
  return S{l.a + r.a, l.size + r.size};
}

S e()
{
  return S{0, 0};
}

S mapping(F l, S r)
{
  return S{l.b * r.a + r.size * l.c, r.size};
}

F composition(F l, F r)
{
  return F{r.b * l.b, l.b * r.c + l.c};
}

F id()
{
  return F{1, 0};
}

