    Data() = default;
    Data(mint x, int len) : x(x), len(len) {}

    static Data op(Data lhs, Data rhs) {
        return Data(lhs.x + rhs.x, lhs.len + rhs.len);
    }
    static Data id() { return Data(0, 0); }
};

struct Ope {
    mint a, b;

    Ope() = default;
    Ope(mint a, mint b) : a(a), b(b) {}

    static Ope op(Ope lhs, Ope rhs) {
        return Ope(lhs.a * rhs.a, lhs.a * rhs.b + lhs.b);
    }
    static Ope id() { return Ope(1, 0); }
};

Data apply(Ope ope, Data data) {
    return Data(data.x * ope.a + ope.b * data.len, data.len);
}

