    return {a.x+b.x,a.len+b.len};
}

T g(E a,T b){
    return {b.x*a.a+b.len*a.b,b.len};
}

E h(E a,E b){
    return {b.a*a.a,b.b*a.a+a.b};
}

T ti(){
