struct modint{
  li num;

  modint(li a=0){
    num=(a%MOD+MOD)%MOD;
  }
  modint operator+(modint a) {return{(num+a.num)%MOD};} 
  modint operator-(modint a) {return{((num-a.num)%MOD+MOD)%MOD};}
  modint operator*(modint a) {return{num*a.num%MOD};}
  modint inv(modint a);
  modint operator/(modint a) {return {*this*inv(a)};}
  modint& operator+=(modint a) {
    *this = *this+a;
    return *this;
  }
  modint& operator*=(modint a) {
    *this = *this*a;
    return *this;
  }
};

