const ll mod = 998244353;

struct mod_affine_lazy_segtree {
  int n;
  vector<ll> data;
  vector<ll> lazy_b;
  vector<ll> lazy_c;
  vector<bool> lazyFlag;

  mod_affine_lazy_segtree() {
    init(1);
  }

  mod_affine_lazy_segtree(const int s) {
    init(s);
  }

  mod_affine_lazy_segtree(const vector<ll> &v) {
    int s = v.size();
    init(s);
    for (int i = 0; i < s; i++) {
      data[i+n-1] = v[i];
    }
    for (int i = n-2; i >= 0; i--) {
      data[i] = (data[i*2+1] + data[i*2+2]) % mod;
    }
  }

  void init(const int s) {
    n = 1;
    while (n < s) n <<= 1;
    data = vector<ll>(2*n-1, 0);
    lazy_b = vector<ll>(2*n-1, 1);
    lazy_c = vector<ll>(2*n-1, 0);
    lazyFlag = vector<bool>(2*n-1);
  }

  void evaluate(int p, int a, int b) {
    if (lazyFlag[p]) {
      // (b * a[i] + c) % mod
      data[p] = (lazy_b[p] * data[p] + lazy_c[p] * (b - a)) % mod;
      if (b - a > 1) {
        lazy_b[p*2+1] = (lazy_b[p*2+1] * lazy_b[p]) % mod;
        lazy_c[p*2+1] = (lazy_c[p*2+1] * lazy_b[p] + lazy_c[p]) % mod;
        lazy_b[p*2+2] = (lazy_b[p*2+2] * lazy_b[p]) % mod;
        lazy_c[p*2+2] = (lazy_c[p*2+2] * lazy_b[p] + lazy_c[p]) % mod;
        lazyFlag[p*2+1] = true;
        lazyFlag[p*2+2] = true;
      }
      lazy_b[p] = 1;
      lazy_c[p] = 0;
      lazyFlag[p] = false;
    }
  }

  void update(int l, int r, ll vb, ll vc, int p = 0, int a = 0, int b = -1) {
    if (b < 0) b = n; // init

    // evaluate lazy value
    evaluate(p, a, b);

    if (r <= a || b <= l) return; // out of range
    if (l <= a && b <= r) { // fully covered
      lazy_b[p] = (lazy_b[p] * vb) % mod;
      lazy_c[p] = (lazy_c[p] * vb + vc) % mod;
      lazyFlag[p] = true;
      evaluate(p, a, b);
    }
    else {
      update(l, r, vb, vc, p*2+1, a, (a + b) / 2); // left
      update(l, r, vb, vc, p*2+2, (a + b) / 2, b); // right
      data[p] = (data[p*2+1] + data[p*2+2]) % mod; // update
    }
    return;
  }

  int query(int l, int r, int p = 0, int a = 0, int b = -1) {
    if (b < 0) b = n; // init
    if (r <= a || b <= l) return 0; // out of range

    // evaluate lazy value
    evaluate(p, a, b);

    if (l <= a && b <= r) return data[p];// fully covered

    int vl = query(l, r, p*2+1, a, (a + b) / 2); // left
    int vr = query(l, r, p*2+2, (a + b) / 2, b); // right
    return (vl + vr) % mod;
  }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n, q;
  cin >> n >> q;
  vector<ll> a(n);
  for (auto &x: a) cin >> x;
  vector<vector<ll> > query(q, vector<ll>(5));
  for (auto &x: query) {
    cin >> x[0] >> x[1] >> x[2];
    if (x[0] == 0) cin >> x[3] >> x[4];
  }

  mod_affine_lazy_segtree malst(a);

  vector<ll> ans;
  for (auto &x: query) {
    if (x[0] == 0) malst.update(x[1], x[2], x[3], x[4]);
    else ans.push_back(malst.query(x[1], x[2]));
  }

  for (auto &x: ans) cout << x << endl;

  return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define fr(i,j,k) for(int i=j;i<k;i++)
#define f(n) fr(i,0,n)
#define f1(n) fr(i,1,n+1)
#define pb push_back
#define F first
#define S second
#define all(x) x.begin(), x.end()
const ll mod = 998244353;
const int maxn = 5e5+5;
ll sum[maxn<<2];
ll mul[maxn<<2];
ll add[maxn<<2];
void pull(int x) {
    sum[x] = (sum[x<<1] + sum[x<<1|1]) % mod;
}


void push(int x,int l,int r,int mid) {
    if (mul[x] != -1) {
        if (~mul[x<<1]) {
            mul[x<<1] *= mul[x];
            mul[x<<1] %= mod;
        }
        else {
            mul[x<<1] = mul[x];
        }
        sum[x<<1] *= mul[x];
        sum[x<<1] %= mod;
        if (~add[x<<1]) {
            add[x<<1] *= mul[x];
            add[x<<1] %= mod;
        }
        if (~mul[x<<1|1]) {
            mul[x<<1|1] *= mul[x];
            mul[x<<1|1] %= mod;
        }
        else {
            mul[x<<1|1] = mul[x];
        }
        sum[x<<1|1] *= mul[x];
        sum[x<<1|1] %= mod;
        if (~add[x<<1|1]) {
            add[x<<1|1] *= mul[x];
            add[x<<1|1] %= mod;
        }
        mul[x] = -1;
    }
    if (add[x] != -1) {
        if (!(~add[x<<1])) {
            add[x<<1] = add[x];
        }
        else {
            add[x<<1] += add[x];
            add[x<<1] %= mod;
        }
        sum[x<<1] += (mid-l+1) * add[x] % mod;
        sum[x<<1] %= mod;
        if (!(~add[x<<1|1])) {
            add[x<<1|1] = add[x];
        }
        else {
            add[x<<1|1] += add[x];
            add[x<<1|1] %= mod;
        }
        sum[x<<1|1] += (r - mid) * add[x] % mod;
        sum[x<<1|1] %= mod;
        add[x] = -1;
    }
}
void update(int x,int l,int r,int ql,int qr,int ad,int mu) {
    if (ql <= l && qr >= r) {
        sum[x] *= mu;
        sum[x] %= mod;
        sum[x] += (ll)(r - l + 1) * ad;
        sum[x] %= mod;
        if (mul[x] == -1) {
            mul[x] = mu;
        }
        else {
            mul[x] *= mu;
            mul[x] %= mod;
        }
        if (add[x] == -1) {
            add[x] = ad;
        }
        else {
            add[x] += ad;
            add[x] %= mod;
        }
        return;
    }
    int mid = (l + r) >> 1;
    push(x,l,r,mid);
    if (ql <= mid) {
        update(x<<1,l,mid,ql,qr,ad,mu);
    }
    if (qr > mid) {
        update(x<<1|1,mid+1,r,ql,qr,ad,mu);
    }
    pull(x);
}
ll query(int x,int l,int r,int ql,int qr) {
    if (ql <= l && qr >= r) {
        return sum[x];
    }
    int mid = (l + r) >> 1;
    push(x,l,r,mid);
    if (qr <= mid) {
        return query(x<<1,l,mid,ql,qr);
    }
    if (ql > mid) {
        return query(x<<1|1,mid+1,r,ql,qr);
    }
    return (query(x<<1,l,mid,ql,qr) + query(x<<1|1,mid+1,r,ql,qr)) % mod;
}
void build(int x,int l,int r) {
    if (l == r) {
        cin >> sum[x];
        return;
    }
    int mid = (l + r) >> 1;
    build(x<<1,l,mid);
    build(x<<1|1,mid+1,r);
    pull(x);
}
void solve() {
    int n, q;
    cin >> n >> q;
    memset(add, -1, sizeof(add));
    memset(mul,-1, sizeof(mul));
    build(1,1,n);
    while (q--) {
        int op,l,r;
        cin >> op >> l >> r;
        l++;
        if (op == 0) {
            int a, b;
            cin >> a >> b;
            update(1,1,n,l,r,b,a);
        }
        else {
            cout << query(1,1,n,l,r) << '\n';
        }
    }
}
int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int c = 0;
    int t;
    if (!c) {
        t = 1;
    }
    else {
        cin >> t;
    }
    while (t--) {
        solve();
    }

}

