template<typename Monoid, typename OperatorMonoid, typename F, typename G, typename H>
struct LazySegmentTree{
	//using F=function<Monoid(Monoid, Monoid)>;
	//using G=function<Monoid(Monoid, OperatorMonoid, int)>;
	//using H=function<OperatorMonoid(OperatorMonoid, OperatorMonoid)>;
	int sz;
	vector<Monoid> data;
	vector<OperatorMonoid> lazy;
	const F f;
	const G g;
	const H h;
	const Monoid e1;
	const OperatorMonoid e0;

	LazySegmentTree(int n, const F f, const G g, const H h, const Monoid &e1, const OperatorMonoid &e0): f(f), g(g), h(h), e1(e1), e0(e0){
		sz=1;
		while(sz<n) sz<<=1;
		data.resize(2*sz-1, e1);
		lazy.resize(2*sz-1, e0);
	}

	void build(vector<Monoid> v){
		for(int i=0; i<v.size(); i++) data[i+sz-1]=v[i];
		for(int i=sz-2; i>=0; i--) data[i]=f(data[2*i+1], data[2*i+2]);
	}

	void eval(int k, int l, int r){
		if(lazy[k]!=e0){
			data[k]=g(data[k], lazy[k], r-l);
			if(k<sz-1){
				lazy[2*k+1]=h(lazy[2*k+1], lazy[k]);
				lazy[2*k+2]=h(lazy[2*k+2], lazy[k]);
			}
		}
		lazy[k]=e0;
	}

	void update(int a, int b, const OperatorMonoid &x, int k, int l, int r){
		eval(k, l, r);
		if(r<=a || b<=l) return;
		if(a<=l && r<=b){
			lazy[k]=h(lazy[k], x);
			eval(k, l, r);
		}else{
			update(a, b, x, 2*k+1, l, (l+r)/2);
			update(a, b, x, 2*k+2, (l+r)/2, r);
			data[k]=f(data[2*k+1], data[2*k+2]);
		}
	}
	void update(int a, int b, const OperatorMonoid &x){
		return update(a, b, x, 0, 0, sz);
	}

	Monoid find(int a, int b, int k, int l, int r){
		eval(k, l, r);
		if(b<=l || r<=a) return e1;
		if(a<=l && r<=b) return data[k];
		else return f(find(a, b, 2*k+1, l, (l+r)/2), find(a, b, 2*k+2, (l+r)/2, r));
	}
	Monoid find(int a, int b){
		return find(a, b, 0, 0, sz);
	}
	Monoid operator[](const int &k){
		return find(k, k+1);
	}
};
int main()
{
    int n, q;
    scanf("%d %d", &n, &q);
    using mint=modint998244353;
    auto f=[](mint a, mint b){
        return a+b;
    };
    auto g=[](mint a, pair<mint, mint> x, int len){
        return x.first*a+x.second*len;
    };
    auto h=[](pair<mint, mint> x, pair<mint, mint> y){
        return make_pair(x.first*y.first, y.first*x.second+y.second);
    };
    vector<mint> a(n);
    for(int i=0; i<n; i++){
        int a1;
        scanf("%d", &a1);
        a[i]=a1;
    }
    LazySegmentTree<mint, pair<mint, mint>, decltype(f), decltype(g), decltype(h)> seg(n, f, g, h, 0, make_pair(1, 0));
    seg.build(a);
    while(q--){
        int t, l, r;
        scanf("%d %d %d", &t, &l, &r);
        if(t==0){
            int b, c;
            scanf("%d %d", &b, &c);
            seg.update(l, r, make_pair(b, c));
        }else{
            printf("%d\n", seg.find(l, r).val());
        }
    }
    return 0;
}

