template<int mod>
struct ModInt{
    int x;

    ModInt() : x(0) {}

    ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

    ModInt &operator+=(const ModInt &p){
        if((x += p.x) >= mod)   x -= mod;
        return *this;
    }

    ModInt &operator-=(const ModInt &p){
        if((x += mod - p.x) >= mod) x -= mod;
        return *this;
    }

    ModInt &operator*=(const ModInt &p){
        x = (int)(1LL * x * p.x % mod);
        return *this;
    }

    ModInt &operator/=(const ModInt &p){
        *this *= p.inverse();
        return *this;
    }

    ModInt operator-() const {return ModInt(-x);}

    ModInt operator+(const ModInt &p) const {return ModInt(*this) += p;}

    ModInt operator-(const ModInt &p) const {return ModInt(*this) -= p;}

    ModInt operator*(const ModInt &p) const {return ModInt(*this) *= p;}

    ModInt operator/(const ModInt &p) const {return ModInt(*this) /= p;}

    bool operator==(const ModInt &p) const {return x == p.x;}

    bool operator!=(const ModInt &p) const {return x != p.x;}

    ModInt inverse() const{
        int a = x, b = mod, u = 1, v = 0, t;
        while(b > 0){
            t = a / b;
            swap(a -= t * b, b);
            swap(u -= t * v, v);
        }
        return ModInt(u);
    }

    ModInt pow(int64_t n) const{
        ModInt ret(1), mul(x);
        while(n > 0){
            if(n & 1)   ret *= mul;
            mul *= mul;
            n >>= 1;
        }
        return ret;
    }

    friend ostream &operator<<(ostream &os, const ModInt &p){
        return os << p.x;
    }

    friend istream &operator>>(istream &is, ModInt &a){
        int64_t t;
        is >> t;
        a = ModInt<mod>(t);
        return (is);
    }

    static int get_mod() {return mod;}
};

using modint = ModInt<mod>;

struct LazySegmentTree{
    vector<modint> data;
    vector<modint> mul, add;
    int sz;

    LazySegmentTree(int n){
        sz = 1;
        while(sz < n)   sz <<= 1;
        data.resize(sz << 1, 0);
        mul.resize(sz << 1, 1);
        add.resize(sz << 1, 0);
    }

    void set(int k, const modint& x) { data[sz + k] = x; }

    void build(){
        for(int k = sz - 1; k > 0; --k){
            data[k] = data[k << 1] + data[k << 1 | 1];
        }
    }

    void propagate(int k, int len){
        if(mul[k] == 1 && add[k] == 0)  return;
        if(k < sz){
            mul[k << 1] *= mul[k];
            add[k << 1] = mul[k] * add[k << 1] + add[k];
            mul[k << 1 | 1] *= mul[k];
            add[k << 1 | 1] = mul[k] * add[k << 1 | 1] + add[k];
        }
        data[k] = mul[k] * data[k] + add[k] * len;
        mul[k] = 1, add[k] = 0;
    }

    modint update(int a, int b, const modint& x, const modint& y, int k = 1, int l = 0, int r = -1){
        if(r == -1) r = sz;
        propagate(k, r - l);
        if(b <= l || r <= a)    return data[k];
        else if(a <= l && r <= b){
            mul[k] *= x;
            add[k] += y;
            propagate(k, r - l);
            return data[k];
        }
        else{
            return data[k] = update(a, b, x, y, k << 1, l, (l + r) >> 1)
                            + update(a, b, x, y, k << 1 | 1, (l + r) >> 1, r);
        }
    }

    modint query(int a, int b, int k = 1, int l = 0, int r = -1){
        if(r == -1) r = sz;
        propagate(k, r - l);
        if(b <= l || r <= a)    return 0;
        else if(a <= l && r <= b)   return data[k];
        else{
            return query(a, b, k << 1, l, (l + r) >> 1)
                    + query(a, b, k << 1 | 1, (l + r) >> 1, r);
        }
    }

    modint operator[](int& k) { return query(k, k + 1); }

    int size() const { return sz; }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q, a;
    cin >> N >> Q;
    LazySegmentTree seg(N);
    for(int i = 0; i < N; ++i){
        cin >> a;
        seg.set(i, a);
    }
    seg.build();
    for(int i = 0; i < Q; ++i){
        int T, l, r;
        cin >> T >> l >> r;
        if(T)   cout << seg.query(l, r) << '\n';
        else{
            modint b, c;
            cin >> b >> c;
            seg.update(l, r, b, c);
        }
    }
}

