typedef long long ll;

template <typename T, const int MAX_E2>
struct SegTreeDelay {
  int e2;
  T nodes[MAX_E2], bs[MAX_E2], cs[MAX_E2];
  bool dls[MAX_E2];
  SegTreeDelay() {}

  void init(int n) {
    for (e2 = 1; e2 < n; e2 <<= 1);
    //fill(nodes, nodes + MAX_E2, 0);
    fill(bs, bs + MAX_E2, 1);
    //fill(cs, cs + MAX_E2, 0);
    //fill(dls, dls + MAX_E2, false);
  }

  T &get(int i) { return nodes[e2 - 1 + i]; }
  void seti(int i, T v) { get(i) = v; }

  void setall() {
    for (int j = e2 - 2; j >= 0; j--)
      nodes[j] = (nodes[j * 2 + 1] + nodes[j * 2 + 2]) % MOD;
  }

  // b1(b0*a+c0)+c1 = (b1*b0)*a+(b1*c0+c1)
  void __update(int k, int l) {
    if (dls[k]) {
      int hl = l / 2;
      int k0 = k * 2 + 1, k1 = k0 + 1;
      nodes[k0] = ((ll)bs[k] * nodes[k0] % MOD + (ll)cs[k] * hl % MOD) % MOD;
      nodes[k1] = ((ll)bs[k] * nodes[k1] % MOD + (ll)cs[k] * hl % MOD) % MOD;
      cs[k0] = ((ll)cs[k0] * bs[k] % MOD + cs[k]) % MOD;
      cs[k1] = ((ll)cs[k1] * bs[k] % MOD + cs[k]) % MOD;
      bs[k0] = (ll)bs[k0] * bs[k] % MOD;
      bs[k1] = (ll)bs[k1] * bs[k] % MOD;
      bs[k] = 1, cs[k] = 0;
      dls[k0] = dls[k1] = true;
      dls[k] = false;
    }
  }

  void set_range(int r0, int r1, int b, int c, int k, int i0, int i1) {
    if (r1 <= i0 || i1 <= r0) return;
    if (r0 <= i0 && i1 <= r1) {
      nodes[k] = ((ll)b * nodes[k] % MOD + (ll)c * (i1 - i0) % MOD) % MOD;
      cs[k] = ((ll)cs[k] * b % MOD + c) % MOD;
      bs[k] = (ll)bs[k] * b % MOD;
      dls[k] = true;
      return;
    }

    __update(k, i1 - i0);

    int im = (i0 + i1) / 2;
    int k0 = k * 2 + 1, k1 = k0 + 1;
    set_range(r0, r1, b, c, k0, i0, im);
    set_range(r0, r1, b, c, k1, im, i1);
    nodes[k] = (nodes[k0] + nodes[k1]) % MOD;
  }
  void set_range(int r0, int r1, int b, int c) {
    set_range(r0, r1, b, c, 0, 0, e2);
  }

  T sum_range(int r0, int r1, int k, int i0, int i1) {
    if (r1 <= i0 || i1 <= r0) return 0;
    if (r0 <= i0 && i1 <= r1) return nodes[k];

    __update(k, i1 - i0);

    int im = (i0 + i1) / 2;
    T v0 = sum_range(r0, r1, k * 2 + 1, i0, im);
    T v1 = sum_range(r0, r1, k * 2 + 2, im, i1);
    return (v0 + v1) % MOD;
  }
  T sum_range(int r0, int r1) { return sum_range(r0, r1, 0, 0, e2); }
};

/* global variables */

SegTreeDelay<int,MAX_E2> st;

/* subroutines */

/* main */

