template<class T,class U,class F,class G,class H>
struct lazy_segment_tree{
  std::vector<T> data;
  std::vector<U> lazy;
  int n,height;
  F merge;
  G mapping;
  H composition;
  T ti;
  U ui;
  lazy_segment_tree(){}
  lazy_segment_tree(std::vector<T>const& v,T ide1,U ide2,F f,G g,H h)
    :ti(ide1),ui(ide2),merge(f),mapping(g),composition(h)
  {
    int sz = std::size(v);
    n=1,height=0;
    while(n<sz)n<<=1,height++;
    data.resize(n<<1,ti);
    lazy.resize(n<<1,ui);
    for(int i=0;i<sz;++i)
      data[i+n] = v[i];
    for(int i=n;i-->0;)
      data[i] = merge(data[i<<1|0],data[i<<1|1]);
  }
  inline T reflect(int k){
    return lazy[k]==ui?data[k]:mapping(data[k],lazy[k]);
  }
  inline void evaluate(int k){
    if(lazy[k]==ui)return;
    if(k<n){
      lazy[k<<1|0] = composition(lazy[k<<1|0],lazy[k]);
      lazy[k<<1|1] = composition(lazy[k<<1|1],lazy[k]);
    }
    data[k] = reflect(k);
    lazy[k] = ui;
  }
  inline void propagate(int k){
    for(int i=height;i>=0;--i)evaluate(k>>i);
  }
  inline void recalc(int k){
    while(k>>=1)data[k] = merge(reflect(k<<1|0),reflect(k<<1|1));
  }
  void update(int a,int b,U v){
    a+=n;b+=n;propagate(a);propagate(b-1);
    for(int l=a,r=b;l<r;l>>=1,r>>=1){
      if(l&1)lazy[l] = composition(lazy[l],v),l++;
      if(r&1)--r,lazy[r] = composition(lazy[r],v);
    }
    recalc(a);recalc(b-1);
  }
  T fold(int a,int b){
    a+=n;b+=n;propagate(a),propagate(b-1);
    T lef_v(ti),rig_v(ti);
    for(int l=a,r=b;l<r;l>>=1,r>>=1){
      if(l&1)lef_v = merge(lef_v,reflect(l)),l++;
      if(r&1)--r,rig_v = merge(reflect(r),rig_v);
    }
    return merge(lef_v,rig_v);
  }
};
template<class T,class U,class F,class G,class H>
auto make_lseg(std::vector<T> v,T ide1,U ide2,F f,G g,H h){
  return lazy_segment_tree<T,U,F,G,H>(v,ide1,ide2,f,g,h);
}

