void range_affine_range_sum(){
  using namespace std;
  std::cin.tie(nullptr);
  std::ios_base::sync_with_stdio(false);
  constexpr char newl = '\n';

  struct ushi{
    mint val;
    int sz;
    ushi():val(),sz(1){}
    ushi(mint v,int s):val(v),sz(s){}
  };
  struct tapu{
    mint a,b;
    tapu():a(1),b(){}
    tapu(mint aa,mint bb):a(aa),b(bb){}
    bool operator == (const tapu& other)const{
      return a==other.a and b==other.b;
    }
  };
  auto f = [](ushi lhs,ushi rhs){
    auto&[a,b]=lhs;auto&[c,d]=rhs;
    return ushi(a+c,b+d);
  };
  auto g = [](ushi lhs,tapu rhs){
    auto&[val,sz]=lhs;auto&[a,b]=rhs;
    return ushi(val*a+b*sz,sz);
  };
  auto h = [](tapu lhs,tapu rhs){
    auto&[a,b]=lhs;auto&[c,d]=rhs;
    return tapu(a*c,b*c+d);
  };
  int n,q;
  cin>>n>>q;
  vector<ushi> a(n);
  for(int i=0;i<n;++i)cin>>a[i].val;
  auto seg = make_lseg<ushi,tapu>(a,ushi(),tapu(),f,g,h);
  while(q--){
    int com;cin>>com;
    if(com==0){
      int l,r,b,c;cin>>l>>r>>b>>c;
      seg.update(l,r,{b,c});
    }
    if(com==1){
      int l,r;cin>>l>>r;
      ushi res = seg.fold(l,r);
      cout<<res.val<<newl;
    }
  }
}

