template <typename X, typename M>
struct SegTreeLazyProportional {
    using FX = function<X(X, X)>;
    using FA = function<X(X, M, int)>;
    using FM = function<M(M, M)>;
    //using FP = function<M(M, int)>;
    int n;
    FX fx;
    FA fa;
    FM fm;
    //FP fp;
    const X ex;
    const M em;
    vector<X> dat;
    vector<M> lazy;
    SegTreeLazyProportional(int n_, FX fx_, FA fa_, FM fm_, X ex_, M em_)
        : n(), fx(fx_), fa(fa_), fm(fm_), ex(ex_), em(em_), dat(n_ * 4, ex), lazy(n_ * 4, em) {
        int x = 1;
        while (n_ > x) x *= 2;
        n = x;
    }
    void set(int i, X x) { dat[i + n - 1] = x; }
    void build() {
        for (int k = n - 2; k >= 0; k--) dat[k] = fx(dat[2 * k + 1], dat[2 * k + 2]);
    }
    /* lazy eval */
    void eval(int k, int len) {
        if (lazy[k] == em) return;  // 更新するものが無ければ終了
        if (k < n - 1) {            // 葉でなければ子に伝搬
            lazy[k * 2 + 1] = fm(lazy[k * 2 + 1], lazy[k]);
            lazy[k * 2 + 2] = fm(lazy[k * 2 + 2], lazy[k]);
        }
        // 自身を更新
        dat[k] = fa(dat[k],lazy[k],len);//fa(dat[k], fp(lazy[k], len));
        lazy[k] = em;
    }
    void update(int a, int b, M x, int k, int l, int r) {
        eval(k, r - l);
        if (a <= l && r <= b) {  // 完全に内側の時
            lazy[k] = fm(lazy[k], x);
            eval(k, r - l);
        } else if (a < r && l < b) {                     // 一部区間が被る時
            update(a, b, x, k * 2 + 1, l, (l + r) / 2);  // 左の子
            update(a, b, x, k * 2 + 2, (l + r) / 2, r);  // 右の子
            dat[k] = fx(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    void update(int a, int b, M x) { update(a, b, x, 0, 0, n); }
    X query_sub(int a, int b, int k, int l, int r) {
        eval(k, r - l);
        if (r <= a || b <= l) {  // 完全に外側の時
            return ex;
        } else if (a <= l && r <= b) {  // 完全に内側の時
            return dat[k];
        } else {  // 一部区間が被る時
            X vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
            X vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
            return fx(vl, vr);
        }
    }
    X query(int a, int b) { return query_sub(a, b, 0, 0, n); }
};
int main(){
    int n,q;cin >> n >>q;
    auto fx=[](pl a,pl b){return make_pair((a.fi+b.fi)%MOD9,(a.se+b.se)%MOD9);};
    auto fa=[](pl a,pl b,int len){return make_pair((a.fi+a.se)*b.fi%MOD9,b.se*len%MOD9);};
    auto fm=[](pl a,pl b){return make_pair(a.fi*b.fi%MOD9,(a.se*b.fi+b.se)%MOD9);};
    SegTreeLazyProportional<pl,pl> st(n,fx,fa,fm,make_pair(0,0),make_pair(1,0));
    rep(i,n){
        ll a;cin >> a;
        st.set(i,make_pair(a,0LL));
    }
    st.build();
    while(q--){
        ll t;cin >> t;
        if(t){
            ll l,r;cin >> l >>r;
            pl p=st.query(l,r);
            cout << (p.fi+p.se)%MOD9 <<endl;
        }
        else{
            ll l,r;cin >> l >>r;
            ll a,b;cin >> a >> b;
            st.update(l,r,{a,b});
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define fr(i,j,k) for(int i=j;i<k;i++)
