		template <class F> auto operator()(F&& f) {
			return Callable([&](auto v) {
				for (const auto& i : v) {
					f(i);
				}
			});
		}
	} Each;
	struct Select_impl {
		template <class F> auto operator()(F&& f) {
			return Callable([&](auto v) {
				using value_type = typename decltype(v)::value_type;
				vector<value_type> res;
				for (const auto& i : v) {
					if (f(i)) res.push_back(i);
				}
				return res;
			});
		}
	} Select;
	struct Map_impl {
		template <class F> auto operator()(F&& f) {
			return Callable([&](auto v) {
				using result_type = invoke_result_t<F, typename decltype(v)::value_type>;
				vector<result_type> res;
				res.reserve(size(v));
				for (const auto& i : v) {
					res.push_back(f(i));
				}
				return res;
			});
		}
	} Map;
	struct Indexed_impl {
		template <class T> friend auto operator|(const T& v, Indexed_impl& c) {
			using value_type = typename T::value_type;
			vector<pair<value_type, int>> res;
			res.reserve(size(v));
			int index = 0;
			for (const auto& i : v) {
				res.emplace_back(i, index++);
			}
			return res;
		}
	} Indexed;
	struct AllOf_impl {
		template <class F> auto operator()(F&& f) {
			return Callable([&](auto v) {
				for (const auto& i : v) {
					if (!f(i)) return false;
				}
				return true;
			});
		}
	} AllOf;
	struct AnyOf_impl {
		template <class F> auto operator()(F&& f) {
			return Callable([&](auto v) {
				for (const auto& i : v) {
					if (f(i)) return true;
				}
				return false;
			});
		}
	} AnyOf;
	struct NoneOf_impl {
		template <class F> auto operator()(F&& f) {
			return Callable([&](auto v) {
				for (const auto& i : v) {
					if (f(i)) return false;
				}
				return true;
			});
		}
	} NoneOf;

