struct S {
	mint a;
	int size;
};
struct F {
	mint b, c;
};
S op(S a, S b) {
	return S{a.a + b.a, a.size + b.size};
}
S e() {
	return S{0, 0};
}
S mapping(F f, S x) {
	return S{f.b * x.a + f.c * x.size, x.size};
}
F composition(F g, F f) {
	return F{f.b * g.b, f.c * g.b + g.c};
}
F id() {
	return F{1, 0};
}

int main() {
	ini(n, q);
	VM a = in[n];
	auto s = a | Map([&](mint i) {
		         return S{i, 1};
	         });

	atcoder::lazy_segtree<S, op, e, F, mapping, composition, id> seg(s);
	rep(_, q) {
		int com = in;
		if (com == 0) {
			ini(l, r, b, c);
			seg.apply(l, r, F{b, c});
		} else {
			ini(l, r);
			out(seg.prod(l, r).a);
		}
	}
