      setN(maxN);
    }
  }
  void free(void){
    delete [] val;
    delete [] fun;
  }
  SVAL& operator[](int i){
    return val[N+i];
  }
  void setN(int n, int zerofill = 1, int dobuild = 1){
    int i;
    for(i=1,logN=0;i<n;i*=2,logN++){
      ;
