template <int mxn> struct UF {
	int fa[mxn], rk[mxn];
	UF() { rep(i, mxn) fa[i] = i, rk[i] = 1; }
	int find(int x) { return x == fa[x] ? x : fa[x] = find(fa[x]); }
	void merge(int x, int y) {
		x = find(x); y = find(y);
		if (x == y) return ;
		if (rk[x] < rk[y]) fa[x] = y;
		else fa[y] = x, rk[x] += rk[x] == rk[y];
	}
};

template <typename T, int mxn> struct BIT {
	T s[mxn + 5];
	void upd(int x, T v) { for (++ x; x < mxn + 5; x += x & -x) s[x] = s[x] + v; }
	T qry(int x) { T ans = T(); for (++ x; x; x -= x & -x) ans = ans + s[x]; return ans; }
	T qry(int l, int r) { if (l >= r) return T(); return qry(r - 1) - qry(l - 1); }
};

template <typename T, int mxn> struct BITR {
	T s0[mxn + 5], s1[mxn + 5];
	void upd(int x, T v) { int ox = x; for (++ x; x < mxn + 5; x += x & -x) s0[x] = s0[x] + v, s1[x] = s1[x] + 1LL * ox * v; }
	T qry(int x) { T ans = T(); int ox = x; for (++ x; x; x -= x & -x) ans = ans + (s0[x] * (ox + 1) - s1[x]); return ans; }
	void upd(int l, int r, T v) { if (l >= r) return ; upd(l, v); upd(r, -v); }
	void qry(int l, int r) { if (l >= r) return T(); return qry(r - 1) - qry(l - 1); }
};

template <typename T, int mxn> struct SEG {
	T va[mxn << 1];
	void pushup(int x) {
		va[x] = va[x << 1] + va[x << 1 | 1];
	}
	void init(T *a, int n) {
		rep(i, n) va[i + mxn] = a[i];
		for (int i = mxn - 1; i; -- i) pushup(i);
	}
	void set(int x, T v) {
		va[x += mxn] = v;
		while (x >>= 1) pushup(x);
	}
	T get(int x) {
		return va[x + mxn];
	}
	T qry(int l, int r) {
		if (l >= r) return T();
		T L = T(), R = T();
		for (l += mxn, r += mxn; l < r; l >>= 1, r >>= 1) {
			if (l & 1) L = L + va[l ++];
			if (r & 1) R = va[-- r] + R;
		}
		return L + R;
	}
};

template <typename T0, typename T1, int mxn> struct SEGR {
	T0 va[mxn << 1]; T1 tag[mxn << 1]; int k;
	SEGR() { k = __builtin_ctz(mxn); }
	void push(int x, T1 v) {
		va[x] = va[x] + v;
		tag[x] = tag[x] + v;
	}
	void pushdown(int x) {
		push(x << 1, tag[x]);
		push(x << 1 | 1, tag[x]);
		tag[x] = T1();
	}
	void pushup(int x) {
		va[x] = va[x << 1] + va[x << 1 | 1];
	}
	void init(T0 *a, int n) {
		rep(i, n) va[i + mxn] = a[i];
		for (int i = mxn - 1; i; -- i) pushup(i);
	}
	void set(int x, T0 v) {
		x += mxn;
		for (int i = k; i; -- i) pushdown(x >> i);
		va[x] = v;
		while (x >>= 1) pushup(x);
	}
	T0 get(int x) {
		x += mxn;
		for (int i = k; i; -- i) pushdown(x >> i);
		return va[x];
	}
	void upd(int l, int r, T1 v) {
		if (l >= r) return ;
		l += mxn, r += mxn;
		for (int i = k; i >= 1; -- i) {
			if (((l >> i) << i) != l) pushdown(l >> i);
			if (((r >> i) << i) != r) pushdown(r >> i);
		}
		int l0 = l, r0 = r;
		for (; l < r; l >>= 1, r >>= 1) {
			if (l & 1) push(l ++, v);
			if (r & 1) push(-- r, v);
		}
		for (int i = 1; i <= k; ++ i) {
			if (((l0 >> i) << i) != l0) pushup(l0 >> i);
			if (((r0 >> i) << i) != r0) pushup(r0 >> i);
		}
	}
	T0 qry(int l, int r) {
		if (l >= r) return T0();
		l += mxn, r += mxn;
		for (int i = k; i >= 1; -- i) {
			if (((l >> i) << i) != l) pushdown(l >> i);
			if (((r >> i) << i) != r) pushdown(r >> i);
		}
		T0 L = T0(), R = T0();
		for (; l < r; l >>= 1, r >>= 1) {
			if (l & 1) L = L + va[l ++];
			if (r & 1) R = va[-- r] + R;
		}
		return L + R;
	}
};

