int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }

int exgcd(int a, int b, int &x, int &y) {
	if (b == 0) { x = 1; y = 0; return a; }
	else { int d = exgcd(b, a % b, y, x); y -= a / b * x; return d; }
}

template <int mod> struct rem {
	int v;
	rem(int v = 0, bool fl = 0) { if (fl) { v %= mod; if (v < 0) v += mod; } this->v = v; }
	friend rem operator += (rem &a, const rem &b) { a.v += b.v; if (a.v >= mod) a.v -= mod; return a; }
	friend rem operator -= (rem &a, const rem &b) { a.v -= b.v; if (a.v < 0) a.v += mod; return a; }
	friend rem operator *= (rem &a, const rem &b) { a.v = 1LL * a.v * b.v % mod; return a; }
	friend rem operator /= (rem &a, const rem &b) { a.v = 1LL * a.v * inv(b).v % mod; return a; }
	friend rem qp(rem x, int n) { rem ans = 1; for (; n; n >>= 1, x *= x) if (n & 1) ans *= x; return ans; }
	friend rem inv(rem v) { int x, y; exgcd(v, mod, x, y); return rem(x, 1); }
	friend rem operator + (rem a, const rem &b) { return a += b; }
	friend rem operator - (rem a, const rem &b) { return a -= b; }
	friend rem operator * (rem a, const rem &b) { return a *= b; }
	friend rem operator / (rem a, const rem &b) { return a /= b; }
	friend rem operator - (const rem &a) { return rem(mod - a.v); }
	operator int () { return v; }
};

