using S = pair<int64_t, int64_t>;
using F = pair<int64_t, int64_t>;

constexpr int64_t mod = 998244353;

S op(S a, S b) {
    return {(a.first + b.first) % mod, a.second + b.second};
}

S e() {
    return {0, 0};
}

S f(F p, S x) {
    return {(p.first * x.first + p.second * x.second) % mod, x.second};
}

F comp(F g, F h) {
    return {g.first * h.first % mod, (g.first * h.second + g.second) % mod};
}

F id() {
    return {1, 0};
}

