void solve(){
  int N,Q;
  cin >> N >> Q;

  vector<mint> a(N);
  REP(i,N) cin >> a[i];

  auto f = [](mint a, mint b){return a+b;};
  auto g = [](mint a, P b, int len){return a*b.fs+b.sc*len;};
  auto h = [](P a, P b){return P(a.fs*b.fs,a.sc*b.fs+b.sc);};
  SegmentTree<mint,P,decltype(f), decltype(g), decltype(h)> seg(f,g,h,0,P(1,0));
  seg.build(a);

  REP(_,Q){
    int q; cin >> q;
    if(!q){
      int l,r,b,c;
      cin >> l >> r >> b >> c;
      seg.update(l,r,P(b,c));
    }
    else{
      int l,r;
      cin >> l >> r;
      cout << seg.query(l,r) << "\n";
    }
  }
}

signed main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int T = 1;
  // cin >> T;

  while(T--) solve();

  return 0;
}

