template <typename T,typename E>
struct LazySegmentTree{
    typedef function<T(T,T)> F;
    typedef function<T(T,E)> G;
    typedef function<E(E,E)> H;
    typedef function<pair<ll,ll>(E,int)> P;
    int n;
    F f;
    G g;
    H h;
    P p;
    T d1;
    E d0;
    vector<T> val;
    vector<E> lazy;

    LazySegmentTree(vector<T> a, F f_, G g_, H h_, T d1_, E d0_, P p_=[](E a,int b){return a;}):
        f(f_),g(g_),h(h_),d1(d1_),d0(d0_),p(p_){

        int sz = a.size();
        n = 1;
        while (n < sz) n <<= 1;
        val.clear();
        val.resize(2 * n - 1, d1);
        lazy.clear();
        lazy.resize(2 * n - 1, d0);
        for (int i = 0; i < sz; i++) val[i + n - 1] = a[i];
        for (int i = n - 2; i >= 0; i--) val[i] = f(val[i * 2 + 1], val[i * 2 + 2]);
    }

    inline void eval(int k, int len){
        if(lazy[k] == d0) return;

        if(2*k+1 < 2*n-1){
            lazy[2*k+1] = h(lazy[2*k+1], lazy[k]);
            lazy[2*k+2] = h(lazy[2*k+2], lazy[k]);
        }
        val[k] = g(val[k], p(lazy[k], len));
        lazy[k] = d0;
    }

    void update(int a, int b, E x, int k=0, int l=0, int r=-1){
        // 0-indexed
        // [a,b)に対して操作
        if(r < 0) r = n;
        eval(k, r-l);
        if(r <=a || b <= l) return;

        if(a <= l && r <= b){
            lazy[k] = h(lazy[k], x);
            eval(k, r-l);
        }
        else{
            update(a, b, x, 2*k+1, l, (l+r)/2);
            update(a, b, x, 2*k+2, (l+r)/2, r);
            val[k] = f(val[2*k+1], val[2*k+2]);
        }
    }

    T query(int a, int b, int k=0, int l=0, int r=-1){
        // 0-indexed
        // [a,b)に対してquery
        if(r < 0) r = n;
        eval(k, r-l);
        if(r <= a || b <= l) return d1;
        if(a <= l && r <= b) return val[k];
        T val_l = query(a, b , 2*k+1, l, (l+r)/2);
        T val_r = query(a, b , 2*k+2, (l+r)/2, r);
        return f(val_l, val_r);
    }

    int findL(int a, int b, const function<bool(T)>& check, int k=0, int l=0, int r=-1){
        // 0-indexed
        // [a,b)でf(val[k])がtrueとなるような最小のkを返す 無ければ-1を返す
        // a      k         b
        // xxxxxxxoooooooooo

        if(r<0) r = n;
        eval(k, r-l);
        if(!check(val[k]) || (r<=a || b<=l)) return -1;
        if(r-l == 1) return l;

        int lv = findL(a, b, check, 2*k+1, l, (l+r)/2);
        if(lv != -1) return lv;

        int rv = findL(a, b, check, 2*k+2, (l+r)/2, r);
        return rv;
    }

    int findR(int a, int b, const function<bool(T)>& check, int k=0, int l=0, int r=-1){
        // 0-indexed
        // [a,b)でf(val[k])がtrueとなるような最大のkを返す 無ければ-1を返す
        // a      k         b
        // ooooooooxxxxxxxxx

        if(r<0) r = n;
        eval(k, r-l);
        if(!check(val[k]) || (r<=a || b<=l)) return -1;
        if(r-l == 1) return l;

        int rv = findR(a, b, check, 2*k+2, (l+r)/2, r);
        if(rv != -1) return rv;

        int lv = findR(a, b, check, 2*k+1, l, (l+r)/2);
        return lv;
    }
};

ll f(ll a, ll b){return (a+b)%MOD;}
ll g(ll a, pair<ll,ll> b){
    ll x = b.first, y = b.second;
    return (x*a + y) % MOD;
}
pair<ll,ll> h(pair<ll,ll> a, pair<ll,ll> b){
    return pair<ll,ll>((a.first*b.first)%MOD, (b.first*a.second+b.second)%MOD);
}
pair<ll,ll> p(pair<ll,ll> a, int b){
    return pair<ll,ll>(a.first, (a.second*b)%MOD);
}

void Main(){
    int N,Q; cin >> N >> Q;
    VL A(N); REP(i,N) cin >> A[i];

    LazySegmentTree<ll,pair<ll,ll>> st(A,f,g,h,0,pair<ll,ll>(1,0),p);
    REP(_,Q){
        int t,l,r; cin >> t >> l >> r;
        if(t == 0){
            ll b,c; cin >> b >> c;
            st.update(l,r,pair<ll,ll>(b,c));
        }
        else{
            ll ans = st.query(l,r);
            cout << ans << en;
        }
    }
    return;
}

