using namespace std;

int MAX_N=131072*4;
int64_t Null=0;//初期値
int64_t Q=998244353;
vector<int64_t> seg(MAX_N*2-1,Null);
vector<int64_t> lazy(MAX_N*2-1,Q);
vector<int64_t> p(MAX_N*2-1,Null);
void eval(int k){
  if(lazy[k]==Q){
    return;
  }
  int64_t A=lazy[k]/Q,B=lazy[k]%Q;
  if(k<MAX_N-1){//子への伝播
    int64_t Ai,Bi;
    Ai=lazy[k*2+1]/Q,Bi=lazy[k*2+1]%Q;
    lazy[k*2+1]=((Ai*A)%Q)*Q+(Bi*A+B)%Q;//change
    Ai=lazy[k*2+2]/Q,Bi=lazy[k*2+2]%Q;
    lazy[k*2+2]=((Ai*A)%Q)*Q+(Bi*A+B)%Q;//change
  }
  seg[k]*=A;
  seg[k]%=Q;//change
  seg[k]+=(B*p[k]);
  seg[k]%=Q;
  lazy[k]=Q;
}

int64_t qu_s(int a,int b,int k,int l, int r){
  eval(k);
  if(r<=a||b<=l){
    return 0;//change
  }
  else if(a<=l&&r<=b){
    return seg[k];
  }
  else{
    int64_t X=qu_s(a,b,k*2+1,l,(l+r)/2);
    int64_t Y=qu_s(a,b,k*2+2,(l+r)/2,r);
    return (X+Y)%Q;//change
  }
}
int64_t qu(int a,int b){
  return qu_s(a,b,0,0,MAX_N);
}

void chran_s(int64_t c,int a,int b,int k,int l, int r){
  eval(k);
  if(r<=a||b<=l){
    return;
  }
  else if(a<=l&&r<=b){
    lazy[k]=c;
    eval(k);
    while(k>0){//親への伝播
      k--;
      k/=2;
      eval(k);
      eval(2*k+1);
      eval(2*k+2);
      seg[k]=(seg[2*k+1]+seg[2*k+2])%Q;//change
    }
  }
  else{
    chran_s(c,a,b,k*2+1,l,(l+r)/2);
    chran_s(c,a,b,k*2+2,(l+r)/2,r);
  }
}
void chran(int64_t c,int a,int b){
  chran_s(c,a,b,0,0,MAX_N);
}

int main(){
  int N,K;
  cin>>N>>K;
  p[0]=MAX_N;
  for(int i=0;i<MAX_N-1;i++){
    p[i*2+1]=p[i]/2;
    p[i*2+2]=p[i]/2;
  }
  for(int i=0;i<N;i++){
    cin>>seg[i-1+MAX_N];
  }
  for(int i=MAX_N-2;i>=0;i--){
    seg[i]=(seg[2*i+1]+seg[i*2+2])%Q;
  }
  for(int i=0;i<K;i++){
    int p,l,r;
    cin>>p>>l>>r;
    if(p){
      cout<<qu(l,r)<<endl;
    }
    else{
      int64_t b,c;
      cin>>b>>c;
      int64_t d=b*Q+c;
      chran(d,l,r);
    }
  }
}

