    ll N, Q;
    cin >> N >> Q;

    auto fop = [](P a, P b) { return P(a.first + b.first, a.second + b.second); };
    auto fac = [](P a, P f) { return P(a.first * f.first + f.second * a.second, a.second); };
    auto fme = [](P f, P g) { return P(f.first * g.first, f.second * g.first + g.second); };
    LazySegTree<P> seg(N, P(0, 1), P(1, 0), fop, fac, fme);

    vc<P> A(N, P(0, 1));
    rep(i, N) {
        ll a;
