struct X {
    mint val, size;
};
struct F {
    mint b, c;
};
X f(X x, X y) { return X{x.val + y.val, x.size + y.size}; };
X g(X x, F ff) { return X{x.size * ff.c + x.val * ff.b, x.size}; };
F h(F ff, F gg) { return F{ff.b * gg.b, ff.c * gg.b + gg.c}; };

