int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(nullptr);

	int n, q;
	std::cin >> n >> q;
	std::vector<sum> node;
	for (int i = 0; i < n; i++) {
		modint<MOD> value;
		std::cin >> value;
		node.emplace_back(value, 1);
	}

	auto f = [](const sum &a, const sum &b) {
		return sum(a.first + b.first, a.second + b.second);
	};
	auto g = [](const sum &a, const affine &b) {
		return sum(a.first * b.first + b.second * a.second, a.second);
	};
	auto h = [](const affine &a, const affine &b) {
		return affine(a.first * b.first, a.second * b.first + b.second);
	};

	auto seg = make_lazysegtree(node.begin(), node.end(), sum(0, 0), affine(1, 0), f, g, h);

	while (q--) {
