struct RUMQ {
    static const ll n = 1LL << 20;
    vector<ll> node, flag;

    using P = pair<ll, ll>;
    P e = mp(1, 0);
    vector<P> lazy;

    function<P(P, P)> comb = [](P a, P b) {
        return P{(a.fi * b.fi) % mod, (a.se * b.fi + b.se) % mod};
    };
    function<ll(ll, ll)> f = [](ll a, ll b) { return (a + b) % mod; };
    function<ll(ll, P)> g = [](ll a, P b) { return (a * b.fi + b.se) % mod; };

    RUMQ() : node(n * 2 - 1), flag(n * 2 - 1), e({1, 0}), lazy(n * 2 - 1, e) {}
    inline void eval(ll i, ll l, ll r) {
        if (flag[i]) {
            node[i] = g(node[i], lazy[i]);
            if (r - l > 1) {
                lazy[i * 2 + 1] =
                    comb(lazy[i * 2 + 1], P{lazy[i].fi, lazy[i].se * inv(2, mod) % mod});
                lazy[i * 2 + 2] =
                    comb(lazy[i * 2 + 2], P{lazy[i].fi, lazy[i].se * inv(2, mod) % mod});
                flag[i * 2 + 1] = flag[i * 2 + 2] = true;
            }
            lazy[i] = e;
            flag[i] = false;
        }
    }
    inline void update(ll a, ll b, P x, ll i = 0, ll l = 0, ll r = n) {
        eval(i, l, r);
        if (b <= l || r <= a) return;
        if (a <= l && r <= b) {
            lazy[i] = comb(lazy[i], P{x.fi, x.se * (r - l) % mod});
            flag[i] = true;
            eval(i, l, r);
        } else {
            update(a, b, x, i * 2 + 1, l, (l + r) / 2);
            update(a, b, x, i * 2 + 2, (l + r) / 2, r);
            node[i] = f(node[i * 2 + 1], node[i * 2 + 2]);
        }
    }
    inline ll fold(ll a, ll b, ll i = 0, ll l = 0, ll r = n) {
        if (b <= l || r <= a) return 0;
        eval(i, l, r);
        if (a <= l && r <= b) return node[i];
        return f(fold(a, b, i * 2 + 1, l, (l + r) / 2), fold(a, b, i * 2 + 2, (l + r) / 2, r));
    }
} seg;

