// LazySegmentTree
template <typename T, typename E, typename F, typename G, typename H>
struct LST {
  int n, height;
  F f;
  G g;
  H h;
  T ti;
  E ei;
  vector<T> dat;
  vector<E> laz;
  LST(int n, F f, G g, H h, T ti, E ei) : f(f), g(g), h(h), ti(ti), ei(ei) {
    init(n);
  }
  LST(const vector<T> &v, F f, G g, H h, T ti, E ei)
      : f(f), g(g), h(h), ti(ti), ei(ei) {
    init((int)v.size());
    build(v);
  }

  void init(int n_) {
    n = 1;
    height = 0;
    while (n < n_) n <<= 1, height++;
    dat.assign(2 * n, ti);
    laz.assign(2 * n, ei);
  }
  void build(const vector<T> &v) {
    int n_ = v.size();
    init(n_);
    for (int i = 0; i < n_; i++) dat[n + i] = v[i];
    for (int i = n - 1; i; i--)
      dat[i] = f(dat[(i << 1) | 0], dat[(i << 1) | 1]);
  }
  inline T reflect(int k) { return laz[k] == ei ? dat[k] : g(dat[k], laz[k]); }
  inline void eval(int k) {
    if (laz[k] == ei) return;
    laz[(k << 1) | 0] = h(laz[(k << 1) | 0], laz[k]);
    laz[(k << 1) | 1] = h(laz[(k << 1) | 1], laz[k]);
    dat[k] = reflect(k);
    laz[k] = ei;
  }
  inline void thrust(int k) {
    for (int i = height; i; i--) eval(k >> i);
  }
  inline void recalc(int k) {
    while (k >>= 1) dat[k] = f(reflect((k << 1) | 0), reflect((k << 1) | 1));
  }
  void update(int a, int b, E x) {
    if (a >= b) return;
    thrust(a += n);
    thrust(b += n - 1);
    for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
      if (l & 1) laz[l] = h(laz[l], x), l++;
      if (r & 1) --r, laz[r] = h(laz[r], x);
    }
    recalc(a);
    recalc(b);
  }
  void set_val(int a, T x) {
    thrust(a += n);
    dat[a] = x;
    laz[a] = ei;
    recalc(a);
  }
  T query(int a, int b) {
    if (a >= b) return ti;
    thrust(a += n);
    thrust(b += n - 1);
    T vl = ti, vr = ti;
    for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
      if (l & 1) vl = f(vl, reflect(l++));
      if (r & 1) vr = f(reflect(--r), vr);
    }
    return f(vl, vr);
  }
};

int main() {
  int N, Q;
  rd(N, Q);
  using mint = LazyMontgomeryModInt<998244353>;
  struct affine {
    mint a, b;
    affine() {}
    affine(mint a_, mint b_) : a(a_), b(b_) {}
    bool operator==(const affine& other) {
      return a == other.a && b == other.b;
    }
  };
  auto f = [](affine a, affine b) { return affine{a.a + b.a, a.b + b.b}; };
  auto g = [](affine a, affine b) {
    return affine{a.a * b.a + a.b * b.b, a.b};
  };
  auto h = [](affine a, affine b) {
    return affine{a.a * b.a, a.b * b.a + b.b};
  };

  vector<affine> v(N);
  for (int i = 0; i < N; i++) {
    int n;
    rd(n);
    v[i] = affine{n, 1};
  }

  LST<affine, affine, decltype(f), decltype(g), decltype(h)> seg(
      v, f, g, h, affine{0, 0}, affine{1, 0});

  while (Q--) {
    int cmd;
    rd(cmd);
    if (cmd) {
      int l, r;
      rd(l, r);
      wtn(seg.query(l, r).a.get());
    } else {
      int l, r, b, c;
      rd(l, r, b, c);
      seg.update(l, r, affine{b, c});
    }
  }
}

