using namespace atcoder;

using mint = modint998244353;

struct S { mint value; mint length; };
S op(S x, S y) { return S{ x.value + y.value, x.length + y.length }; }
S e() { return S{ 0, 0 }; }
// S e() { return S{ 0, 0 }; }
struct F { mint b; mint c; }; // 写像f(x)=bx+c を F{b,c} で表す
S mapping(F f, S x) {
	auto [b, c] = f;
	return S{ b * x.value + c * x.length, x.length };
}
// f(x)=b1x+c1, g(x)=b2x+c2 のとき f○g(x)=f(g(x))=b1(b2x+c2)+c1=(b1b2)x+(b1c2+c1)
F composition(F f, F g) {
	auto [b1, c1] = f; auto [b2, c2] = g;
	return F{ b1 * b2, b1 * c2 + c1 };
}
F id() { return F{ 1, 0 }; }

int N;

void show(lazy_segtree<S, op, e, F, mapping, composition, id> s) {
	cout << endl << "[";
	rep(i, N) {
		cout << s.get(i).value.val() << ", ";
	}
	cout << "]" << endl;
}

int main() {
	int Q; cin >> N >> Q;
	vector<S> a(N);
	rep(i, N) {
		int a_value; cin >> a_value;
		a[i] = S{ a_value, 1 }; //
	}
	lazy_segtree<S, op, e, F, mapping, composition, id> s(a);
	while (Q--) {
		int q; cin >> q;
		if (q == 0) {
			int l, r, b, c; cin >> l >> r >> b >> c;
			s.apply(l, r, F{ b, c });
		} else if (q == 1) {
			int l, r; cin >> l >> r;
			cout << s.prod(l, r).value.val() << endl;
		}
		// show(s);
	}
}

