template<typename Monoid, typename Operator_Monoid>
struct Lazy_Segment_Tree{
    vector<Monoid> seg;
    vector<Operator_Monoid> lazy;
    const Monoid e1;
    const Operator_Monoid e2;
    const int n;

    Monoid f(const Monoid &a, const Monoid &b) const {return a+b;}

    Monoid g(const Monoid &a, const Operator_Monoid &b) const{
        return a*b.x + b.y;
    }

    Operator_Monoid h(const Operator_Monoid &a, const Operator_Monoid &b) const{
        return {a.x*b.x, a.y*b.x + b.y};
    }

    Lazy_Segment_Tree(int N, const Monoid &e1, const Operator_Monoid &e2)
        : e1(e1), e2(e2), n(1<<(32-__builtin_clz(N-1))){
        seg.assign(2*n, e1), lazy.assign(2*n, e2);
    }

    void set(int i, const Monoid &x) {seg[n+i] = x;}

    void build(){
        rep3(i, n-1, 1) seg[i] = f(seg[2*i], seg[2*i+1]);
    }

    void init(int N, const Monoid &x){
        rep(i, N) set(i, x);
        build();
    }

    void eval(int i, int l, int r){
        if(lazy[i] != e2){
            //seg[i] = g(seg[i], lazy[i]*(r-l));
            Monoid memo = lazy[i].y;
            lazy[i].y *= r-l;
            seg[i] = g(seg[i], lazy[i]);
            lazy[i].y = memo;
            if(r-l > 1){
                lazy[2*i] = h(lazy[2*i] ,lazy[i]);
                lazy[2*i+1] = h(lazy[2*i+1], lazy[i]);
            }
            lazy[i] = e2;
        }
    }

    void add(int a, int b, const Operator_Monoid &x, int i, int l, int r){
        eval(i, l, r);
        if(a >= r || b <= l) return;
        if(a <= l && r <= b){
            lazy[i] = h(lazy[i], x);
            eval(i, l, r);
        }
        else{
            add(a, b, x, 2*i, l, (l+r)/2);
            add(a, b, x, 2*i+1, (l+r)/2, r);
            seg[i] = f(seg[2*i], seg[2*i+1]);
        }
    }

    void add(int a, int b, const Operator_Monoid &x) {add(a, b, x, 1, 0, n);}

    Monoid query(int a, int b, int i, int l, int r){
        eval(i, l, r);
        if(a >= r || b <= l) return e1;
        if(a <= l && r <= b) return seg[i];
        Monoid vl = query(a, b, 2*i, l, (l+r)/2);
        Monoid vr = query(a, b, 2*i+1, (l+r)/2, r);
        return f(vl, vr);
    }

    Monoid query(int a, int b) {return query(a, b, 1, 0, n);}

    void update(int i, int l, int r){
        seg[i] = g(seg[i], lazy[i]);
        if(r-l > 1){
            lazy[2*i] = h(lazy[2*i], lazy[i]);
            lazy[2*i+1] = h(lazy[2*i+1], lazy[i]);
            update(2*i, l, (l+r)/2);
            update(2*i+1, (l+r)/2, r);
        }
        lazy[i] = e2;
    }

    void update() {update(1, 0, n);}

    Monoid operator [] (int i) const {return seg[n+i];}

    void clear(){
        fill(all(seg), e1), fill(all(lazy), e2);
    }
};

struct Data{
    mint x, y;
    Data(mint x, mint y) : x(x), y(y) {}

    bool operator == (const Data &a) const {return x == a.x && y == a.y;}

    bool operator != (const Data &a) const {return !(*this == a);}
};

int main(){
	ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, Q;
    cin >> N >> Q;
    Lazy_Segment_Tree<mint, Data> seg(N, 0, {1, 0});
    rep(i, N){
        mint a; cin >> a;
        seg.set(i, a);
    }
    seg.build();
    while(Q--){
        int q, l, r; cin >> q >> l >> r;
        if(q == 0){
            mint x, y; cin >> x >> y;
            seg.add(l, r, {x, y});
        }
        else cout << seg.query(l, r) << '\n';
    }
}

