template <class S,
          S (*op)(S, S),
          S (*e)(),
          class F,
          S (*mapping)(F, S),
          F (*composition)(F, F),
          F (*id)()>
struct lazy_segtree {
  public:
    lazy_segtree() : lazy_segtree(0) {}
    lazy_segtree(int n) : lazy_segtree(std::vector<S>(n, e())) {}
    lazy_segtree(const std::vector<S>& v) : _n(int(v.size())) {
        log = internal::ceil_pow2(_n);
        size = 1 << log;
        d = std::vector<S>(2 * size, e());
        lz = std::vector<F>(size, id());
        for (int i = 0; i < _n; i++) d[size + i] = v[i];
        for (int i = size - 1; i >= 1; i--) {
            update(i);
        }
    }

    void set(int p, S x) {
        assert(0 <= p && p < _n);
        p += size;
        for (int i = log; i >= 1; i--) push(p >> i);
        d[p] = x;
        for (int i = 1; i <= log; i++) update(p >> i);
    }

    S get(int p) {
        assert(0 <= p && p < _n);
        p += size;
        for (int i = log; i >= 1; i--) push(p >> i);
        return d[p];
    }

    S prod(int l, int r) {
        assert(0 <= l && l <= r && r <= _n);
        if (l == r) return e();

        l += size;
        r += size;

        for (int i = log; i >= 1; i--) {
            if (((l >> i) << i) != l) push(l >> i);
            if (((r >> i) << i) != r) push(r >> i);
        }

        S sml = e(), smr = e();
        while (l < r) {
            if (l & 1) sml = op(sml, d[l++]);
            if (r & 1) smr = op(d[--r], smr);
            l >>= 1;
            r >>= 1;
        }

        return op(sml, smr);
    }

    S all_prod() { return d[1]; }

    void apply(int p, F f) {
        assert(0 <= p && p < _n);
        p += size;
        for (int i = log; i >= 1; i--) push(p >> i);
        d[p] = mapping(f, d[p]);
        for (int i = 1; i <= log; i++) update(p >> i);
    }
    void apply(int l, int r, F f) {
        assert(0 <= l && l <= r && r <= _n);
        if (l == r) return;

        l += size;
        r += size;

        for (int i = log; i >= 1; i--) {
            if (((l >> i) << i) != l) push(l >> i);
            if (((r >> i) << i) != r) push((r - 1) >> i);
        }

        {
            int l2 = l, r2 = r;
            while (l < r) {
                if (l & 1) all_apply(l++, f);
                if (r & 1) all_apply(--r, f);
                l >>= 1;
                r >>= 1;
            }
            l = l2;
            r = r2;
        }

        for (int i = 1; i <= log; i++) {
            if (((l >> i) << i) != l) update(l >> i);
            if (((r >> i) << i) != r) update((r - 1) >> i);
        }
    }

    template <bool (*g)(S)> int max_right(int l) {
        return max_right(l, [](S x) { return g(x); });
    }
    template <class G> int max_right(int l, G g) {
        assert(0 <= l && l <= _n);
        assert(g(e()));
        if (l == _n) return _n;
        l += size;
        for (int i = log; i >= 1; i--) push(l >> i);
        S sm = e();
        do {
            while (l % 2 == 0) l >>= 1;
            if (!g(op(sm, d[l]))) {
                while (l < size) {
                    push(l);
                    l = (2 * l);
                    if (g(op(sm, d[l]))) {
                        sm = op(sm, d[l]);
                        l++;
                    }
                }
                return l - size;
            }
            sm = op(sm, d[l]);
            l++;
        } while ((l & -l) != l);
        return _n;
    }

    template <bool (*g)(S)> int min_left(int r) {
        return min_left(r, [](S x) { return g(x); });
    }
    template <class G> int min_left(int r, G g) {
        assert(0 <= r && r <= _n);
        assert(g(e()));
        if (r == 0) return 0;
        r += size;
        for (int i = log; i >= 1; i--) push((r - 1) >> i);
        S sm = e();
        do {
            r--;
            while (r > 1 && (r % 2)) r >>= 1;
            if (!g(op(d[r], sm))) {
                while (r < size) {
                    push(r);
                    r = (2 * r + 1);
                    if (g(op(d[r], sm))) {
                        sm = op(d[r], sm);
                        r--;
                    }
                }
                return r + 1 - size;
            }
            sm = op(d[r], sm);
        } while ((r & -r) != r);
        return 0;
    }

  private:
    int _n, size, log;
    std::vector<S> d;
    std::vector<F> lz;

    void update(int k) { d[k] = op(d[2 * k], d[2 * k + 1]); }
    void all_apply(int k, F f) {
        d[k] = mapping(f, d[k]);
        if (k < size) lz[k] = composition(f, lz[k]);
    }
    void push(int k) {
        all_apply(2 * k, lz[k]);
        all_apply(2 * k + 1, lz[k]);
        lz[k] = id();
    }
};

struct S {
    mint a;
    int size;
};

struct F {
    mint a, b;
};

S op(S l, S r) { return S{l.a + r.a, l.size + r.size}; }

S e() { return S{0, 0}; }

S mapping(F l, S r) { return S{r.a * l.a + (mint)r.size * l.b, r.size}; }

F composition(F l, F r) { return F{r.a * l.a, r.b * l.a + l.b}; }

F id() { return F{1, 0}; }

int main() {
    int n, q;
    scanf("%d %d", &n, &q);

    vector<S> a(n);
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        a[i] = S{x, 1};
    }

    lazy_segtree<S, op, e, F, mapping, composition, id> seg(a);

    for (int i = 0; i < q; i++) {
        int t;
        scanf("%d", &t);
        if (t == 0) {
            int l, r;
            int c, d;
            scanf("%d %d %d %d", &l, &r, &c, &d);
            seg.apply(l, r, F{c, d});
        } else {
            int l, r;
            scanf("%d %d", &l, &r);
            cout << seg.prod(l, r).a << endl;
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

int MAX_N=131072*4;
int64_t A,B,Ai,Bi;
int64_t Null=0;//初期値
int64_t Q=998244353;
vector<int64_t> seg(MAX_N*2-1,Null);
vector<int64_t> lazy(MAX_N*2-1,Q);
vector<int64_t> p(MAX_N*2-1,Null);
void eval(int k){
  if(lazy[k]==Q){
    return;
  }
  A=lazy[k]/Q,B=lazy[k]%Q;
  if(k<MAX_N-1){//子への伝播
    Ai,Bi;
    Ai=lazy[k*2+1]/Q,Bi=lazy[k*2+1]%Q;
    lazy[k*2+1]=((Ai*A)%Q)*Q+(Bi*A+B)%Q;//change
    Ai=lazy[k*2+2]/Q,Bi=lazy[k*2+2]%Q;
    lazy[k*2+2]=((Ai*A)%Q)*Q+(Bi*A+B)%Q;//change
  }
  seg[k]*=A;
  seg[k]%=Q;//change
  seg[k]+=(B*p[k]);
  seg[k]%=Q;
  lazy[k]=Q;
}

int64_t qu_s(int a,int b,int k,int l, int r){
  eval(k);
  if(r<=a||b<=l){
    return 0;//change
  }
  else if(a<=l&&r<=b){
    return seg[k];
  }
  else{
    int64_t X=qu_s(a,b,k*2+1,l,(l+r)/2);
    int64_t Y=qu_s(a,b,k*2+2,(l+r)/2,r);
    return (X+Y)%Q;//change
  }
}
int64_t qu(int a,int b){
  return qu_s(a,b,0,0,MAX_N);
}

void chran_s(int64_t c,int a,int b,int k,int l, int r){
  eval(k);
  if(r<=a||b<=l){
    return;
  }
  else if(a<=l&&r<=b){
    lazy[k]=c;
    eval(k);
    while(k>0){//親への伝播
      k--;
      k/=2;
      eval(2*k+1);
      eval(2*k+2);
      seg[k]=(seg[2*k+1]+seg[2*k+2])%Q;//change
    }
  }
  else{
    chran_s(c,a,b,k*2+1,l,(l+r)/2);
    chran_s(c,a,b,k*2+2,(l+r)/2,r);
  }
}
void chran(int64_t c,int a,int b){
  chran_s(c,a,b,0,0,MAX_N);
}

int main(){
  int N,K;
  cin>>N>>K;
  p[0]=MAX_N;
  for(int i=0;i<MAX_N-1;i++){
    p[i*2+1]=p[i]/2;
    p[i*2+2]=p[i]/2;
  }
  for(int i=0;i<N;i++){
    cin>>seg[i-1+MAX_N];
  }
  for(int i=MAX_N-2;i>=0;i--){
    seg[i]=(seg[2*i+1]+seg[i*2+2])%Q;
  }
  for(int i=0;i<K;i++){
    int p,l,r;
    cin>>p>>l>>r;
    if(p){
      cout<<qu(l,r)<<endl;
    }
    else{
      int64_t b,c;
      cin>>b>>c;
      int64_t d=b*Q+c;
      chran(d,l,r);
    }
  }
}

