void solve() {
    int n, q;
    std::cin >> n >> q;

    std::vector<mint> xs(n);
    for (auto& x : xs) {
        int a;
        std::cin >> a;
        x = mint::raw(a);
    }

    LazySegmentTree<mint, std::pair<mint, mint>>
        seg(
            xs, 0, std::make_pair(1, 0),
            [](auto a, auto b) { return a + b; },
            [](auto e, auto f) { return std::make_pair(e.first * f.first,
                                                       e.second * f.first + f.second); },
            [](auto a, auto e, int k) { return a * e.first + e.second * k; });

    while (q--) {
        int t;
        std::cin >> t;

        switch (t) {
            case 0: {
                int l, r, _a, _b;
                std::cin >> l >> r >> _a >> _b;
                mint a = mint::raw(_a),
