    segobj& operator=(const T& p) {
        val = p * size;
        return *this;
    }
    friend ostream& operator<<(ostream& os, const segobj& p) {
        return os << p.val;
    }
    segobj operator+(const segobj& p) const { return segobj(*this) += p; }
    segobj operator+(const T& p) const { return segobj(*this) += p; }
};
