signed main() {
	INIT;

	VAR(int, n, Q);
	VEC(int, a, n);

	LazySegmentTree<MonoidOfValue::X, MonoidOfOperator::X, ApplyOperator::X> lst(n);
	REP(i, n) lst.update(i, i + 1, MonoidOfOperator::X::value_type{ 0, a[i] });
	REP(_, Q) {
		VAR(int, t);
		if (t == 0) {
			VAR(int, l, r, b, c);
			lst.update(l, r, MonoidOfOperator::X::value_type{ b, c });
		}
		else {
			VAR(int, l, r);
			OUT(lst.query(l, r))BR;
		}
	}

	return 0;
}

