namespace atcoder {

// Reference:
// B. Aspvall, M. Plass, and R. Tarjan,
// A Linear-Time Algorithm for Testing the Truth of Certain Quantified Boolean
// Formulas
struct two_sat {
  public:
    two_sat() : _n(0), scc(0) {}
    two_sat(int n) : _n(n), _answer(n), scc(2 * n) {}

    void add_clause(int i, bool f, int j, bool g) {
        assert(0 <= i && i < _n);
        assert(0 <= j && j < _n);
        scc.add_edge(2 * i + (f ? 0 : 1), 2 * j + (g ? 1 : 0));
        scc.add_edge(2 * j + (g ? 0 : 1), 2 * i + (f ? 1 : 0));
    }
    bool satisfiable() {
        auto id = scc.scc_ids().second;
        for (int i = 0; i < _n; i++) {
            if (id[2 * i] == id[2 * i + 1]) return false;
            _answer[i] = id[2 * i] < id[2 * i + 1];
        }
        return true;
    }
    std::vector<bool> answer() { return _answer; }

  private:
    int _n;
    std::vector<bool> _answer;
    internal::scc_graph scc;
};

}  // namespace atcoder

#endif  // ATCODER_TWOSAT_HPP
using namespace std; using namespace atcoder;

using mint = modint998244353;

struct S { mint value; mint length; };
S op(S x, S y) { return S{ x.value + y.value, x.length + y.length }; }
S e() { return S{ 0, 0 }; }
// S e() { return S{ 0, 0 }; }
struct F { mint b; mint c; }; // 写像f(x)=bx+c を F{b,c} で表す
S mapping(F f, S x) {
	auto [b, c] = f;
	return S{ b * x.value + c * x.length, x.length };
}
// f(x)=b1x+c1, g(x)=b2x+c2 のとき f○g(x)=f(g(x))=b1(b2x+c2)+c1=(b1b2)x+(b1c2+c1)
F composition(F f, F g) {
	auto [b1, c1] = f; auto [b2, c2] = g;
	return F{ b1 * b2, b1 * c2 + c1 };
}
F id() { return F{ 1, 0 }; }

int N;

int main() {
	int Q; cin >> N >> Q;
	vector<S> a(N);
	for(int i = 0; i < N; i++) {
		int a_value; cin >> a_value;
