template<typename T,typename OT>
struct LinkCutTree{
  using F = function<T(T, T)>;
  using G = function<T(T, OT)>;
  using H = function<OT(OT, OT)>;
  using S = function<T(T)>;
  struct Node{
    Node *p,*l,*r;
    int idx;
    T key, sum;
    OT lazy;
    int sz;
    bool rev;
    bool is_root(){
      return !p || (p->l != this && p->r != this);
    }
    Node(int idx, const T &key,const OT &om):
      idx(idx),key(key),sum(key),lazy(om),sz(1),
      l(nullptr),r(nullptr),p(nullptr),rev(false){}
  };
  const T M1;
  const OT OM0;
  const F f;
  const G g;
  const H h;
  const S s;
  vector<Node *>ver;
  LinkCutTree(int n):
    LinkCutTree(n,[&](T x,T y){return x;},[&](T x){return x;},T()){}
  LinkCutTree(int n,const F &f,const S &s,const T M1):
    LinkCutTree(n,f,G(),H(),s,M1,OT()){}
  LinkCutTree(int n,const F &f,const G &g,const H &h, const S &s,const T M1,const OT OM0)
    :f(f),g(g),h(h),s(s),ver(n),M1(M1),OM0(OM0){}
  void update(Node *t){
    t->sz = 1;
    t->sum = t->key;
    if(t->l)t->sz += t->l->sz, t->sum = f(t->l->sum, t->sum);
    if(t->r)t->sz += t->r->sz, t->sum = f(t->sum, t->r->sum);
  }
  void rotr(Node *t){
    Node *x = t->p, *y = x->p;
    if((x->l = t->r))t->r->p = x;
    t->r = x, x->p = t;
    update(x),update(t);
    if((t->p = y)){
      if(y->l == x)y->l = t;
      if(y->r == x)y->r = t;
      update(y);
    }
  }
  void rotl(Node *t){
    Node *x =t->p, *y = x->p;
    if((x->r = t->l))t->l->p = x;
    t->l = x, x->p = t;
    update(x),update(t);
    if((t->p = y)){
      if(y->l == x)y->l = t;
      if(y->r == x)y->r = t;
      update(y);
    }
  }
  void splay(Node *t){
    push(t);
    while(!t->is_root()){
      Node *q = t->p;
      if(q->is_root()){
        push(q), push(t);
        if(q->l == t)rotr(t);
        else rotl(t);
      }
      else{
        Node *r = q->p;
        push(r), push(q), push(t);
        if(r->l == q){
          if(q->l == t)rotr(q), rotr(t);
          else rotl(t), rotr(t);
        }
        else{
          if(q->r == t)rotl(q), rotl(t);
          else rotr(t), rotl(t);
        }
      }
    }
  }
  Node *expose(Node *t){
    Node *rp = nullptr;
    Node *cur = t;
    while(cur){
      splay(cur);
      cur->r = rp;
      update(cur);
      rp = cur;
      cur = cur->p;
    }
    splay(t);
    return rp;
  }
  void link(Node *child, Node *parent){
    expose(child);
    expose(parent);
    child->p = parent;
    parent->r = child;
    update(parent);
  }
  void cut(Node *child){
    expose(child);
    Node *parent = child->l;
    child->l = nullptr;
    parent->p = nullptr;
    update(child);
  }
  void toggle(Node *t){
    assert(t);
    swap(t->l,t->r);
    t->sum = s(t->sum);
    t->rev^=true;
  }
  void evert(Node *t){
    expose(t);
    toggle(t);
    push(t);
  }
  Node *make_node(int idx,T v = T()){
    return new Node(idx, v, OM0);
  }
  void push(Node *t){
    if(t->lazy != OM0){
      if(t->l)propagate(t->l, t->lazy);
      if(t->r)propagate(t->r, t->lazy);
      t->lazy = OM0;
    }
    if(t->rev){
      if(t->l)toggle(t->l);
      if(t->r)toggle(t->r);
      t->rev=false;
    }
  }
  Node *lca(Node *u, Node *v){
    expose(u);
    return expose(v);
  }
  void propagate(Node *t, const OT x){
    t->lazy = h(t->lazy, x);
    t->key = g(t->key, x);
    t->sum = g(t->sum, x);
  }
  //ここから操作
  void add_vertex(int idx,T v = T()){//頂点idxの追加
    ver[idx] = make_node(idx, v);
  }
  void evert(int x){//根をxに
    evert(ver[x]);
  }
  void add_edge(int x,int y){//(x->y)の追加
    evert(y);
    link(ver[y],ver[x]);
  }
  void cut_edge(int x,int y){
    evert(x);
    cut(ver[y]);
  }
  T val(int x){
    return ver[x]->key;
  }
  T val_path(int x){//根~xのパスクエリ
    expose(ver[x]);
    return ver[x]->sum;
  }
  T val_path(int x,int y){//x->yのパスクエリ
    evert(x);
    return val_path(y);
  }
  void update(int x,T v){//頂点xの値をvに
    expose(ver[x]);
    ver[x]->key = v;
    update(ver[x]);
  }
  void update_path(int x,const OT v){//根~xのパス更新
    expose(ver[x]);
    propagate(ver[x], v);
    push(ver[x]);
  }
  void update_path(int x,int y,const OT v){//x~yのパス更新
    evert(x);
    update_path(y,v);
  }
  int lca(int x,int y){
    return lca(ver[x], ver[y])->idx;
  }
  bool connected(int x,int y){//頂点xとyが連結か？
    expose(ver[x]);
    expose(ver[y]);
    return bool(ver[x]->p);
  }
};
template< int mod >
struct ModInt {
  int x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

  ModInt &operator+=(const ModInt &p) {
    if((x += p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
    x = (int) (1LL * x * p.x % mod);
    return *this;
  }

  ModInt &operator/=(const ModInt &p) {
    *this *= p.inverse();
    return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt inverse() const {
    int a = x, b = mod, u = 1, v = 0, t;
    while(b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }

  ModInt pow(int64_t n) const {
    ModInt ret(1), mul(x);
    while(n > 0) {
      if(n & 1) ret *= mul;
      mul *= mul;
      n >>= 1;
    }
    return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) {
    return os << p.x;
  }

  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt< mod >(t);
    return (is);
  }

  static int get_mod() { return mod; }
};
