using mi = atcoder::modint998244353;

std::pair<mi, int> op(std::pair<mi, int> s1, std::pair<mi, int> s2) {
  auto [x1, l1] = s1;
  auto [x2, l2] = s2;
  return {x1+x2, l1+l2};
}
std::pair<mi, int> e() { return {mi(0), 0}; }
std::pair<mi, int> mapping(std::pair<mi, mi> f, std::pair<mi, int> s) {
  auto [x, l] = s;
  auto [b, c] = f;
  return {b*x + c*l, l};
}
std::pair<mi, mi> composition(std::pair<mi, mi> f1, std::pair<mi, mi> f2) {
  auto [b1, c1] = f1;
  auto [b2, c2] = f2;
  return {b1*b2, c1*b2+c2};
}
std::pair<mi, mi> id() {
  return {mi(1), mi(0)};
}

int main() {
  int n, q;
  scanf("%d %d", &n, &q);

  std::vector<std::pair<mi, int>> a(n);
  for (auto& ai: a) {
    int tmp;
    scanf("%d", &tmp);
    ai.first = tmp;
    ai.second = 1;
  }

  atcoder::lazy_segtree<std::pair<mi, int>, op, e,
                        std::pair<mi, mi>, mapping, composition, id> st(a);

  for (int i = 0; i < q; ++i) {
    int t;
    scanf("%d", &t);

    if (t == 0) {
      int l, r, b, c;
      scanf("%d %d %d %d", &l, &r, &b, &c);
