    return {a.sum + b.sum, a.len + b.len};
  }
};
struct action {
  mint a = 1, b = 0;
  node operator()(node x) const {
    x.sum *= a;
    x.sum += b * x.len;
    return x;
  }
  friend action operator*(const action& f, const action& g) {
    return {f.a * g.a, f.b * g.a + g.b};
  }
};

