template <class T1,class T2> // T1が要素、T2が作用素
class LazySegTree2 { // 区間長に比例したものを扱える
    public:
    int siz;
    typedef function<T1(T1,T1)> FX;
    typedef function<T1(T1,T2)> FA;
    typedef function<T2(T2,T2)> FM;
    typedef function<T2(T2,int)> FP;
    FX fx;
    FA fa;
    FM fm;
    FP fp;
    T1 idx;
    T2 idm;
    vector<T1> data;
    vector<T2> lazy;
    // 単位元埋め
    LazySegTree2 (int n,T1 _idx,T2 _idm,FX _fx,FA _fa,FM _fm,FP _fp):idx(_idx),idm(_idm),fx(_fx),fa(_fa),fm(_fm),fp(_fp){
        siz = 1;
        while(siz < n){
            siz *= 2;
        }
        data = vector<T1>(siz*2-1,_idx);
        lazy = vector<T2>(siz*2-1,_idm);
    }
    // 配列埋め
    LazySegTree2 (int n,T1 _idx,T2 _idm,vector<T1> &v,FX _fx,FA _fa,FM _fm,FP _fp):idx(_idx),idm(_idm),fx(_fx),fa(_fa),fm(_fm),fp(_fp){
        siz = 1;
        while(siz < n){
            siz *= 2;
        }
        data = vector<T1>(siz*2-1,_idx);
        lazy = vector<T2>(siz*2-1,_idm);
        rep(i,n){
            data[siz-1+i] = v[i];
        }
        for (int i = siz-2;i >= 0;i--){
            data[i] = fx(data[i*2+1],data[i*2+2]);
        }
    }
    //　評価関数
    void eval(int k,int len){
        if (lazy[k] == idm) return;
        if (k < siz-1){
            lazy[k*2+1] = fm(lazy[k*2+1],lazy[k]);
            lazy[k*2+2] = fm(lazy[k*2+2],lazy[k]);
        }
        data[k] = fa(data[k],fp(lazy[k],len));
        lazy[k] = idm;
    }
    // 更新クエリ
    void _update(int a,int b,T2 x,int k,int l,int r){
        eval(k,r-l);
        if (a <= l && r <= b){
            lazy[k] = fm(lazy[k],x);
            eval(k,r-l);
        }
        else if (a < r && l < b){
            _update(a,b,x,k*2+1,l,(l+r)/2);
            _update(a,b,x,k*2+2,(l+r)/2,r);
            data[k] = fx(data[k*2+1],data[k*2+2]);
        }
    }
    void update(int a,int b,T2 x){
        _update(a,b,x,0,0,siz);
    }
    // 区間クエリ
    T1 _query(int a,int b,int k,int l,int r){
        eval(k,r-l);
        if (r <= a || b <= l){
            return idx;
        }
        else if (a <= l && r <= b){
            return data[k];
