template<int64_t p>
struct F_p{
  using value_type = int64_t;
  static constexpr inline value_type get_mod(){return p;}

  value_type value;

  constexpr F_p():value(value_type{}){}
  template<class T>constexpr F_p(T v):value(static_cast<value_type>(v<0?v%p+p:v%p)){}
// operator +, -, *, /, ^ 
  constexpr F_p operator + (const F_p& other)const{
    return F_p(*this) += other;
  }
  constexpr F_p operator - (const F_p& other)const{
    return F_p(*this) -= other;
  }
  constexpr F_p operator * (const F_p& other)const{
    return F_p(*this) *= other;
  }
  constexpr F_p operator / (const F_p& other)const{
    return F_p(*this) /= other;
  }
  template<class T> constexpr F_p operator ^ (const T other)const{
    return F_p(*this) ^= other;
  }
  constexpr F_p &operator += (const F_p& other){
    value+=other.value;
    if(value>p)value-=p;
    return *this;
  }
  constexpr F_p &operator -= (const F_p& other){
    value-=other.value;
    if(value<0)value+=p;
    return *this;
  }
  constexpr F_p &operator *= (const F_p& other){
    value*=other.value;
    if(value>p)value%=p;
    return *this;
  }
  constexpr F_p &operator /= (const F_p& other){
    value*=other.inverse();
    if(value>p)value%=p;
    return *this;
  }
  template<class T>
  constexpr F_p &operator ^= (const T n){
    value = mpow(n).value;
    return *this;
  }
// ext_gcd,inverse,mpow 
  static constexpr value_type ext_gcd(value_type a,value_type b,value_type& x,value_type& y){
    if(b==0){x=1,y=0;return a;}
    value_type d=ext_gcd(b,a%b,y,x);
    y-=a/b*x;return d;
  }
  constexpr value_type inverse()const{
    value_type x,y;
    ext_gcd(value,p,x,y);
    return x<0?x%p+p:x%p;
  }
  template<class T>
  static constexpr value_type inverse(T val){
    value_type x,y;
    ext_gcd(val,p,x,y);
    return x<0?x%p+p:x%p;
  }
  template<class T>
  constexpr F_p mpow(T n)const{
    F_p res(1),vn(*this);
    while(n){
      if(n&1)res*=vn;
      vn*=vn;
      n>>=1;
    }
    return res;
  }
  template<class T,class U>
  static constexpr T mpow(T a,U b){
    F_p x(a);
    return static_cast<T>(x.mpow(b).value);
  }
// operator iostream 
  constexpr friend std::istream &operator >> (std::istream& is,F_p& fp){
    is>>fp.value;
    return is;
  }constexpr friend std::ostream &operator << (std::ostream& os,const F_p& fp){
    os<<fp.value;
    return os;
  }
// operator bool
  constexpr bool operator == (const F_p& other)const{
    return value==other.value;
  }
};

// Range Affine, Range Sum
template<class T>
struct lazy_segment_tree{
  struct monoid_type{
    T value;
    int size;
    monoid_type():value(),size(){}
    monoid_type(T v):value(v),size(1){}
    monoid_type(T v,int s):value(v),size(s){}
    monoid_type operator + (monoid_type const& rhs)const{
      return monoid_type(value+rhs.value,size+rhs.size);
    }
  };
  struct map_type{
    T a,b;
    map_type():a(1),b(){}
    map_type(T a,T b):a(a),b(b){}
    map_type operator * (map_type const& rhs)const{
      return map_type(a*rhs.a,b*rhs.a+rhs.b);
    }
    bool operator == (map_type const& rhs)const{
      return a==rhs.a and b==rhs.b;
    }
  };
  monoid_type merge(monoid_type lhs,monoid_type rhs)const{
    return lhs+rhs;
  }
  map_type composition(map_type lhs,map_type rhs)const{
    return lhs*rhs;
  }
  monoid_type mapping(monoid_type lhs,map_type rhs)const{
    auto&[value,size]=lhs;auto&[a,b]=rhs;
    return monoid_type(value*a+b*size,size);
  }
  std::vector<monoid_type> data;
  std::vector<map_type> lazy;
  monoid_type moni_ide = {0,0};
  map_type map_ide = {1,0};
  int n,height;

  lazy_segment_tree(){}

  template<class INT>
  lazy_segment_tree(std::vector<INT> const& vec){
    int sz = vec.size();
    height = 0;
    while((1<<height)<sz)height++;
    n = 1<<height;
    data.resize(2*n,moni_ide);
    lazy.resize(2*n,map_ide);
    for(int i=0;i<sz;++i){
      data[i+n] = static_cast<monoid_type>(vec[i]);
    }
    for(int i=n;i-->1;){
      data[i] = merge(data[i<<1|0],data[i<<1|1]);
    }
  }
  inline void eval(int k){
    if(lazy[k]==map_ide)return;
    if(k<n){
      lazy[k<<1|0] = composition(lazy[k<<1|0],lazy[k]);
      lazy[k<<1|1] = composition(lazy[k<<1|1],lazy[k]);
    }
    data[k] = mapping(data[k],lazy[k]);
    lazy[k] = map_ide;
  }
  inline void propagate(int k){
    for(int i=height;i;--i)eval(k>>i);
  }
  inline void calc_to_par(int k){
    while(k>>=1){
      eval(k<<1|0);eval(k<<1|1);
      data[k]=merge(data[k<<1|0],data[k<<1|1]);
    }
  }
  void update(int a,int b,map_type v){
    a+=n,b+=n-1;propagate(a);propagate(b);
    for(int l=a,r=b+1;l<r;l>>=1,r>>=1){
      if(l&1)lazy[l]=composition(lazy[l],v),l++;
      if(r&1)--r,lazy[r]=composition(v,lazy[r]);
    }
    calc_to_par(a);calc_to_par(b);
  }
  void set(int k,map_type v){
    k+=n;propagate(k);
    data[k]=v;lazy[k]=map_ide;
    calc_to_par(k);
  }
  T fold(int a,int b){
    a+=n,b+=n-1;propagate(a);propagate(b);
    monoid_type left_v,right_v;
    for(int l=a,r=b+1;l<r;l>>=1,r>>=1){
      if(l&1){
        eval(l);
        left_v = merge(left_v,data[l]);
        l++;
      }
      if(r&1){
        --r;
        eval(r);
        right_v = merge(data[r],right_v);
      }
    }
    return merge(left_v,right_v).value;
  }
};

