struct S {
    mint val;
    int sz;
};
S op(S a, S b) {
    return S{ a.val + b.val, a.sz + b.sz };
}
S e() {
    return S{ 0, 0 };
}
struct F {
    mint a, b;
};
S mapping(F f, S x) {
    return S{ f.a * x.val + f.b * x.sz, x.sz };
}
F composition(F f, F g) {
    return F{ f.a * g.a, f.a * g.b + f.b };
}
F id() {
    return F{ 1, 0 };
}

int solve() {

    SS(int, N, Q);

    vector<S> A(N);
    REP (i, N) {
        SS(int, X);
        A[i].val = X;
        A[i].sz  = 1;
    }

    atcoder::lazy_segtree<S, op, e, F, mapping, composition, id> seg(A);

    while (Q--) {
        SS(int, T);
        if (T == 0) {
            SS(int, L, R, B, C);
            seg.apply(L, R, F{ B, C });
        } else {
            SS(int, L, R);
            print(seg.prod(L, R).val.val());
        }
    }

    return 0;
}

