using mint = modint998244353;
using P = pair<mint, int>;
using Q = pair<mint, mint>;

P f(P a, P b) {
    P res;
    res.first = a.first + b.first;
    res.second = a.second + b.second;
    return res;
}
P g(P a, Q x, int l, int r) {
    P res = a;
    res.first *= x.first;
    res.first += x.second * (r - l);
    return res;
}
Q h(Q a, Q b) {
    Q res;
    res.first = a.first * b.first;
    res.second = a.first * b.second + a.second;
    return res;
}
int main() {
