    cin >> n >> q;
    vi a(n);
    rep(i, n) cin >> a[i];
    LazySegmentTree<P, Q> seg(n, P{0, 0}, Q{1, 0}, f, g, h);
    rep(i, n) {
        seg.set(i, P{a[i], 1});
    }
    seg.build();
    while (q--) {
        int t;
        cin >> t;
        if (t) {
