#include <bits/stdc++.h>

using namespace std;

const int M = 500005;
const int mod = 998244353;

int A[M], B[4 * M], C[4 * M], S[4 * M], len[4 * M];
int n, q;

void push_up(int p) {
    S[p] = (S[p << 1] + S[p << 1 | 1]) % mod;
}

void push_down(int p) {
    if (B[p] != 1) {
        B[p << 1] = (long long) B[p << 1] * B[p] % mod;
        C[p << 1] = (long long) C[p << 1] * B[p] % mod;
        S[p << 1] = (long long) S[p << 1] * B[p] % mod;
        B[p << 1 | 1] = (long long) B[p << 1 | 1] * B[p] % mod;
        C[p << 1 | 1] = (long long) C[p << 1 | 1] * B[p] % mod;
        S[p << 1 | 1] = (long long) S[p << 1 | 1] * B[p] % mod;
        B[p] = 1;
    }
    if (C[p] != 0) {
        C[p << 1] = (C[p << 1] + C[p]) % mod;
        S[p << 1] = (S[p << 1] + (long long) C[p] * len[p << 1]) % mod;
        C[p << 1 | 1] = (C[p << 1 | 1] + C[p]) % mod;
        S[p << 1 | 1] = (S[p << 1 | 1] + (long long) C[p] * len[p << 1 | 1]) % mod;
        C[p] = 0;
    }
}

void build(int p, int l, int r) {
    len[p] = r - l + 1;
    B[p] = 1;
    if (l == r) {
        S[p] = A[l];
        return;
    }
    int mid = (l + r) >> 1;
    build(p << 1, l, mid);
    build(p << 1 | 1, mid + 1, r);
    push_up(p);
}

void modify(int p, int l, int r, int a, int b, int x, int y) {
    if (l == a && r == b) {
        B[p] = (long long) B[p] * x % mod;
        C[p] = ((long long) C[p] * x + y) % mod;
        S[p] = ((long long) S[p] * x + (long long) y * len[p]) % mod;
        return;
    }
    push_down(p);
    int mid = (l + r) >> 1;
    if (mid < a)
        modify(p << 1 | 1, mid + 1, r, a, b, x, y);
    else if (b <= mid)
        modify(p << 1, l, mid, a, b, x, y);
    else {
        modify(p << 1, l, mid, a, mid, x, y) ;
        modify(p << 1 | 1, mid + 1, r, mid + 1, b, x, y);
    }
    push_up(p);
}

int query(int p, int l, int r, int a, int b) {
    if (l == a && r == b)
        return S[p];
    push_down(p);
    int mid = (l + r) >> 1;
    if (mid < a)
        return query(p << 1 | 1, mid + 1, r, a, b);
    if (b <= mid)
        return query(p << 1, l, mid, a, b);
    return (query(p << 1, l, mid, a, mid) + query(p << 1 | 1, mid + 1, r, mid + 1, b)) % mod;
}

int main() {
    scanf("%d%d", &n, &q);
    for (int i = 0; i < n; ++i)
        scanf("%d", &A[i]);
    build(1, 0, n - 1);
    while (q-- != 0) {
        int op, l, r, b, c;
        scanf("%d", &op);
        if (op == 0) {
            scanf("%d%d%d%d", &l, &r, &b, &c);
            modify(1, 0, n - 1, l, r - 1, b, c);
        }
        if (op == 1) {
            scanf("%d%d", &l, &r);
            printf("%d\n", query(1, 0, n - 1, l, r - 1));
        }
    }
    return 0;
}

