const int modu = 998244353;

int op(int a, int b) {
	return (a + b) % modu;
}

int e() {
	return 0;
}

int mapping(pair<int, int> f, int x) {
	int ret = x * f.first;
	ret %= modu;
	ret += f.second;
	ret %= modu;

	return ret;
}

pair<int, int> composition(pair<int, int> f, pair<int, int> g) {
	// (b, c) と (d, e) をマージ
	int b = f.first, c = f.second, d = g.first, e = g.second;

	return mp((b * d) % modu, (c*d + e) % modu);
}

pair<int, int> id() {
	return mp(1, 0);
}

