using LazySegtree = lazy_segtree<
    typename M::Value, M::merge, M::unit_value,
    typename M::Lazy, M::act, M::compose, M::unit_action>;

struct SumAffine {
    using Value = pair<mint,int>; // sum,len
    using Lazy = pair<mint,mint>; // b,c
    static Value unit_value() { return {0,0}; }
    static Lazy unit_action() { return {1,0}; }
    static Value merge(Value x, Value y) {
        return { x.fst + y.fst, x.snd + y.snd };
    }
    static Value act(Lazy x, Value y) {
        return { x.fst*y.fst + x.snd*y.snd, y.snd };
    }
    static Lazy compose(Lazy x, Lazy y) {
        return { x.fst*y.fst, x.fst*y.snd + x.snd };
    }
};

