void PrimeFactorize(ll num,vector<ll> &ret){
    vector<ll> prime(num+1,0);
    while(num%2==0){
        num /= 2;
        prime[2]++;
    }
    for(ll i=3;i<=num;i++){
        while(num%i==0){
            num /= i;
            prime[i]++;
        }
    }
    copy(prime.begin(),prime.end(),back_inserter(ret));
}

