    T _l;
    T _r;
    function<bool(T)> _f;
    public:
    BinarySearch(T left,T right,function<bool(T)>func){
        this->_l=left;
        this->_r=right;
        this->_f=func;
    }
    ~BinarySearch() = default;
    T calc(){
        while((this->_r-this->_l)>1){
            T middle=(this->_l+this->_r)/2;
            if(this->_f[middle]){
                this->_r=middle;
            }else{
                this->_l=middle;
