		{
			cin >> l >> r >> x >> y;
			d0[0][0] = x, d0[0][1] = y;
			d0[1][0] = 0, d0[1][1] = 1;
			st.update(l, r, d0);
		}
		else
		{
			cin >> l >> r;
			cout << st.query(l, r) << endl;
		}
		//cout << "a" << endl;
	}

	return 0;
}

