    auto fp=[](pl a,int len){return make_pair(a.fi,a.se*len%MOD9);};
    SegTreeLazyProportional<pl,pl> st(n,fx,fa,fm,fp,make_pair(0,0),make_pair(1,0));
    rep(i,n){
        ll a;cin >> a;
