/* #region mint */

// 自動で MOD を取る整数
struct mint {
    ll x;
    mint(ll x = 0) : x((x % MOD + MOD) % MOD) {}
    mint &operator+=(const mint a) {
        if ((x += a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint &operator-=(const mint a) {
        if ((x += MOD - a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint &operator*=(const mint a) {
        (x *= a.x) %= MOD;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }
    // O(log(t))
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1); // ⌊t/2⌋ 乗
        a *= a;               // ⌊t/2⌋*2 乗
        if (t & 1)            // ⌊t/2⌋*2 == t-1 のとき
            a *= *this;       // ⌊t/2⌋*2+1 乗 => t 乗
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(MOD - 2); // オイラーの定理から， x^(-1) ≡ x^(p-2)
    }
    mint &operator/=(const mint a) { return (*this) *= a.inv(); }
    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }
    bool operator==(const mint a) const { return this->x == a.x; }
    bool operator==(const ll a) const { return this->x == a; }

    // mint 入力
    friend istream &operator>>(istream &is, mint &x) {
        is >> x.x;
        return is;
    }

    // mint 出力
    friend ostream &operator<<(ostream &os, mint x) {
        os << x.x;
        return os;
    }
};

/* #endregion */

// Problem
void solve() {
    VAR(ll, n, q); //
    vc<mint> va(n);
    cin >> va;

    using T = pair<mint, mint>;
    using E = pair<mint, mint>;

    auto f = [](T az0, T az1) -> T { // 要素のマージ
        auto [a0, z0] = az0;
        auto [a1, z1] = az1;
        return {a0 + a1, z0 + z1};
    };
    auto g = [](T az, E bc) -> T { // 要素に作用素を作用させる
        auto [a, z] = az;
        auto [b, c] = bc;
        return {a * b + c * z, z};
    };
    auto h = [](E a, E b) -> E {
        auto [b0, c0] = a;
        auto [b1, c1] = b;
        return {b0 * b1, c0 * b1 + c1};
    };
    T ti = {0, 0};
    E ei = {1, 0};
    LazySegmentTree<T, E> seg(f, g, h, ti, ei);

    vc<T> data(n);
    REP(i, 0, n) data[i] = {va[i], 1};
    seg.build(data);

    REP(i, 0, q) {
        VAR(ll, m, l, r);
        if (m == 0) {
            // update
            VAR(ll, b, c);
            seg.update(l, r, {b, c});
        } else {
            // query
            cout << seg.query(l, r).first << endl;
        }
    }
}

// entry point
int main() {
    solve();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int MAX_N=131072*4;
int64_t Null=0;//初期値
int64_t Q=998244353;
vector<int64_t> seg(MAX_N*2-1,Null);
vector<int64_t> lazy(MAX_N*2-1,Null);
vector<int64_t> p(MAX_N*2-1,Null);
void eval(int k){
  if(lazy[k]==Null){
    return;
  }
  if(k<MAX_N-1){//子への伝播
    lazy[k*2+1]=lazy[k];//change
    lazy[k*2+2]=lazy[k];//change
  }
  int64_t A=lazy[k]/Q,B=lazy[k]%Q;
  seg[k]*=A;
  seg[k]%=Q;//change
  seg[k]+=(B*p[k]);
  seg[k]%=Q;
  lazy[k]=Null;
}

int64_t qu_s(int a,int b,int k,int l, int r){
  eval(k);
  if(r<=a||b<=l){
    return 0;//change
  }
  else if(a<=l&&r<=b){
    return seg[k];
  }
  else{
    int64_t X=qu_s(a,b,k*2+1,l,(l+r)/2);
    int64_t Y=qu_s(a,b,k*2+2,(l+r)/2,r);
    return (X+Y)%Q;//change
  }
}
int64_t qu(int a,int b){
  return qu_s(a,b,0,0,MAX_N);
}

void chran_s(int64_t c,int a,int b,int k,int l, int r){
  eval(k);
  if(r<=a||b<=l){
    return;
  }
  else if(a<=l&&r<=b){
    lazy[k]=c;
    eval(k);
    while(k>0){//親への伝播
      k--;
      k/=2;
      eval(k);
      eval(2*k+1);
      eval(2*k+2);
      seg[k]=(seg[2*k+1]+seg[2*k+2])%Q;//change
    }
  }
  else{
    chran_s(c,a,b,k*2+1,l,(l+r)/2);
    chran_s(c,a,b,k*2+2,(l+r)/2,r);
  }
}
void chran(int64_t c,int a,int b){
  chran_s(c,a,b,0,0,MAX_N);
}

int main(){
  int N,K;
  cin>>N>>K;
  p[0]=MAX_N;
  for(int i=0;i<MAX_N-1;i++){
    p[i*2+1]=p[i]/2;
    p[i*2+2]=p[i]/2;
  }
  for(int i=0;i<N;i++){
    cin>>seg[i-1+MAX_N];
  }
  for(int i=MAX_N-2;i>=0;i--){
    seg[i]=(seg[2*i+1]+seg[i*2+2])%Q;
  }
  for(int i=0;i<K;i++){
    int p,l,r;
    cin>>p>>l>>r;
    if(p){
      cout<<qu(l,r)<<endl;
    }
    else{
      int64_t b,c;
      cin>>b>>c;
      int64_t d=b*Q+c;
      chran(d,l,r);
    }
  }
}

