    using Seg = LazySegmentTree<segobj<T>, T>;
    using obj = segobj<T>;
    RSRRQ(int n)
        : Seg(n, plus<obj>(), myreplace<obj, T>, myreplace<T>, segobj<T>(),
              numeric_limits<T>::max()) {
        rep(i, n) this->set(i, segobj<T>(0, 1));
        this->build();
    }
    T sum(int l, int r) { return this->query(l, r).val; }
};

struct X {
    mint val, size;
};
struct F {
    mint b, c;
};
int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);
    cout << setprecision(30);
    auto f = [&](X x, X y) {
        x.size += y.size;
        x.val += y.val;
        return x;
    };
    auto g = [&](X x, F ff) {
        x.val = x.size * ff.c + x.val * ff.b;
        return x;
    };
    auto h = [&](F ff, F gg) {
        ff.b *= gg.b;
        ff.c = ff.c * gg.b + gg.c;
        return ff;
    };
    int n, q;
    cin >> n >> q;
    LazySegmentTree<X, F> seg(n, f, g, h, X{0, 0}, F{1, 0});
    rep(i, n) {
        ll a;
        cin >> a;
        seg.set(i, X{a, 1});
    }
    seg.build();
    cout << endl;
    while (q--) {
        int t;
        cin >> t;
        if (t == 0) {
            ll l, r, b, c;
            cin >> l >> r >> b >> c;
            seg.update(l, r, F{b, c});
        } else {
            ll l, r;
            cin >> l >> r;
            print(seg.query(l, r).val);
        }
    }
}

