void eval(int k){
  if(lazy[k]==Null){
    return;
  }
  if(k<MAX_N-1){//子への伝播
    eval(k*2+1);
    eval(k*2+2);
    lazy[k*2+1]=lazy[k];//change
    lazy[k*2+2]=lazy[k];//change
  }
  int64_t A=lazy[k]/Q,B=lazy[k]%Q;
  seg[k]*=A;
  seg[k]%=Q;//change
  seg[k]+=(B*p[k]);
