// Segment Tree
// SegTree<X>(n,fx,ex): monoid(∈X, fx:binary operation, ex:identity element)
template <typename X, typename FX> struct SegTree {
    int n; FX fx; const X ex; vector<X> dat;
    SegTree(int n_, FX fx_, X ex_) : n(), fx(fx_), ex(ex_), dat(n_*4, ex_) {
        int x = 1; while (n_ > x) {x *= 2;} n = x;
    }
    void set(int i, X x) {dat[i+n-1] = x;}
    void build() {rrep(k,n-1) {dat[k] = fx(dat[2*k+1], dat[2*k+2]);}}
    void update(int i, X b, X c) {
        i += n - 1; dat[i] = dat[i]*b + c; // subject to change
        while(i) {i = (i-1)/2; dat[i] = fx(dat[i*2+1], dat[i*2+2]);}
    }
    // query : f[a,b), Ο(log(n))
    X query(int a, int b) {return query_sub(a, b, 0, 0, n);}
    private:
    X query_sub(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return ex;
        else if (a <= l && r <= b) return dat[k];
        else {
            X vl = query_sub(a, b, k*2+1, l, (l+r)/2);
            X vr = query_sub(a, b, k*2+2, (l+r)/2, r);
            return fx(vl, vr);
        }
    }
};

signed main() {
    int n, q; cin >> n >> q;
    auto fx = [](mint x1, mint x2) -> mint {return x1 + x2;};
    mint ex = 0;
    SegTree<mint,decltype(fx)> seg(n, fx, ex);
    rep(i,n) {
        mint a; cin >> a;
        seg.set(i,a);
    }
    seg.build();
    rep(i,q) {
        int t, l, r; cin >> t >> l >> r;
        if(t) {
            cout << seg.query(l,r) << endl;
        }
        else {
            mint b, c; cin >> b >> c;
            rep2(i,l,r) seg.update(i,b,c);
        }
    }
    return 0;
}

