template <
    class T,
    class F,
    T (*fOperate)(T, T),
    T (*fAct)(T, F),
    F (*fMerge)(F, F)
>
struct LazySegTree {
    int n, height;
    // 値配列, 値の単位元
    vector<T> data;
    T dataId;
    // 遅延配列, 遅延値の単位元
    vector<F> lazy;
    F lazyId;

    LazySegTree(
        int _n, T _did, F _lid
    )
        : dataId(_did), lazyId(_lid){
        n = 1, height = 0;
        while (n < _n) n *= 2, height++;
        data = vector<T>(2 * n, dataId);
        lazy = vector<F>(2 * n, lazyId);
    }

    inline T act(int k){
        return lazy[k] == lazyId ? data[k] : fAct(data[k], lazy[k]);
    }

    inline void propagate(int k){
        if (lazy[k] == lazyId) return;
        lazy[2 * k + 0] = fMerge(lazy[2 * k + 0], lazy[k]);
        lazy[2 * k + 1] = fMerge(lazy[2 * k + 1], lazy[k]);
        data[k] = fAct(data[k], lazy[k]), lazy[k] = lazyId;
    }


    // [a, b)を更新
    inline void update(int a, int b, F x) {
        if (a == b) return;
        a += n, b += n - 1;
        for (int i = height; i > 0; i--) propagate(a >> i), propagate(b >> i);
        for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) lazy[l] = fMerge(lazy[l], x), l++;
            if (r & 1) r--, lazy[r] = fMerge(lazy[r], x);
        }
        for (int l = a >> 1, r = b >> 1; l > 0; l >>= 1, r >>= 1) {
            data[l] = fOperate(act(2 * l + 0), act(2 * l + 1));
            data[r] = fOperate(act(2 * r + 0), act(2 * r + 1));
        }
    }

    // [l, r)の区間クエリ
    inline T query(int a, int b){
        if (a == b) return dataId;
        a += n, b += n - 1;
        for (int i = height; i > 0; i--) propagate(a >> i), propagate(b >> i);
        T Lret = dataId, Rret = dataId;
        for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1){
            if (l & 1) Lret = fOperate(Lret, act(l++));
            if (r & 1) Rret = fOperate(act(--r), Rret);
        }
        return fOperate(Lret, Rret);
    }

    inline void build(vector<T> vec){
        for (int i = 0; i < vec.size(); i++) data[i + n] = vec[i];
        for (int i = n - 1; i > 0; i--) data[i] = fOperate(data[2 * i + 0], data[2 * i + 1]);
    }

    // 添字でアクセス
    inline T& operator[](int i) {
        return data[i + n];
    }
};

struct Data {
    mint v, size;
};
Data dataid = {0, 1};

struct Lazy{
    mint a, b;
    constexpr bool operator == (const Lazy& lz) const noexcept {
        return a == lz.a and b == lz.b;
    }
};
Lazy lazyid = {1, 0};

Data fop(Data a, Data b){
    return {a.v + b.v, a.size + b.size};
}
Data fac(Data a, Lazy f){
    return {a.v * f.a + f.b * a.size, a.size};
}
Lazy fme(Lazy f, Lazy g){
    return {f.a * g.a, f.b * g.a + g.b};
}

