template <typename X, typename M>
struct SegTreeLazy {
    using FX = function<X(X, X)>;
    using FA = function<X(X, M)>;
    using FM = function<M(M, M)>;
    using FP = function<M(M, int)>;
    int n;
    FX fx;
    FA fa;
    FM fm;
    FP fp;
    const X ex;
    const M em;
    vector<X> dat;
    vector<M> lazy;
    SegTreeLazy(int n_, FX fx_, FA fa_, FM fm_, FP fp_, X ex_, M em_)
        : n(), fx(fx_), fa(fa_), fm(fm_), fp(fp_), ex(ex_), em(em_), dat(n_ * 4, ex), lazy(n_ * 4, em) {
        int x = 1;
        while (n_ > x) x *= 2;
        n = x;
    }
    void set(int i, X x) { dat[i + n - 1] = x; }
    void build() {
        for (int k = n - 2; k >= 0; k--) dat[k] = fx(dat[2 * k + 1], dat[2 * k + 2]);
    }
    /* lazy eval */
    void eval(int k, int len) {
        if (lazy[k] == em) return;  // 更新するものが無ければ終了
        if (k < n - 1) {            // 葉でなければ子に伝搬
            lazy[k * 2 + 1] = fm(lazy[k * 2 + 1], lazy[k]);
            lazy[k * 2 + 2] = fm(lazy[k * 2 + 2], lazy[k]);
        }
        // 自身を更新
        dat[k] = fa(dat[k], fp(lazy[k], len));
        lazy[k] = em;
    }
    void update(int a, int b, M x, int k, int l, int r) {
        eval(k, r - l);
        if (a <= l && r <= b) {  // 完全に内側の時
            lazy[k] = fm(lazy[k], x);
            eval(k, r - l);
        } else if (a < r && l < b) {                     // 一部区間が被る時
            update(a, b, x, k * 2 + 1, l, (l + r) / 2);  // 左の子
            update(a, b, x, k * 2 + 2, (l + r) / 2, r);  // 右の子
            dat[k] = fx(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    void update(int a, int b, M x) { update(a, b, x, 0, 0, n); }
    X query_sub(int a, int b, int k, int l, int r) {
        eval(k, r - l);
        if (r <= a || b <= l) {  // 完全に外側の時
            return ex;
        } else if (a <= l && r <= b) {  // 完全に内側の時
            return dat[k];
        } else {  // 一部区間が被る時
            X vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
            X vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
            return fx(vl, vr);
        }
    }
    X query(int a, int b) { return query_sub(a, b, 0, 0, n); }
    X operator[](int i) {
        return query(i, i+1);
    }
};
/* 
  SegTreeLazyProportional<X,M>(n,fx,fa,fm,fp,ex,em): 
  モノイド(集合X, 二項演算fx,fa,fm,fp 単位元ex,em)についてサイズnで構築
    set(int i, X x), build(): i番目の要素をxにセット。まとめてセグ木を構築する。O(n)
    update(i,j,x): [i,j)の要素を x で更新。O(log(n))
    query(a,b):  [a,b) 全てにfxを作用させた値を取得。O(log(n))
*/
signed main() {
  cin.tie(0);cout.tie(0);ios::sync_with_stdio(false);cout<<fixed<<setprecision(12);
  using X = mint;
  using M = pair<mint,mint>;
  auto fx = [](X x1, X x2) -> X { return x1 + x2; }; // 元データ * 元データ(Q)
  auto fa = [](X x, M m) -> X { return x * m.FI + m.SE; }; // 元データ * 遅延(U)
  auto fm = [](M m1, M m2) -> M { return mp(m1.FI*m2.FI , m1.SE*m2.FI + m2.SE ); };
  auto fp = [](M m, int n) -> M { return mp(m.FI,m.SE*n); }; // n要素の区間の扱い(Q)
  mint ex = 0;
  pair<mint,mint> em = mp(1,0);
  int n,q;cin >> n >> q;
  SegTreeLazy<X, M> st(n, fx, fa, fm, fp, ex, em);

  rep(i,0,n){
    int qw;cin >> qw;
    st.set(i,qw);
  }
  st.build();
  rep(i,0,q){
    int qw;cin >> qw;
    if(qw){
      int er,ty;cin >> er >> ty;
      cout << st.query(er,ty).val() << endl;
    }
    else {
      int er,ty,as,df;
      cin >> er >> ty >> as >> df;
      st.update(er,ty,mp(as,df));
    }
  }

  return 0;
}

