template <class T = long long, class U = long long>
class LazyST {
   private:
	int n;
	int height = -1;	  //木の高さ
	vector<T> data;		  // monoid
	vector<U> lazy;		  // operator
	T unit_data;		  // monoid単位元
	U unit_lazy;		  // operator単位元
	function<T(T, T)> f;  // monoid同士の演算
	function<T(T, U)> g;  // monoidとoperatorとの演算
	function<U(U, U)> h;  // operator同士の演算
	void propagate(int lef, int rig) {
		// 遅延させていた作用素を上から伝播させる [lef,rig)に有効な範囲で
		lef += n;
		rig += n - 1;  //閉区間にする
		for(int i = height; i > 0; i--) {
			int l = lef >> i;
			int r = rig >> i;
			lazy[l << 1] = h(lazy[l << 1], lazy[l]);
			lazy[l << 1 | 1] = h(lazy[l << 1 | 1], lazy[l]);
			data[l] = g(data[l], lazy[l]);
			lazy[l] = unit_lazy;
			lazy[r << 1] = h(lazy[r << 1], lazy[r]);
			lazy[r << 1 | 1] = h(lazy[r << 1 | 1], lazy[r]);
			data[r] = g(data[r], lazy[r]);
			lazy[r] = unit_lazy;
		}
	}

   public:
	// 全て同じmonoid = init_dataで初期化
	LazyST(int _n, function<T(T, T)> ope_data_data, function<T(T, U)> ope_data_lazy, function<U(U, U)> ope_lazy_lazy, T _unit_data,
		   U _unit_lazy, T init_data)
		: n(_n), f(ope_data_data), g(ope_data_lazy), h(ope_lazy_lazy), unit_data(_unit_data), unit_lazy(_unit_lazy) {
		data.assign(n * 2, unit_data);
		for(int i = 0; i < n; i++) {
			data[i + n] = init_data;
		}
		for(int i = n - 1; i > -1; i--) {
			data[i] = f(data[i << 1], data[i << 1 | 1]);
		}
		lazy.assign(n * 2, unit_lazy);
		for(int i = 1; i <= n; i *= 2) height++;
	}
	// 初期化配列をvectorで渡す
	LazyST(int _n, function<T(T, T)> ope_data_data, function<T(T, U)> ope_data_lazy, function<U(U, U)> ope_lazy_lazy, T _unit_data,
		   U _unit_lazy, vector<T> raw_data)
		: n(_n), f(ope_data_data), g(ope_data_lazy), h(ope_lazy_lazy), unit_data(_unit_data), unit_lazy(_unit_lazy) {
		data.assign(n * 2, unit_data);
		for(int i = 0; i < n; i++) {
			data[i + n] = raw_data[i];
		}
		for(int i = n - 1; i > -1; i--) {
			data[i] = f(data[i << 1], data[i << 1 | 1]);
		}
		lazy.assign(n * 2, unit_lazy);
		for(int i = 1; i <= n; i *= 2) height++;
	}

	void update(int lef, int rig, U _operator) {  //[lef,rig)にopeを作用させる
		propagate(lef, rig);
		lef += n;
		rig += n;  //半開区間にする 下から上にdataを更新
		int L0 = lef / (lef & -lef);
		int R0 = rig / (rig & -rig);
		while(lef < rig) {
			if(lef & 1) {
				lazy[lef] = h(lazy[lef], _operator);
				lef++;
			}
			if(rig & 1) {
				lazy[rig - 1] = h(lazy[rig - 1], _operator);
				rig--;
			}
			lef >>= 1;
			rig >>= 1;
		}
		lef = L0;
		rig = R0;
		while(lef > 1) {
			lef >>= 1;
			data[lef] = f(g(data[lef << 1], lazy[lef << 1]), g(data[lef << 1 | 1], lazy[lef << 1 | 1]));
			lazy[lef] = unit_lazy;
		}
		while(rig > 1) {
			rig >>= 1;
			data[rig] = f(g(data[rig << 1], lazy[rig << 1]), g(data[rig << 1 | 1], lazy[rig << 1 | 1]));
			lazy[rig] = unit_lazy;
		}
	}

	T get(int lef, int rig) {  //区間の値取得
		propagate(lef, rig);
		T a = unit_data, b = unit_data;
		lef += n;
		rig += n;
		while(lef < rig) {
			if(lef & 1) a = f(a, g(data[lef], lazy[lef]));
			if(rig & 1) b = f(g(data[rig - 1], lazy[rig - 1]), b);
			(lef += 1) >>= 1;
			rig >>= 1;
		}
		return f(a, b);
	}
};

struct mint {
	long long x;
	mint(long long x = 0) : x((x % mod + mod) % mod) {}
	mint operator-() const { return mint(-x); }
	mint &operator+=(const mint a) {
		if((x += a.x) >= mod) x -= mod;
		return *this;
	}
	mint &operator-=(const mint a) {
		if((x += mod - a.x) >= mod) x -= mod;
		return *this;
	}
	mint &operator*=(const mint a) {
		(x *= a.x) %= mod;
		return *this;
	}
	mint operator+(const mint a) const { return mint(*this) += a; }
	mint operator-(const mint a) const { return mint(*this) -= a; }
	mint operator*(const mint a) const { return mint(*this) *= a; }
	mint pow(long long t) const {
		if(!t) return 1;
		mint a = pow(t >> 1);
		a *= a;
		if(t & 1) a *= *this;
		return a;
	}

	// for prime mod
	mint inv() const { return pow(mod - 2); }
	mint &operator/=(const mint a) { return *this *= a.inv(); }
	mint operator/(const mint a) const { return mint(*this) /= a; }
};
ostream &operator<<(ostream &os, const mint &a) { return os << a.x; }

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout << fixed << setprecision(15);
	srand((unsigned)time(NULL));

	LL(n, q);

	VEC(ll, a, n);

	using pp = pair<mint, mint>;
	vector<pp> amod(n);
	rep(i, n) amod[i].first = a[i], amod[i].second = 1;

	dump(amod);

	vector<mint> ans;

	auto add = [](pair<mint, mint> a, pair<mint, mint> b) {
		pair<mint, mint> ret;
		ret.first = a.first + b.first, ret.second = a.second + b.second;
		return ret;
	};

	auto affine = [](pair<mint, mint> a, pair<mint, mint> b) {
		pair<mint, mint> ret;
		ret.second = a.second;
		ret.first = a.first * b.first + a.second * b.second;
		return ret;
	};

	auto merge = [](pair<mint, mint> a, pair<mint, mint> b) {
		pair<mint, mint> ret;
		ret.first = a.first * b.first;
		ret.second = a.second * b.first + b.second;
		return ret;
	};

	const pp unit_ope = {1, 0};
	const pp unit_monoid = {0, 0};

	LazyST<pp, pp> lst(n, add, affine, merge, unit_monoid, unit_ope, amod);

	while(q--) {
