	vector <S> a(n);
	for (int i = 0; i < n; ++i) {
		int x; scanf("%d", &x);
		a[i] = x;
	}
	lazy_segtree <S, op, e, F, mapping, composition, id> t(a);
	while (q--) {
		char f[2];
