S op(S a, S b) { return a + b; }
S e() { return S(0); }
S mapping(F f, S x) { return f.first * x + f.second; }
F composition(F a, F b) {
	return F { a.first * b.first, a.first * b.second + a.second };
}
F id() { return F { 1, 0 }; }

