template<class T>
class LazySegmentTree {
protected:
    using UPF = function<void(T&)>;
    using QRF = function<void(T&, const T)>;
    using F = function<bool(T& a)>;
    int n, rr;
    vector<T>dat;

    LazySegmentTree() {}
    LazySegmentTree(int size) { init(size); }
    LazySegmentTree(vector<T>& v) {
        init(v);
    }
    virtual ~LazySegmentTree() {}

    virtual void eval(T& par, T& a,T& b) = 0;
    virtual T proc(const T& a, const T& b) = 0;

public:
    void init(int size) {
        n = size, rr = 1;
        while (rr < n) rr <<= 1;
        dat.assign(2 * rr - 1, T());
        for (int i = rr - 2; i >= 0; i--)
            dat[i] = proc(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    void init(vector<T>& v) {
        n = v.size(), rr = 1;
        while (rr < n) rr <<= 1;
        dat.assign(2 * rr - 1, T());
        for (int i = 0; i < n; i++)
            dat[i + rr - 1] = v[i];
        for (int i = rr - 2; i >= 0; i--)
            dat[i] = proc(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    //one point update
    void set(int at, T x) {
        update(0, at, at + 1, 0, rr, [x](T& a) {a = x; });
    }
    void upd(int a, int b, UPF func) {
        upd(0, a, b, 0, rr, func);
    }
    T qry(int a, int b) {
        return qry(0, a, b, 0, rr);
    }
    T get0() {
        return dat[0];
    }
    //func([a,i))==true, func([a,i+1))==false
    int lb(int a, int b, F func) {
        return lb(0, a, b, 0, rr, func, T());
    }
    //func([i,b))==true, func([i-1,b))==false
    int rb(int a, int b, F func) {
        return rb(0, a, b, 0, rr, func, T());
    }
private:
    void upd(int i, int a, int b, int l, int r, UPF& func) {
        if (b <= l || r <= a) return;
        if (a <= l && r <= b) {
            func(dat[i]);
            return;
        }

        eval(dat[i], dat[i * 2 + 1], dat[i * 2 + 2]);

        upd(i * 2 + 1, a, b, l, (l + r) / 2, func);
        upd(i * 2 + 2, a, b, (l + r) / 2, r, func);

        dat[i] = proc(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    T qry(int i, int a, int b, int l, int r) {
        if (b <= l || r <= a) return T();
        if (a <= l && r <= b) return dat[i];

        eval(dat[i], dat[i * 2 + 1], dat[i * 2 + 2]);

        T ret = proc(qry(i * 2 + 1, a, b, l, (l + r) / 2),
            qry(i * 2 + 2, a, b, (l + r) / 2, r));

        return ret;
    }
    int lb(int i, int a, int b, int l, int r, F& func, T wa) {
        if (b <= l || r <= a || func(proc(wa, dat[i]))) return b + 1;
        if (r - l == 1) return r;
        int tmp = lb(i * 2 + 1, a, b, l, (l + r) / 2, func, wa);
        if (tmp < b + 1) return tmp;
        return lb(i * 2 + 2, a, b, (l + r) / 2, r, func, proc(wa, dat[i * 2 + 1]));
    }
    int rb(int i, int a, int b, int l, int r, F& func,T wa) {
        if (b <= l || r <= a || func(dat[i], wa)) return a - 1;
        if (r - l == 1) return l;
        int tmp = rb(i * 2 + 2, a, b, (l + r) / 2, r, func,wa);
        if (tmp >= a) return tmp;
        return rb(i * 2 + 1, a, b, l, (l + r) / 2, func, proc(dat[i * 2 + 2], wa));
    }
};

template<class T>
class Segtree :LazySegmentTree<T>{
    using Base = LazySegmentTree<T>;
public:
    Segtree() {}
    Segtree(int size) :Base(size) {}
    Segtree(vector<ll>& v)  {
        init(v);
    }
    void init(int size) {
        Base::init(size);
    }
    void init(vector<mint>& v) {
        vector<T>r(v.size());
        for (int i = 0; i < v.size(); i++) r[i] = T{ v[i],1,0,1 };
        Base::init(r);
    }

    void update(int a, int b, mint x, mint y) {
        Base::upd(a, b, [x, y](T& a) {
            a.val = a.val * x + y * a.len;
            a.a *= x;
            a.b = a.b * x + y;
            });
    }
    ll query(int a, int b) {
        return Base::qry(a, b).val.v;
    }
private:
    void eval(T& par, T& a, T& b)override {
        a.val = a.val * par.a + par.b * a.len;
        a.a *= par.a; a.b = par.a * a.b + par.b;

        b.val = b.val * par.a + par.b * b.len;
        b.a *= par.a; b.b = par.a * b.b + par.b;

        par.a = 1; par.b = 0;
    }
    T proc(const T& a, const T& b)override {
        return T{ a.val + b.val,1,0,a.len + b.len };
    }
};
struct Monoid {
