// Segment Tree with Lazy Propagation 2
template <typename X, typename M>
struct LZPSegTree {
    using FX = function<X(X, X)>;
    using FA = function<X(X, M)>;
    using FM = function<M(M, M)>;
    using FP = function<M(M, int)>;
    int n;  FX fx;  FA fa;  FM fm;  FP fp; 
    const X ex;  const M em;
    vector<X> dat; vector<M> lazy;
    LZPSegTree(int n_,FX fx_,FA fa_,FM fm_,FP fp_,X ex_,M em_)
        : n(),fx(fx_),fa(fa_),fm(fm_),fp(fp_),ex(ex_),em(em_),dat(n_*4,ex),lazy(n_*4,em) {
        int x = 1; while (n_> x) {x *= 2;} n = x;
    }
    void set(int i, X x) {dat[i+n-1] = x; return;}
    void build() {rrep(k,n-1) dat[k] = fx(dat[2*k+1], dat[2*k+2]); return;}
    void eval(int k, int len) {
        if (lazy[k] == em) return; 
        if (k < n - 1) {          
            lazy[k*2+1] = fm(lazy[k*2+1], lazy[k]);
            lazy[k*2+2] = fm(lazy[k*2+2], lazy[k]);
        }
        dat[k] = fa(dat[k],fp(lazy[k],len)); lazy[k] = em;
        return;
    }
    void update(int a, int b, M x) {update_sub(a, b, x, 0, 0, n); return;}
    X query(int a, int b) {return query_sub(a, b, 0, 0, n);}
    private:
    void update_sub(int a, int b, M x, int k, int l, int r) {
        eval(k, r - l);
        if (a <= l && r <= b) {
            lazy[k] = fm(lazy[k], x);
            eval(k, r - l);
            return;
        }
        else if (a < r && l < b) {
            update_sub(a, b, x, k*2+ 1, l, (l+r)/2);
            update_sub(a, b, x, k*2+2, (l+r)/2, r);
            dat[k] = fx(dat[k*2+1], dat[k*2+2]);
            return;
        }
    }
    X query_sub(int a, int b, int k, int l, int r) {
        eval(k, r - l);
        if (r <= a || b <= l) return ex;
        else if (a <= l && r <= b) return dat[k];
        else { 
            X vl = query_sub(a, b, k*2+1, l, (l+r)/2);
            X vr = query_sub(a, b, k*2+2, (l+r)/2, r);
            return fx(vl, vr);
        }
    }

};

signed main() {
    int n, q; cin >> n >> q;
    using X = mint;
    using M = P;
    auto fx = [](X x1, X x2) -> X {return x1 + x2;};
    auto fa = [](X x, M m) -> X {return m.first * x + m.second;};
    auto fm = [](M m1, M m2) -> M {return P(m1.first*m2.first, m2.first*m1.second + m2.second);};
    auto fp = [](M m, int n) -> M {return P(m.first, m.second*n);};
    X ex = 0;
    M em = P(1,0);
    LZPSegTree<X, M> rzseg(n,fx,fa,fm,fp,ex,em);
    rep(i,n) {
        int a; cin >> a;
        rzseg.set(i,a);
    }
    rzseg.build();
    rep(i,q) {
        int t, l, r; cin >> t >> l >> r;
        if(t) {
            cout << rzseg.query(l,r) << endl;
        }
        else {
            mint b, c; cin >> b >> c;
            rzseg.update(l,r,P(b,c));
        }
    }
    return 0;
}

