atai xx(atai x,atai y){
	atai ret;
	ret.s=(x.s+y.s)%MOD;
	ret.len=x.len+y.len;
	return ret;
}
atai Tx(sayouso T,atai x){
	atai ret;
	ret.s=(T.a*x.s+T.b*x.len)%MOD;
	ret.len=x.len;
	return ret;
}
sayouso TT(sayouso S,sayouso T){
	sayouso ret;
	ret.a=S.a*T.a%MOD;
	ret.b=(S.b+S.a*T.b)%MOD;
	return ret;
}
