data class Seg(val sum: ModInt, val sz: Int) {
    operator fun plus(B: Seg) = Seg(sum + B.sum, sz + B.sz)
}

data class Affine(val a: ModInt, val b: ModInt) {
    fun compose(other: Affine) = Affine(a * other.a, b * other.a + other.b)
    operator fun invoke(seg: Seg) = Seg(a * seg.sum + b * seg.sz, seg.sz)
}
fun Affine(a: Int, b: Int) = Affine(ModInt(a), ModInt(b))

class PropagatingSegmentTree<T, U>(
    val size: Int,
    val identityValue: T,
    val op: (T, T) -> T,
    val updateIdentity: U,
    val composer: (U, U) -> U,
    val updater: (T, U) -> T
) {
    val tsize = if(size == 0) 0 else Integer.highestOneBit(size.shl(1) - 1)

    @Suppress("UNCHECKED_CAST")
    val A = Array<Any?>(tsize shl 1) { identityValue } as Array<T>
    @Suppress("UNCHECKED_CAST")
    val B = Array<Any?>(tsize) { updateIdentity } as Array<U>

    private val h = 32 - Integer.numberOfLeadingZeros(tsize)

    inline fun build(generator: (Int) -> T) {
        for(i in 0 until size) {
            A[tsize+i] = generator(i)
        }
        for(i in tsize-1 downTo 1) {
            A[i] = op(A[i shl 1], A[i shl 1 or 1])
        }
    }

    private fun calc(i: Int) {
        A[i] = op(A[i shl 1], A[i shl 1 or 1])
        A[i] = updater(A[i], B[i])
    }

    private fun apply(i: Int, u: U) {
        A[i] = updater(A[i], u)
        if(i < tsize) {
            B[i] = composer(B[i], u)
        }
    }

    private fun build(l: Int) {
        //var k = 2
        var l = l
        while(l > 1) {
            l = l shr 1
            calc(l)
            //k = k shl 1
        }
    }

    private fun push(l: Int) {
        var s = h
        //var k = 1 shl h-1
        while(s > 0) {
            val i = l shr s

            val b = B[i]
            if(b != updateIdentity) {
                apply(i shl 1, b)
                apply(i shl 1 or 1, b)
                B[i] = updateIdentity
            }

            s--
            //k = k shr 1
        }
    }

    fun update(start: Int, endExclusive: Int, b: U) {
        var l = maxOf(start, 0) + tsize
        var r = minOf(endExclusive, size) + tsize

        push(l)
        push(r-1)
        val l0 = l
        val r0 = r

        //var k = 1

        while(l < r) {
            if(l and 1 == 1) {
                apply(l++, b)
            }
            if(r and 1 == 1) {
                apply(--r, b)
            }

            l = l shr 1
            r = r shr 1
            //k = k shl 1
        }

        build(l0)
        build(r0-1)
    }

    fun query(start: Int, endExclusive: Int): T {
        var l = maxOf(start, 0) + tsize
        var r = minOf(endExclusive, size) + tsize

        push(l)
        push(r-1)

        var lacc = identityValue
        var racc = identityValue

        while(l < r) {
            if(l and 1 == 1) {
                lacc = op(lacc, A[l++])
            }
            if(r and 1 == 1) {
                racc = op(A[--r], racc)
            }

            l = l shr 1
            r = r shr 1
        }

        return op(lacc, racc)
    }

    val root get() = A[1]
}

