class RangeAffineRangeSum(val size: Int) {
    /* degenericization helpers */
    val A = ModIntArray(size shl 1)
    val B = ModIntArray(size) { ModInt(1) }
    val C = ModIntArray(size)
    val D = BooleanArray(size)

    private val h = 32 - Integer.numberOfLeadingZeros(size)

    inline fun build(generator: (Int) -> ModInt) {
        for(i in 0 until size) {
            A[size+i] = generator(i)
        }
        for(i in size-1 downTo 1) {
            A[i] = A[i shl 1] + A[i shl 1 or 1]
        }
    }

    private fun calc(p: Int, k: Int) {
        val b = B[p]
        val c = C[p]
        A[p] = A[p shl 1] + A[p shl 1 or 1]
        A[p] = b * A[p] + c * k
    }

    private fun apply(p: Int, b: ModInt, c: ModInt, k: Int) {
        A[p] = b * A[p] + c * k
        if(p < size) {
            B[p] *= b
            C[p] = C[p] * b + c
            D[p] = true
        }
    }

    private fun build(l: Int) {
        var k = 2
        var l = l
        while(l > 1) {
            l = l shr 1
            calc(l, k)
            k = k shl 1
        }
    }

    private fun push(l: Int) {
        var s = h
        var k = 1 shl h-1
        while(s > 0) {
            val i = l shr s

            val b = B[i]
            val c = C[i]
            if(D[i]) {
                apply(i shl 1, b, c, k)
                apply(i shl 1 or 1, b, c, k)
                B[i] = ModInt(1)
                C[i] = ModInt(0)
                D[i] = false
            }

            s--
            k = k shr 1
        }
    }

    fun update(start: Int, endExclusive: Int, b: ModInt, c: ModInt) {
        var l = maxOf(start, 0) + size
        var r = minOf(endExclusive, size) + size

        push(l)
        push(r-1)
        val l0 = l
        val r0 = r

        var k = 1

        while(l < r) {
            if(l and 1 == 1) {
                apply(l++, b, c, k)
            }
            if(r and 1 == 1) {
                apply(--r, b, c, k)
            }

            l = l shr 1
            r = r shr 1
            k = k shl 1
        }

        build(l0)
        build(r0-1)
    }

    fun query(start: Int, endExclusive: Int): ModInt {
        var l = maxOf(start, 0) + size
        var r = minOf(endExclusive, size) + size

        push(l)
        push(r-1)

        var acc = ModInt(0)

        while(l < r) {
            if(l and 1 == 1) {
                acc += A[l++]
            }
            if(r and 1 == 1) {
                acc += A[--r]
            }

            l = l shr 1
            r = r shr 1
        }

        return acc
    }
}

const val MOD = 998244353
const val TOTIENT = MOD - 1 // assumes MOD is prime

infix fun Int.modulo(mod: Int): Int = (this % mod).let { (it shr Int.SIZE_BITS - 1 and mod) + it }
infix fun Long.modulo(mod: Long) = (this % mod).let { (it shr Long.SIZE_BITS - 1 and mod) + it }
infix fun Long.modulo(mod: Int) = modulo(mod.toLong()).toInt()

fun Int.mulMod(other: Int, mod: Int) = toLong() * other modulo mod

fun Int.powMod(exponent: Long, mod: Int): Int {
    if(exponent < 0) error("Inverse not implemented")
    var res = 1L
    var e = exponent
    var b = modulo(mod).toLong()

    while(e > 0) {
        if(e and 1 == 1L) {
            res = res * b % mod
        }
        e = e shr 1
        b = b * b % mod
    }
    return res.toInt()
}
fun Int.powMod(exponent: Int, mod: Int) = powMod(exponent.toLong(), mod)
fun Int.modPowArray(n: Int, mod: Int): IntArray {
    val res = IntArray(n+1)
    res[0] = 1
    for(i in 1..n) res[i] = mulMod(res[i-1], mod)
    return res
}

