class PropagatingSegmentTree(
    val size: Int //,
//    val identityValue: T,
//    val combiner: (T, T) -> T,
//    val updateIdentity: U,
//    val updateCombiner: (U, U) -> U,
//    val updater: (T, U) -> T
) {
    /* degenericization helpers */
    inline val identityValue: ModInt get() = ModInt(0)
    inline fun combiner(a: ModInt, b: ModInt): ModInt = a + b
    val updateIdentity: Affine = Affine(1, 0)
    inline fun updateCombiner(a: Affine, b: Affine): Affine = a.compose(b)
    fun updater(t: ModInt, u: Affine, a: Int, b: Int): ModInt {
        val sz = b-a+1
        return t * u.a + u.b * sz
    }

    private inline fun treeSize() = if(size == 0) 0 else Integer.highestOneBit(size.shl(2) - 1)

    @Suppress("UNCHECKED_CAST")
    private val tree = ModIntArray(treeSize())// { identityValue } as Array<ModInt>
    @Suppress("UNCHECKED_CAST")
    private val lazy = Array<Affine>(tree.size) { updateIdentity }

    fun build(list: ModIntArray) {
        if(size == 0) return
        build(list, 1, 0, size-1)
    }

    inline fun build(generator: (Int) -> ModInt) { build(ModIntArray(size) { generator(it) }) }

    private inline fun mid(low: Int, high: Int) = (low + high) shr 1
    private fun build(list: ModIntArray, node: Int, a: Int, b: Int) {
        if(a == b) {
            tree[node] = list[a]
            return
        }

        build(list, node shl 1, a, mid(a, b))
        build(list, node shl 1 or 1, 1 + mid(a, b), b)
        updateNode(node)
    }

    private inline fun updateNode(i: Int) {
        tree[i] = combiner(tree[i shl 1], tree[i shl 1 or 1])
    }

    fun update(start: Int, endx: Int, value: Affine) {
        update(1, 0, size-1, start, endx-1, value)
    }
    fun update(range: IntRange, value: Affine) {
        update(range.first, range.last + 1, value)
    }

    private inline fun updateLazy(i: Int, u: Affine) {
        lazy[i] = updateCombiner(lazy[i], u)
    }

    private fun propagate(node: Int, a: Int, b: Int) {
        tree[node] = updater(tree[node], lazy[node], a, b)
        if(a != b) {
            updateLazy(node shl 1, lazy[node])
            updateLazy(node shl 1 or 1, lazy[node])
        }
        lazy[node] = updateIdentity
    }

    private fun update(node: Int, a: Int, b: Int, i: Int, j: Int, u: Affine) {
        if(lazy[node] != updateIdentity) {
            propagate(node, a, b)
        }

        if(a > b || a > j || b < i) return

        if(a >= i && b <= j) {
            lazy[node] = u
            propagate(node, a, b)
            return
        }

        update(node shl 1, a, mid(a, b), i, j, u)
        update(node shl 1 or 1, 1 + mid(a, b), b, i, j, u)

        updateNode(node)
    }

    fun query(start: Int, endx: Int) =
        query(1, 0, size-1, start, endx-1)
    fun query(range: IntRange) =
        query(range.first, range.last+1)

    private fun query(node: Int, a: Int, b: Int, i: Int, j: Int): ModInt {
        if(a > b || a > j || b < i) return identityValue
        if(lazy[node] != updateIdentity) {
            propagate(node, a, b)
        }

        if(a >= i && b <= j) {
            return tree[node]
        }

        val l = query(node shl 1, a, mid(a, b), i, j)
        val r = query(node shl 1 or 1, 1 + mid(a, b), b, i, j)

        return combiner(l, r)
    }

    val root get() = tree[1]
}

