@FunctionalInterface
interface BinaryConsumer<T> extends BiConsumer<T, T> {  }
@FunctionalInterface
interface TriConsumer<S, T, U> {
	void accept(S s, T t, U u);
	default TriConsumer<S, T, U> andThen(TriConsumer<? super S,? super T,? super U> after) {
		Objects.requireNonNull(after);
		return (S s, T t, U u) -> { accept(s, t, u); after.accept(s, t, u); };
	}
}
@FunctionalInterface
interface TriFunction<S, T, U, R> {
	R apply(S s, T t, U u);
	default <V> TriFunction<S, T, U, V> andThen(Function<? super R, ? extends V> after) {
		Objects.requireNonNull(after);
			return (S s, T t, U u) -> after.apply(apply(s, t, u));
	}
}

@FunctionalInterface
interface LazyFunction<T> {
	long apply(long s, T t, int u);
}

class LazySegTree<T> {
	long e;
	LongBinaryOperator f;
	Supplier<T> e2;
	BinaryConsumer<T> g;
	LazyFunction<T> h;

	int n;
	long nodes[];
	T lazy[];

	LazySegTree(long[] a, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, LazyFunction<T> h) { init(a, e, f, e2, g, h); } // O(N)
	LazySegTree(int len, long x, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, LazyFunction<T> h) { // O(N)
		@SuppressWarnings("unchecked")
		long a[] = new long[len];
		fill(a, x);
		init(a, e, f, e2, g, h);
	}
	LazySegTree(int len, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, LazyFunction<T> h) { init(len, e, f, e2, g, h); } // O(N)

	void init(long[] a, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, LazyFunction<T> h) { // O(N)
		init(a.length, e, f, e2, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n - 1] = a[i];
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.applyAsLong(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}
	void init(int len, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, LazyFunction<T> h) { // O(N)
		this.e = e;
		this.f = f;
		this.e2 = e2;
		this.g = g;
		this.h = h;
		n = 1;
		while(n < len) n *= 2;
		nodes = new long[n * 2 - 1];
		fill(nodes, e);
		@SuppressWarnings("unchecked")
		T tmp2[] = (T[]) new Object[n * 2 - 1];
		lazy = tmp2;
		for(int i = 0; i < lazy.length; i ++) lazy[i] = e2.get();
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.applyAsLong(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}

	void eval(int k, int l, int r) { // O(1)
		if(!lazy[k].equals(e2.get())) {
			nodes[k] = h.apply(nodes[k], lazy[k], r - l);
			if(r - l > 1) {
				g.accept(lazy[k * 2 + 1], lazy[k]);
				g.accept(lazy[k * 2 + 2], lazy[k]);
			}
			lazy[k] = e2.get();
		}
	}

	void update(int a, int b, T val) { update(a, b, val, 0, 0, n); } // O(logN)
	void update(int a, int b, T val, int k, int l, int r) { // O(logN)
		eval(k, l, r);
		if(b <= l || r <= a) return;
		if(a <= l && r <= b) {
			g.accept(lazy[k], val);
			eval(k, l, r);
			return;
		}
		update(a, b, val, k * 2 + 1, l, (l + r) / 2);
		update(a, b, val, k * 2 + 2, (l + r) / 2, r);
		nodes[k] = f.applyAsLong(nodes[k * 2 + 1], nodes[k * 2 + 2]);
	}

	long get(int i) { return find(i, i + 1); } // O(logN)
	long find(int a, int b) { return find(a, b, 0, 0, n); } // O(logN)
	long find(int a, int b, int k, int l, int r) { // O(logN)
		if(b <= l || r <= a) return e;
		eval(k, l, r);
		if(a <= l && r <= b) return nodes[k];
		return f.applyAsLong(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	long acc;
	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(LongPredicate check) { return findLeftmost(0, check); }
	int findLeftmost(int a, LongPredicate check) { return findLeftmost(a, n, check); }
	int findLeftmost(int a, int b, LongPredicate check) { acc = e; return findLeftmost(a, b, check, 0, 0, n); }
	int findLeftmost(int a, int b, LongPredicate check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		long tmp = f.applyAsLong(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findLeftmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
		return vr >= 0 ? vr : findLeftmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(LongPredicate check) { return findRightmost(n, check); }
	int findRightmost(int b, LongPredicate check) { return findRightmost(0, b, check); }
	int findRightmost(int a, int b, LongPredicate check) { acc = e; return findRightmost(a, b, check, 0, 0, n); }
	int findRightmost(int a, int b, LongPredicate check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		long tmp = f.applyAsLong(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findRightmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
		return vr >= 0 ? vr : findRightmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
	}
}

	}
}

import java.io.*;
import java.util.*;

class Query {
  final int type, l, r;
  final AffineOperator affineOperator;

  Query(int type, int l, int r, AffineOperator affineOperator) {
    this.type = type;
    this.l = l;
    this.r = r;
    this.affineOperator = affineOperator;
  }
}

class AffineOperator {
  final long b, c;

  AffineOperator(long b, long c) {
    this.b = b;
    this.c = c;
  }
}

public class Main {
  private static final ModCalculator mc = new ModCalculator(998244353L);

  private static final Long ZERO = Long.valueOf(0L);

  private static final UpdateRangeGetRangeSegmentTree.Operator<AffineOperator, Long> OPERATOR = new UpdateRangeGetRangeSegmentTree.Operator<>() {

    @Override
    public AffineOperator multiplyLazyValue(AffineOperator lazy, int count) {
      return new AffineOperator(lazy.b, mc.mul(lazy.c, count));
    }

    @Override
    public AffineOperator applyOffset(AffineOperator lazy, int offset) {
      return lazy;
    }

    @Override
    public AffineOperator mergeLazyValue(AffineOperator oldLazy, AffineOperator newLazy) {
      if (oldLazy == null) {
        return newLazy;
      }
      // v -> oldLazy.b * v + lodLazy.c
      // oldLazy.b * v + lodLazy.c -> (oldLazy.b * v + oldLazy.c) * newLazy.b + newLazy.c
      // -> oldLazy.b * newLazy.b * v + (oldLazy.c * newLazy.b) + newLazy.c

      long b = mc.mul(oldLazy.b, newLazy.b);
      long c = mc.add(mc.mul(oldLazy.c, newLazy.b), newLazy.c);
      return new AffineOperator(b, c);
    }

    @Override
    public Long apply(Long value, AffineOperator lazy) {
      return mc.add(mc.mul(value, lazy.b), lazy.c);
    }

    @Override
    public Long mergeValue(Long smallIndexValue, Long largeIndexValue) {
      return mc.add(smallIndexValue, largeIndexValue);
    }

    @Override
    public Long getUnitValue() {
      return ZERO;
    }
  };

  private static List<Long> solve(int n, int q, int[] as, Query[] queries) {
    Long[] initialValues = new Long[n];
    for (int i = 0; i < n; i++) {
      initialValues[i] = Long.valueOf(as[i]);
    }
    UpdateRangeGetRangeSegmentTree<AffineOperator, Long> segmentTree = new UpdateRangeGetRangeSegmentTree<>(OPERATOR, initialValues);
    List<Long> answers = new ArrayList<>();
    for (Query query : queries) {
      if (query.type == 0) {
        segmentTree.update(query.l, query.r, query.affineOperator);
      } else {
        answers.add(segmentTree.getRange(query.l, query.r));
      }
    }
    return answers;
  }

  private static void execute(ContestReader reader, ContestWriter out) {
    int n = reader.nextInt();
    int q = reader.nextInt();
    int[] as = reader.nextInt(n);
    Query[] queries = new Query[q];
    for (int i = 0; i < q; i++) {
      int type = reader.nextInt();
      int l = reader.nextInt();
      int r = reader.nextInt();
      AffineOperator affineOperator = null;
      if (type == 0) {
        int b = reader.nextInt();
        int c = reader.nextInt();
        affineOperator = new AffineOperator(b, c);
      }
      queries[i] = new Query(type, l, r, affineOperator);
    }
    out.printList(solve(n, q, as, queries));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    ContestWriter out = new ContestWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ModCalculator {
  private final long mod;
  private final ModInverseCache modInverseCache;
  private final ModCombinationCache modCombinationCache;

  ModCalculator(long mod) {
    this.mod = mod;
    this.modInverseCache = new ModInverseCache();
    this.modCombinationCache = new ModCombinationCache();
  }

  public long norm(long v) {
    long nogmalized = v % mod;
    if (nogmalized < 0) {
      nogmalized += mod;
    }
    return nogmalized;
  }

  public long add(long a, long b) {
    return norm(a + b);
  }

  public long sub(long a, long b) {
    return norm(a - b + mod);
  }

  public long mul(long a, long b) {
    return norm(a * b);
  }

  public long pow(long a, long b) {
    if (b == 0) {
      return 1;
    }
    long v = pow(mul(a, a), b / 2);
    if (b % 2 == 1) {
      return mul(v, a);
    } else {
      return v;
    }
  }

  public long inverse(long a) {
    return pow(a, mod - 2);
  }

  public long div(long a, long b) {
    return mul(a, inverse(b));
  }

  // Verify ARC 042 D
  // https://atcoder.jp/contests/arc042/tasks/arc042_d
  // a^x mod p === b
  // return -1 there is no such positive x
  public long log(long a, long b) {
    Map<Long, Long> map = new HashMap<>();
    long powA = 1;
    long rootP = 0;
    while (true) {
      if (powA == b && rootP != 0) {
        return rootP;
      }
      if (map.containsKey(powA)) {
        return -1;
      }
      map.put(powA, rootP);
      powA = mul(powA, a);
      rootP++;
      if (rootP * rootP > mod) {
        break;
      }
    }
    long inversePowA = inverse(powA);
    for (int i = 1; i <= rootP; i++) {
      b = mul(b, inversePowA);
      Long value = map.get(b);
      if (value != null && value + rootP * i > 0) {
        return value + rootP * i;
      }
    }
    return -1;
  }

  public long getF(int n) {
    return modCombinationCache.getF(n);
  }

  public long getP(int n, int r) {
    return modCombinationCache.getP(n, r);
  }

  public long getC(int n, int k) {
    return modCombinationCache.getC(n, k);
  }

  // Verify ttpc2019 J
  // https://atcoder.jp/contests/ttpc2019/tasks/ttpc2019_j
  class PrimitiveLongList {
    long[] values;
    int size;

    public PrimitiveLongList() {
      values = new long[10];
    }

    private void resize() {
      long[] newValues = new long[values.length * 2];
      System.arraycopy(values, 0, newValues, 0, values.length);
      values = newValues;
    }

    public void add(long value) {
      if (size >= values.length) {
        resize();
      }
      values[size] = value;
      size++;
    }

    private void validateIndex(int index) {
      if (index < 0 || size <= index) {
        throw new IndexOutOfBoundsException(String.format("size: %d, index: %d", size, index));
      }
    }

    public long get(int index) {
      validateIndex(index);
      return values[index];
    }

    public void set(int index, long value) {
      validateIndex(index);
      values[index] = value;
    }

    public int size() {
      return size;
    }
  }

  // Verify AGC 040 C
  // https://atcoder.jp/contests/agc040/tasks/agc040_c
  class ModInverseCache {
    private final PrimitiveLongList inverseCache;

    public ModInverseCache() {
      inverseCache = new PrimitiveLongList();
      inverseCache.add(0L);
      inverseCache.add(1L);
    }

    private void resize(int n) {
      for (int i = inverseCache.size(); i <= n; i++) {
        long k = mod / i;
        int r = (int)(mod % i);
        long inverse = mul(-k, inverseCache.get(r));
        inverseCache.add(inverse);
      }
    }

    long get(int n) {
      resize(n);
      return inverseCache.get(n);
    }
  }

  class ModCombinationCache {
    private final PrimitiveLongList factorialCache;
    private final PrimitiveLongList factorialInverseCache;

    public ModCombinationCache() {
      factorialCache = new PrimitiveLongList();
      factorialCache.add(1L);
      factorialInverseCache = new PrimitiveLongList();
      factorialInverseCache.add(1L);
    }

    private void resize(int n) {
      for (int i = factorialCache.size() - 1; i < n; i++) {
        factorialCache.add(mul(factorialCache.get(i), i + 1));
        factorialInverseCache.add(mul(factorialInverseCache.get(i), modInverseCache.get(i + 1)));
      }
    }

    long getF(int n) {
      resize(n);
      return factorialCache.get(n);
    }

    long getP(int n, int r) {
      resize(n);
      return mul(factorialCache.get(n), factorialInverseCache.get(n - r));
    }

    long getC(int n, int k) {
      resize(n);
      return mul(factorialCache.get(n), mul(factorialInverseCache.get(k), factorialInverseCache.get(n-k)));
    }
  }
}

