public void solve() {
	int num = ni();
	int query = ni();
	Long a[] = new Long[num];
	for(int i = 0; i < num; i ++) a[i] = nl();
	LazySegTree<Long, PairLL> st = new LazySegTree<>(a,
			0l, (ele1, ele2) -> mod(ele1 + ele2),
			new PairLL(1, 0), (ele1, ele2) -> new PairLL(mod(ele1.a * ele2.a), mod(ele1.b * ele2.a + ele2.b)),
			(ele1, ele2, ele3) -> mod(ele1 * ele2.a + ele2.b * ele3));
	for(int q = 0; q < query; q ++) {
		switch(ni()) {
		case 0: st.update(ni(), ni(), npll()); break;
		case 1: prtln(st.find(ni(), ni())); break;
		}
		for(int i = 0; i < num; i ++) st.get(i);
	}
}
@FunctionalInterface
public interface TriFunction<S, T, U, R> {
	R apply(S s, T t, U u);
	default <V> TriFunction<S, T, U, V> andThen(Function<? super R, ? extends V> after) {
		Objects.requireNonNull(after);
		return (S s, T t, U u) -> after.apply(apply(s, t, u));
	}
}

class LazySegTree<T, U> {
	T e;
	BinaryOperator<T> f;
	U e2;
	BinaryOperator<U> g;
	TriFunction<T, U, Integer, T> h;

	int n;
	T nodes[];
	U lazy[];

	LazySegTree(T[] a, T e, BinaryOperator<T> f, U e2, BinaryOperator<U> g, TriFunction<T, U, Integer, T> h) { init(a, e, f, e2, g, h); } // O(N)
	LazySegTree(int len, T x, T e, BinaryOperator<T> f, U e2, BinaryOperator<U> g, TriFunction<T, U, Integer, T> h) { // O(N)
		@SuppressWarnings("unchecked")
		T a[] = (T[]) new Object[len];
		for(int i = 0; i < len; i ++) a[i] = x;
		init(a, e, f, e2, g, h);
	}
	LazySegTree(int len, T e, BinaryOperator<T> f, U e2, BinaryOperator<U> g, TriFunction<T, U, Integer, T> h) { init(len, e, f, e2, g, h); } // O(N)

	void init(T[] a, T e, BinaryOperator<T> f, U e2, BinaryOperator<U> g, TriFunction<T, U, Integer, T> h) { // O(N)
		init(a.length, e, f, e2, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n - 1] = a[i];
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.apply(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}
	void init(int len, T e, BinaryOperator<T> f, U e2, BinaryOperator<U> g, TriFunction<T, U, Integer, T> h) { // O(N)
		this.e = e;
		this.f = f;
		this.e2 = e2;
		this.g = g;
		this.h = h;
		n = 1;
		while(n < len) n *= 2;
		@SuppressWarnings("unchecked")
		T tmp[] = (T[]) new Object[n * 2 - 1];
		this.nodes = tmp;
		for(int i = 0; i < nodes.length; i ++) nodes[i] = e;
		@SuppressWarnings("unchecked")
		U tmp2[] = (U[]) new Object[n * 2 - 1];
		this.lazy = tmp2;
		for(int i = 0; i < lazy.length; i ++) lazy[i] = e2;
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.apply(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}

	void eval(int k, int l, int r) { // O(1)
		if(!lazy[k].equals(e2)) {
			nodes[k] = h.apply(nodes[k], lazy[k], r - l);
			if(r - l > 1) {
				lazy[k * 2 + 1] = g.apply(lazy[k * 2 + 1], lazy[k]);
				lazy[k * 2 + 2] = g.apply(lazy[k * 2 + 2], lazy[k]);
			}
			lazy[k] = e2;
		}
	}

	void update(int a, int b, U val) { update(a, b, val, 0, 0, n); } // O(logN)
	void update(int a, int b, U val, int k, int l, int r) { // O(logN)
		eval(k, l, r);
		if(b <= l || r <= a) return;
		if(a <= l && r <= b) {
			lazy[k] = g.apply(lazy[k], val);
			eval(k, l, r);
			return;
		}
		update(a, b, val, k * 2 + 1, l, (l + r) / 2);
		update(a, b, val, k * 2 + 2, (l + r) / 2, r);
		nodes[k] = f.apply(nodes[k * 2 + 1], nodes[k * 2 + 2]);
	}

	T get(int i) { return find(i, i + 1); } // O(logN)
	T find(int a, int b) { return find(a, b, 0, 0, n); } // O(logN)
	T find(int a, int b, int k, int l, int r) { // O(logN)
		eval(k, l, r);
		if(b <= l || r <= a) return e;
		if(a <= l && r <= b) return nodes[k];
		return f.apply(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	T acc;
	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(Predicate<T> check) { return findLeftmost(0, check); }
	int findLeftmost(int a, Predicate<T> check) { return findLeftmost(a, n, check); }
	int findLeftmost(int a, int b, Predicate<T> check) { acc = e; return findLeftmost(a, b, check, 0, 0, n); }
	int findLeftmost(int a, int b, Predicate<T> check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		T tmp = f.apply(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findLeftmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
		return vr >= 0 ? vr : findLeftmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(Predicate<T> check) { return findRightmost(n, check); }
	int findRightmost(int b, Predicate<T> check) { return findRightmost(0, b, check); }
	int findRightmost(int a, int b, Predicate<T> check) { acc = e; return findRightmost(a, b, check, 0, 0, n); }
	int findRightmost(int a, int b, Predicate<T> check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		T tmp = f.apply(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findRightmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
		return vr >= 0 ? vr : findRightmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
	}
}

	}
}

public class Main {
    static ModIntFactory fac = new ModIntFactory(998244353);
    public static void main(String[] args) throws Exception {
        var sc = new FastScanner();
        var pw = new FastPrintStream();
        solve(sc, pw);
        sc.close();
        pw.flush();
        pw.close();
    }

    public static void solve(FastScanner sc, FastPrintStream pw) {
        int n = sc.nextInt();
        int q = sc.nextInt();
        var a = new long[n];
        java.util.Arrays.setAll(a, i -> sc.nextLong());
        var t = new RangeAffineRangeSum(a, fac);
        while (q --> 0) {
            if (sc.nextInt() == 0) {
                int l = sc.nextInt();
                int r = sc.nextInt();
                int b = sc.nextInt();
                int c = sc.nextInt();
                t.affine(l, r, b, c);
            } else {
                int l = sc.nextInt();
                int r = sc.nextInt();
                pw.println(t.sum(l, r).value());
            }
        }
    }
}

class RangeAffineRangeSum {

    private final ModIntFactory.ModInt[] dat, lzA, lzB;
    private final int n;
    private final int log;
    private final ModIntFactory fac;
    private final ModIntFactory.ModInt ONE, ZERO;

    public RangeAffineRangeSum(int n, ModIntFactory fac) {
        int k = 1; while (k < n) k <<= 1;
        this.dat = new ModIntFactory.ModInt[k << 1];
        this.lzA = new ModIntFactory.ModInt[k];
        this.lzB = new ModIntFactory.ModInt[k];
        this.fac = fac;
        this.ONE = fac.create(1);
        this.ZERO = fac.create(0);
        this.n = k;
        this.log = Integer.numberOfTrailingZeros(k);
        java.util.Arrays.fill(dat, ZERO);
        java.util.Arrays.fill(lzA, ONE);
        java.util.Arrays.fill(lzB, ZERO);
    }

    public RangeAffineRangeSum(long[] dat, ModIntFactory fac) {
        this(dat.length, fac);
        build(dat);
    }

    private void build(long[] a) {
        for (int i = 0; i < a.length; i++) {
            dat[i + n] = fac.create(a[i]);
        }
        for (int i = n - 1; i > 0; i--) {
            dat[i] = dat[i << 1 | 0].add(dat[i << 1 | 1]);
        }
    }

    private void push(int k, int h) {
        if (lzA[k].equals(ONE) && lzB[k].equals(ZERO)) return;
        int lk = k << 1 | 0, rk = k << 1 | 1;
        dat[lk] = dat[lk].mul(lzA[k]).add(lzB[k].mul(1 << h - 1));
        dat[rk] = dat[rk].mul(lzA[k]).add(lzB[k].mul(1 << h - 1));
        if (lk < n) {
            lzA[lk] = lzA[lk].mul(lzA[k]);
            lzB[lk] = lzA[lk].mul(lzA[k]).add(lzB[k]);
        }
        if (rk < n) {
            lzA[rk] = lzA[rk].mul(lzA[k]);
            lzB[rk] = lzA[rk].mul(lzA[k]).add(lzB[k]);
        }
        lzA[k] = ONE;
        lzB[k] = ZERO;
    }

    private void pushTo(int k) {
        for (int i = log; i > 0; i--) push(k >> i, i);
    }

    private void pushTo(int lk, int rk) {
        for (int i = log; i > 0; i--) {
            if (((lk >> i) << i) != lk) push(lk >> i, i);
            if (((rk >> i) << i) != rk) push(rk >> i, i);
        }
    }

    private void updateFrom(int k) {
        k >>= 1;
        while (k > 0) {
            dat[k] = dat[k << 1 | 0].add(dat[k << 1 | 1]);
            k >>= 1;
        }
    }

    private void updateFrom(int lk, int rk) {
        for (int i = 1; i <= log; i++) {
            if (((lk >> i) << i) != lk) {
                int lki = lk >> i;
                dat[lki] = dat[lki << 1 | 0].add(dat[lki << 1 | 1]);
            }
            if (((rk >> i) << i) != rk) {
                int rki = (rk - 1) >> i;
                dat[rki] = dat[rki << 1 | 0].add(dat[rki << 1 | 1]);
            }
        }
    }

    public ModIntFactory.ModInt get(int i) {
        pushTo(i + n);
        return dat[i + n];
    }

    public ModIntFactory.ModInt sum(int l, int r) {
        if (l == r) return fac.create(0);
        l += n; r += n;
        pushTo(l, r);
        ModIntFactory.ModInt sum = fac.create(0);
        while (l < r) {
            if ((l & 1) == 1) sum.add(dat[l++]);
            if ((r & 1) == 1) sum.add(dat[--r]);
            l >>= 1; r >>= 1;
        }
        return sum;
    }

    public ModIntFactory.ModInt sum() {
        return fac.create(dat[1].value());
    }

    public void affine(int i, long a, long b) {
        pushTo(i + n);
        dat[i + n] = dat[i + n].mul(a).add(b);
        updateFrom(i + n);
    }

    public void affine(int l, int r, long a, long b) {
        if (l == r) return;
        l += n; r += n;
        pushTo(l, r);
        for (int l2 = l, r2 = r, w = 1; l2 < r2; w <<= 1) {
            if ((l2 & 1) == 1) {
                dat[l2] = dat[l2].mul(a).add(b * w);
                if (l2 < n) {
                    lzA[l2] = lzA[l2].mul(a);
                    lzB[l2] = lzB[l2].mul(a).add(b);
                }
                l2++;
            }
            if ((r2 & 1) == 1) {
                r2--;
                dat[r2] = dat[r2].mul(a).add(b * w);
                if (r2 < n) {
                    lzA[r2] = lzA[r2].mul(a);
                    lzB[r2] = lzB[r2].mul(a).add(b);
                }
            }
            l2 >>= 1; r2 >>= 1;
        }
        updateFrom(l, r);
    }
