        Mods[] a = new Mods[N];
        for(int n=0; n<N; n++) a[n] =  new Mods(mf.create(sc.nextLong()), 1);

        LazySegTree<Mods, ModAffine> seg = 
          new LazySegTree<>(a,
                            Mods::merge,
                            Mods.id,
                            (f,s)->f.apply(s),
                            ModAffine::comp,
                            ModAffine.id(998244353)); 

