				return c;
			}
		}
		class TupleDDD implements Comparable<TupleDDD> {
			double a; double b; double c;
			TupleDDD() {  }
			TupleDDD(double a, double b, double c) { this.a = a; this.b = b; this.c = c; }
			@Override public String toString() { return "("+a+", "+b+", "+c+")"; }
			@Override public int hashCode() { return Objects.hash(a, b, c); }
			@Override
			public boolean equals(Object obj) {
				if(this == obj) return true;
				if(obj == null || this.getClass() != obj.getClass()) return false;
				TupleDDD that = (TupleDDD) obj;
				if(this.a != that.a || this.b != that.b || this.c != that.c) return false;
				return true;
			}
			@Override
			public int compareTo(TupleDDD that) {
				int c = Double.compare(this.a, that.a);
				if(c == 0) c = Double.compare(this.b, that.b);
				if(c == 0) c = Double.compare(this.c, that.c);
				return c;
			}
		}

public void solve() {
	int num = ni();
	int query = ni();
	Long a[] = new Long[num];
	for(int i = 0; i < num; i ++) a[i] = nl();
	LazySegTree<Long, PairLL> st = new LazySegTree<>(a,
			() -> 0l, (ele1, ele2) -> mod(ele1 + ele2),
			() -> new PairLL(1, 0), (ele1, ele2) -> { ele1.a = mod(ele1.a * ele2.a); ele1.b = mod(ele1.b * ele2.a + ele2.b); },
			(ele1, ele2, ele3) -> ele1 = mod(ele1 * ele2.a + ele2.b * ele3));
	for(int q = 0; q < query; q ++) {
		switch(ni()) {
		case 0: st.update(ni(), ni(), npll()); break;
		case 1: prtln(st.find(ni(), ni())); break;
		}
		for(int i = 0; i < num; i ++) st.get(i);
	}
}
@FunctionalInterface
interface BinaryConsumer<T> extends BiConsumer<T, T> {  }
@FunctionalInterface
interface TriConsumer<S, T, U> {
	void accept(S s, T t, U u);
	default TriConsumer<S, T, U> andThen(TriConsumer<? super S,? super T,? super U> after) {
		Objects.requireNonNull(after);
		return (S s, T t, U u) -> { accept(s, t, u); after.accept(s, t, u); };
	}
}
@FunctionalInterface
interface TriFunction<S, T, U, R> {
	R apply(S s, T t, U u);
	default <V> TriFunction<S, T, U, V> andThen(Function<? super R, ? extends V> after) {
		Objects.requireNonNull(after);
		return (S s, T t, U u) -> after.apply(apply(s, t, u));
	}
}

class LazySegTree<T, U> {
	Supplier<T> e;
	BinaryOperator<T> f;
	Supplier<U> e2;
	BinaryConsumer<U> g;
	TriFunction<T, U, Integer, T> h;

	int n;
	T nodes[];
	U lazy[];

	LazySegTree(T[] a, Supplier<T> e, BinaryOperator<T> f, Supplier<U> e2, BinaryConsumer<U> g, TriFunction<T, U, Integer, T> h) { init(a, e, f, e2, g, h); } // O(N)
	LazySegTree(int len, Supplier<T> x, Supplier<T> e, BinaryOperator<T> f, Supplier<U> e2, BinaryConsumer<U> g, TriFunction<T, U, Integer, T> h) { // O(N)
		@SuppressWarnings("unchecked")
		T a[] = (T[]) new Object[len];
		for(int i = 0; i < len; i ++) a[i] = x.get();
		init(a, e, f, e2, g, h);
	}
	LazySegTree(int len, Supplier<T> e, BinaryOperator<T> f, Supplier<U> e2, BinaryConsumer<U> g, TriFunction<T, U, Integer, T> h) { init(len, e, f, e2, g, h); } // O(N)

	void init(T[] a, Supplier<T> e, BinaryOperator<T> f, Supplier<U> e2, BinaryConsumer<U> g, TriFunction<T, U, Integer, T> h) { // O(N)
		init(a.length, e, f, e2, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n - 1] = a[i];
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.apply(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}
	void init(int len, Supplier<T> e, BinaryOperator<T> f, Supplier<U> e2, BinaryConsumer<U> g, TriFunction<T, U, Integer, T> h) { // O(N)
		this.e = e;
		this.f = f;
		this.e2 = e2;
		this.g = g;
		this.h = h;
		n = 1;
		while(n < len) n *= 2;
		@SuppressWarnings("unchecked")
		T tmp[] = (T[]) new Object[n * 2 - 1];
		this.nodes = tmp;
		for(int i = 0; i < nodes.length; i ++) nodes[i] = e.get();
		@SuppressWarnings("unchecked")
		U tmp2[] = (U[]) new Object[n * 2 - 1];
		this.lazy = tmp2;
		for(int i = 0; i < lazy.length; i ++) lazy[i] = e2.get();
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.apply(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}

	void eval(int k, int l, int r) { // O(1)
		if(!lazy[k].equals(e2.get())) {
			nodes[k] = h.apply(nodes[k], lazy[k], r - l);
			if(r - l > 1) {
				g.accept(lazy[k * 2 + 1], lazy[k]);
				g.accept(lazy[k * 2 + 2], lazy[k]);
			}
			lazy[k] = e2.get();
		}
	}

	void update(int a, int b, U val) { update(a, b, val, 0, 0, n); } // O(logN)
	void update(int a, int b, U val, int k, int l, int r) { // O(logN)
		eval(k, l, r);
		if(b <= l || r <= a) return;
		if(a <= l && r <= b) {
			g.accept(lazy[k], val);
			eval(k, l, r);
			return;
		}
		update(a, b, val, k * 2 + 1, l, (l + r) / 2);
		update(a, b, val, k * 2 + 2, (l + r) / 2, r);
		nodes[k] = f.apply(nodes[k * 2 + 1], nodes[k * 2 + 2]);
	}

	T get(int i) { return find(i, i + 1); } // O(logN)
	T find(int a, int b) { return find(a, b, 0, 0, n); } // O(logN)
	T find(int a, int b, int k, int l, int r) { // O(logN)
		if(b <= l || r <= a) return e.get();
		eval(k, l, r);
		if(a <= l && r <= b) return nodes[k];
		return f.apply(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	T acc;
	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(Predicate<T> check) { return findLeftmost(0, check); }
	int findLeftmost(int a, Predicate<T> check) { return findLeftmost(a, n, check); }
	int findLeftmost(int a, int b, Predicate<T> check) { acc = e.get(); return findLeftmost(a, b, check, 0, 0, n); }
	int findLeftmost(int a, int b, Predicate<T> check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		T tmp = f.apply(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findLeftmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
		return vr >= 0 ? vr : findLeftmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(Predicate<T> check) { return findRightmost(n, check); }
	int findRightmost(int b, Predicate<T> check) { return findRightmost(0, b, check); }
	int findRightmost(int a, int b, Predicate<T> check) { acc = e.get(); return findRightmost(a, b, check, 0, 0, n); }
	int findRightmost(int a, int b, Predicate<T> check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		T tmp = f.apply(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findRightmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
		return vr >= 0 ? vr : findRightmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
	}
}

	}
}

