public void solve() {
	int num = ni();
	int query = ni();
	long a[] = nl(num);
	LazySegTree st = new LazySegTree(a,
			0, (ele1, ele2) -> mod(ele1 + ele2),
			MOD, (ele1, ele2) -> mod((ele1 / MOD) * (ele2 / MOD)) * MOD + mod(mod(ele1) * (ele2 / MOD) + mod(ele2)),
			(ele1, ele2, ele3) -> mod(ele1 * (ele2 / MOD) + mod(ele2) * ele3));
	for(int q = 0; q < query; q ++) {
		switch(ni()) {
		case 0: st.update(ni(), ni(), nl() * MOD + nl()); break;
		case 1: prtln(st.find(ni(), ni())); break;
		}
		for(int i = 0; i < num; i ++) st.get(i);
	}
}
@FunctionalInterface
interface LazyOperator { long applyAsLong(long s, long t, int u); }

class LazySegTree {
	long e;
	LongBinaryOperator f;
	long e2;
	LongBinaryOperator g;
	LazyOperator h;

	int n;
	long nodes[];
	long lazy[];

	LazySegTree(long[] a, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LazyOperator h) { init(a, e, f, e2, g, h); } // O(N)
	LazySegTree(int len, long x, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LazyOperator h) { // O(N)
		long a[] = new long[len];
		fill(a, x);
		init(a, e, f, e2, g, h);
	}
	LazySegTree(int len, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LazyOperator h) { init(len, e, f, e2, g, h); } // O(N)

	void init(long[] a, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LazyOperator h) { // O(N)
		init(a.length, e, f, e2, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n - 1] = a[i];
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.applyAsLong(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}
	void init(int len, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LazyOperator h) { // O(N)
		this.e = e;
		this.f = f;
		this.e2 = e2;
		this.g = g;
		this.h = h;
		n = 1;
		while(n < len) n *= 2;
		nodes = new long[n * 2 - 1];
		fill(nodes, e);
		lazy = new long[n * 2 - 1];
		fill(lazy, e2);
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.applyAsLong(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}

	void eval(int k, int l, int r) { // O(1)
		if(lazy[k] != e2) {
			nodes[k] = h.applyAsLong(nodes[k], lazy[k], r - l);
			if(r - l > 1) {
				lazy[k * 2 + 1] = g.applyAsLong(lazy[k * 2 + 1], lazy[k]);
				lazy[k * 2 + 2] = g.applyAsLong(lazy[k * 2 + 2], lazy[k]);
			}
			lazy[k] = e2;
		}
	}

	void update(int a, int b, long val) { update(a, b, val, 0, 0, n); } // O(logN)
	void update(int a, int b, long val, int k, int l, int r) { // O(logN)
		eval(k, l, r);
		if(b <= l || r <= a) return;
		if(a <= l && r <= b) {
			lazy[k] = g.applyAsLong(lazy[k], val);
			eval(k, l, r);
			return;
		}
		update(a, b, val, k * 2 + 1, l, (l + r) / 2);
		update(a, b, val, k * 2 + 2, (l + r) / 2, r);
		nodes[k] = f.applyAsLong(nodes[k * 2 + 1], nodes[k * 2 + 2]);
	}

	long get(int i) { return find(i, i + 1); } // O(logN)
	long find(int a, int b) { return find(a, b, 0, 0, n); } // O(logN)
	long find(int a, int b, int k, int l, int r) { // O(logN)
		eval(k, l, r);
		if(b <= l || r <= a) return e;
		if(a <= l && r <= b) return nodes[k];
		return f.applyAsLong(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	long acc;
	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(LongPredicate check) { return findLeftmost(0, check); }
	int findLeftmost(int a, LongPredicate check) { return findLeftmost(a, n, check); }
	int findLeftmost(int a, int b, LongPredicate check) { acc = e; return findLeftmost(a, b, check, 0, 0, n); }
	int findLeftmost(int a, int b, LongPredicate check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		long tmp = f.applyAsLong(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findLeftmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
		return vr >= 0 ? vr : findLeftmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(LongPredicate check) { return findRightmost(n, check); }
	int findRightmost(int b, LongPredicate check) { return findRightmost(0, b, check); }
	int findRightmost(int a, int b, LongPredicate check) { acc = e; return findRightmost(a, b, check, 0, 0, n); }
	int findRightmost(int a, int b, LongPredicate check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		long tmp = f.applyAsLong(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findRightmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
		return vr >= 0 ? vr : findRightmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
	}
}


	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;
import java.util.function.BinaryOperator;
import java.util.function.Function;


public class Main {
	static final long MOD1=1000000007;
	static final long MOD2=998244353;
	public static void main(String[] args) {
		PrintWriter out = new PrintWriter(System.out);
		InputReader sc=new InputReader(System.in);
		int N=sc.nextInt();
		int Q=sc.nextInt();
		S[] dat = new S[N];
		for (int i = 0; i < dat.length; i++) {
			dat[i]=new S(sc.nextLong(), 1L);
		}
		LazySegTree<S, F> lazySegTree=new LazySegTree<S, F>(dat, S::op, S.E,S::map,F::composite,F.I);
		for (int i = 0; i< Q; i++) {
			int c=sc.nextInt();
			int s=sc.nextInt();
			int t=sc.nextInt();
			if (c==0) {
				long a=sc.nextLong();
				long b=sc.nextLong();
				lazySegTree.apply(s, t, new F(a, b));

			}else {
				out.println(lazySegTree.prod(s, t).sum);
			}
		}
		out.flush();
	}
	static class F {
        static final F I = new F(1,0);
        long a;
        long b;
        public F (long a, long b) {
        	super();
            this.a = a;
            this.b = b;
        }
        public static F composite(F f, F g) {
            return new F((f.a*g.a)%MOD2,((f.a*g.b)%MOD2+f.b)%MOD2);
        }
    }
	static class S {
        static final S E = new S(0,0);
        long sum;
        long size;
        public S (long sum,long size) {
        	super();
            this.sum = sum;
            this.size=size;
        }
        public static S op(S s1, S s2) {
            return new S((s1.sum+s2.sum)%MOD2,(s1.size+s2.size)%MOD2);
        }
        static S map(F f,  S s) {
    		return new S(((s.sum*f.a)%MOD2 + (f.b * s.size)%MOD2)%MOD2, s.size);
    	}
    }
	static class LazySegTree<S, F> {
	    final int MAX;

	    final int N;
	    final int Log;
	    final java.util.function.BinaryOperator<S> Op;
	    final S E;
	    final java.util.function.BiFunction<F, S, S> Mapping;
	    final java.util.function.BinaryOperator<F> Composition;
	    final F Id;

	    final S[] Dat;
	    final F[] Laz;

	    @SuppressWarnings("unchecked")
	    public LazySegTree(int n, java.util.function.BinaryOperator<S> op, S e, java.util.function.BiFunction<F, S, S> mapping, java.util.function.BinaryOperator<F> composition, F id) {
	        this.MAX = n;
	        int k = 1;
	        while (k < n) k <<= 1;
	        this.N = k;
	        this.Log = Integer.numberOfTrailingZeros(N);
	        this.Op = op;
	        this.E = e;
	        this.Mapping = mapping;
	        this.Composition = composition;
	        this.Id = id;
	        this.Dat = (S[]) new Object[N << 1];
	        this.Laz = (F[]) new Object[N];
	        java.util.Arrays.fill(Dat, E);
	        java.util.Arrays.fill(Laz, Id);
	    }

	    public LazySegTree(S[] dat, java.util.function.BinaryOperator<S> op, S e, java.util.function.BiFunction<F, S, S> mapping, java.util.function.BinaryOperator<F> composition, F id) {
	        this(dat.length, op, e, mapping, composition, id);
	        build(dat);
	    }

	    private void build(S[] dat) {
	        int l = dat.length;
	        System.arraycopy(dat, 0, Dat, N, l);
	        for (int i = N - 1; i > 0; i--) {
	            Dat[i] = Op.apply(Dat[i << 1 | 0], Dat[i << 1 | 1]);
	        }
	    }

	    private void push(int k) {
	        if (Laz[k] == Id) return;
	        int lk = k << 1 | 0, rk = k << 1 | 1;
	        Dat[lk] = Mapping.apply(Laz[k], Dat[lk]);
	        Dat[rk] = Mapping.apply(Laz[k], Dat[rk]);
	        if (lk < N) Laz[lk] = Composition.apply(Laz[k], Laz[lk]);
	        if (rk < N) Laz[rk] = Composition.apply(Laz[k], Laz[rk]);
	        Laz[k] = Id;
	    }

	    private void pushTo(int k) {
	        for (int i = Log; i > 0; i--) push(k >> i);
	    }

	    private void pushTo(int lk, int rk) {
	        for (int i = Log; i > 0; i--) {
	            if (((lk >> i) << i) != lk) push(lk >> i);
	            if (((rk >> i) << i) != rk) push(rk >> i);
	        }
	    }

	    private void updateFrom(int k) {
	        k >>= 1;
	        while (k > 0) {
	            Dat[k] = Op.apply(Dat[k << 1 | 0], Dat[k << 1 | 1]);
	            k >>= 1;
	        }
	    }

	    private void updateFrom(int lk, int rk) {
	        for (int i = 1; i <= Log; i++) {
	            if (((lk >> i) << i) != lk) {
	                int lki = lk >> i;
	                Dat[lki] = Op.apply(Dat[lki << 1 | 0], Dat[lki << 1 | 1]);
	            }
	            if (((rk >> i) << i) != rk) {
	                int rki = (rk - 1) >> i;
	                Dat[rki] = Op.apply(Dat[rki << 1 | 0], Dat[rki << 1 | 1]);
	            }
	        }
	    }

	    public void set(int p, S x) {
	        exclusiveRangeCheck(p);
	        p += N;
	        pushTo(p);
	        Dat[p] = x;
	        updateFrom(p);
	    }

	    public S get(int p) {
	        exclusiveRangeCheck(p);
	        p += N;
	        pushTo(p);
	        return Dat[p];
	    }

	    public S prod(int l, int r) {
	        if (l > r) {
	            throw new IllegalArgumentException(
	                String.format("Invalid range: [%d, %d)", l, r)
	            );
	        }
	        inclusiveRangeCheck(l);
	        inclusiveRangeCheck(r);
	        if (l == r) return E;
	        l += N; r += N;
	        pushTo(l, r);
	        S sumLeft = E, sumRight = E;
	        while (l < r) {
	            if ((l & 1) == 1) sumLeft = Op.apply(sumLeft, Dat[l++]);
	            if ((r & 1) == 1) sumRight = Op.apply(Dat[--r], sumRight);
	            l >>= 1; r >>= 1;
	        }
	        return Op.apply(sumLeft, sumRight);
	    }

	    public S allProd() {
	        return Dat[1];
	    }

	    public void apply(int p, F f) {
	        exclusiveRangeCheck(p);
	        p += N;
	        pushTo(p);
	        Dat[p] = Mapping.apply(f, Dat[p]);
	        updateFrom(p);
	    }

	    public void apply(int l, int r, F f) {
	        if (l > r) {
	            throw new IllegalArgumentException(
	                String.format("Invalid range: [%d, %d)", l, r)
	            );
	        }
	        inclusiveRangeCheck(l);
	        inclusiveRangeCheck(r);
	        if (l == r) return;
	        l += N; r += N;
	        pushTo(l, r);
	        for (int l2 = l, r2 = r; l2 < r2;) {
	            if ((l2 & 1) == 1) {
	                Dat[l2] = Mapping.apply(f, Dat[l2]);
	                if (l2 < N) Laz[l2] = Composition.apply(f, Laz[l2]);
	                l2++;
	            }
	            if ((r2 & 1) == 1) {
	                r2--;
	                Dat[r2] = Mapping.apply(f, Dat[r2]);
	                if (r2 < N) Laz[r2] = Composition.apply(f, Laz[r2]);
	            }
	            l2 >>= 1; r2 >>= 1;
	        }
	        updateFrom(l, r);
	    }

	    public int maxRight(int l, java.util.function.Predicate<S> g) {
	        inclusiveRangeCheck(l);
	        if (!g.test(E)) {
	            throw new IllegalArgumentException("Identity element must satisfy the condition.");
	        }
	        if (l == MAX) return MAX;
	        l += N;
	        pushTo(l);
	        S sum = E;
	        do {
	            l >>= Integer.numberOfTrailingZeros(l);
	            if (!g.test(Op.apply(sum, Dat[l]))) {
	                while (l < N) {
	                    push(l);
	                    l = l << 1;
	                    if (g.test(Op.apply(sum, Dat[l]))) {
	                        sum = Op.apply(sum, Dat[l]);
	                        l++;
	                    }
	                }
	                return l - N;
	            }
	            sum = Op.apply(sum, Dat[l]);
	            l++;
	        } while ((l & -l) != l);
	        return MAX;
	    }

	    public int minLeft(int r, java.util.function.Predicate<S> g) {
	        inclusiveRangeCheck(r);
	        if (!g.test(E)) {
	            throw new IllegalArgumentException("Identity element must satisfy the condition.");
	        }
	        if (r == 0) return 0;
	        r += N;
	        pushTo(r - 1);
	        S sum = E;
	        do {
	            r--;
	            while (r > 1 && (r & 1) == 1) r >>= 1;
	            if (!g.test(Op.apply(Dat[r], sum))) {
	                while (r < N) {
	                    push(r);
	                    r = r << 1 | 1;
	                    if (g.test(Op.apply(Dat[r], sum))) {
	                        sum = Op.apply(Dat[r], sum);
	                        r--;
	                    }
	                }
	                return r + 1 - N;
	            }
	            sum = Op.apply(Dat[r], sum);
	        } while ((r & -r) != r);
	        return 0;
	    }

	    private void exclusiveRangeCheck(int p) {
	        if (p < 0 || p >= MAX) {
	            throw new IndexOutOfBoundsException(
	                String.format("Index %d is not in [%d, %d).", p, 0, MAX)
	            );
	        }
	    }

	    private void inclusiveRangeCheck(int p) {
	        if (p < 0 || p > MAX) {
	            throw new IndexOutOfBoundsException(
	                String.format("Index %d is not in [%d, %d].", p, 0, MAX)
	            );
	        }
	    }

	    // **************** DEBUG **************** //

	    private int indent = 6;

	    public void setIndent(int newIndent) {
	        this.indent = newIndent;
	    }

	    @Override
	    public String toString() {
	        return toString(1, 0);
	    }

	    private String toString(int k, int sp) {
	        if (k >= N) return indent(sp) + Dat[k];
	        String s = "";
	        s += toString(k << 1 | 1, sp + indent);
	        s += "\n";
	        s += indent(sp) + Dat[k] + "/" + Laz[k];
	        s += "\n";
	        s += toString(k << 1 | 0, sp + indent);
	        return s;
	    }

	    private static String indent(int n) {
	        StringBuilder sb = new StringBuilder();
	        while (n --> 0) sb.append(' ');
	        return sb.toString();
	    }
	}
