public void solve() {
	int num = ni();
	int query = ni();
	long a[] = nl(num);
	LazySegTree<PairLL> st = new LazySegTree<>(a,
			0, (ele1, ele2) -> mod(ele1 + ele2),
			() -> new PairLL(1, 0), (ele1, ele2) -> { ele1.a = mod(ele1.a * ele2.a); ele1.b = mod(ele1.b * ele2.a + ele2.b); },
			(ele1, ele2, ele3) -> mod(ele1 * ele2.a + ele2.b * ele3));
	for(int q = 0; q < query; q ++) {
		switch(ni()) {
		case 0: st.update(ni(), ni(), npll()); break;
		case 1: prtln(st.find(ni(), ni())); break;
		}
	}
}

@FunctionalInterface
interface BinaryConsumer<T> extends BiConsumer<T, T> {  }
@FunctionalInterface
// interface LazyFunction<T> { long apply(long t, T u); }
interface LazyFunction<T> { long apply(long t, T u, int v); }
class LazySegTree<T> {
	long e;
	LongBinaryOperator f;
	Supplier<T> e2Supplier;
	T e2;
	BinaryConsumer<T> g;
	LazyFunction<T> h;

	int n;
	int height;
	long nodes[];
	T lazy[];
	int rangeL[];
	int rangeR[];

	LazySegTree(long[] a, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { init(a, e, f, e2Supplier, g, h); } // O(N)
	LazySegTree(int len, long x, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { // O(N)
		long a[] = new long[len];
		fill(a, x);
		init(a, e, f, e2Supplier, g, h);
	}
	LazySegTree(int len, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { init(len, e, f, e2Supplier, g, h); } // O(N)

	void init(long[] a, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { // O(N)
		init(a.length, e, f, e2Supplier, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n] = a[i];
		for(int i = n - 1; i > 0; i --) nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
	}
	void init(int len, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { // O(N)
		this.e = e;
		this.f = f;
		this.e2Supplier = e2Supplier;
		this.e2 = e2Supplier.get();
		this.g = g;
		this.h = h;
		n = 1;
		height = 0;
		while(n < len) { n <<= 1; height ++; }
		nodes = new long[n << 1];
		fill(nodes, e);
		@SuppressWarnings("unchecked")
		T tmp2[] = (T[]) new Object[n << 1];
		lazy = tmp2;
		for(int i = 0; i < lazy.length; i ++) lazy[i] = e2Supplier.get();
		rangeL = new int[n << 1];
		rangeR = new int[n << 1];
		for(int i = 0; i < n; i ++) { rangeL[i + n] = i; rangeR[i + n] = i + 1; }
		for(int i = n - 1; i > 0; i --) {
			nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
			rangeL[i] = rangeL[i << 1]; rangeR[i] = rangeR[(i << 1) + 1];
		}
	}

	void eval(int k) { // O(1)
		if(!lazy[k].equals(e2)) {
			// nodes[k] = h.apply(nodes[k], lazy[k]);
			nodes[k] = h.apply(nodes[k], lazy[k], rangeR[k] - rangeL[k]);
			if(k < n) {
				g.accept(lazy[k << 1], lazy[k]);
				g.accept(lazy[(k << 1) + 1], lazy[k]);
			}
			lazy[k] = e2Supplier.get();
		}
	}

	void update(int l, int r, T val) { // O(logN)
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		int l0 = l;
		int r0 = r;
		r ++;
		while(l < r) {
			if((l & 1) != 0) { g.accept(lazy[l], val); eval(l); l ++; }
			if((r & 1) != 0) { r --; g.accept(lazy[r], val); eval(r); }
			l >>= 1; r >>= 1;
		}
		while(l0 > 1) {
			l0 >>= 1;
			eval(l0 << 1); eval((l0 << 1) + 1);
			nodes[l0] = f.applyAsLong(nodes[l0 << 1], nodes[(l0 << 1) + 1]);
		}
		while(r0 > 1) {
			r0 >>= 1;
			eval(r0 << 1); eval((r0 << 1) + 1);
			nodes[r0] = f.applyAsLong(nodes[r0 << 1], nodes[(r0 << 1) + 1]);
		}
	}

	long get(int i) { return find(i, i + 1); } // O(logN)
	long find(int l, int r) {
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		r ++;
		long xL = e;
		long xR = e;
		while(l < r) {
			if((l & 1) != 0) { eval(l); xL = f.applyAsLong(xL, nodes[l]); l ++; }
			if((r & 1) != 0) { r --; eval(r); xR = f.applyAsLong(nodes[r], xR); }
			l >>= 1; r >>= 1;
		}
		return f.applyAsLong(xL, xR);
	}

	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(LongPredicate check) { return findLeftmost(0, check); }
	int findLeftmost(int l, LongPredicate check) { return findLeftmost(l, n, check); }
	int findLeftmost(int l, int r, LongPredicate check) {
		long crt = e;
		int idx;
		for(idx = l + n; idx < n << 1 && l < r; ){
			eval(idx);
			long tmp = f.applyAsLong(crt, nodes[idx]);
			if(rangeR[idx] <= r && !check.test(tmp)) {
				crt = tmp;
				l = rangeR[idx ++];
				if((idx & 1) == 0) idx >>= 1;
			}else idx <<= 1;
		}
		return l >= r ? -1 : l;
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(LongPredicate check) { return findRightmost(n, check); }
	int findRightmost(int r, LongPredicate check) { return findRightmost(0, r, check); }
	int findRightmost(int l, int r, LongPredicate check) {
		long crt = e;
		int idx;
		for(idx = r + n - 1; idx < n << 1 && r > l; ){
			eval(idx);
			long tmp = f.applyAsLong(nodes[idx], crt);
			if(rangeL[idx] >= l && !check.test(tmp)) {
				crt = tmp;
				r = rangeL[idx --];
				if((idx & 1) != 0) idx >>= 1;
			}else idx = (idx << 1) + 1;
		}
		return r <= l ? -1 : r;
	}
}

	}
}

public class Main {
    static ModIntFactory fac = new ModIntFactory(998244353);
    public static void main(String[] args) throws Exception {
        var sc = new FastScanner();
        var pw = new FastPrintStream();
        solve(sc, pw);
        sc.close();
        pw.flush();
        pw.close();
    }

    public static void solve(FastScanner sc, FastPrintStream pw) {
        int n = sc.nextInt();
        int q = sc.nextInt();
        var a = new long[n];
        java.util.Arrays.setAll(a, i -> sc.nextLong());
        var t = new RangeAffineRangeSum(a, fac);
        while (q --> 0) {
            if (sc.nextInt() == 0) {
                int l = sc.nextInt();
                int r = sc.nextInt();
                int b = sc.nextInt();
                int c = sc.nextInt();
                t.affine(l, r, b, c);
            } else {
                int l = sc.nextInt();
                int r = sc.nextInt();
                pw.println(t.sum(l, r).value());
            }
        }
    }
}

class RangeAffineRangeSum {

    private final ModIntFactory.ModInt[] dat, lzA, lzB;
    private final int n;
    private final int log;
    private final ModIntFactory fac;
    private final ModIntFactory.ModInt ONE, ZERO;

    public RangeAffineRangeSum(int n, ModIntFactory fac) {
        int k = 1; while (k < n) k <<= 1;
        this.dat = new ModIntFactory.ModInt[k << 1];
        this.lzA = new ModIntFactory.ModInt[k];
        this.lzB = new ModIntFactory.ModInt[k];
        this.fac = fac;
        this.ONE = fac.create(1);
        this.ZERO = fac.create(0);
        this.n = k;
        this.log = Integer.numberOfTrailingZeros(k);
        java.util.Arrays.setAll(dat, i -> fac.create(0));
        java.util.Arrays.setAll(lzA, i -> fac.create(1));
        java.util.Arrays.setAll(lzB, i -> fac.create(0));
    }

    public RangeAffineRangeSum(long[] dat, ModIntFactory fac) {
        this(dat.length, fac);
        build(dat);
    }

    private void build(long[] a) {
        for (int i = 0; i < a.length; i++) {
            dat[i + n] = fac.create(a[i]);
        }
        for (int i = n - 1; i > 0; i--) {
            dat[i] = dat[i << 1 | 0].add(dat[i << 1 | 1]);
        }
    }

    private void push(int k, int h) {
        if (lzA[k].equals(ONE) && lzB[k].equals(ZERO)) return;
        int lk = k << 1 | 0, rk = k << 1 | 1;
        dat[lk] = dat[lk].mul(lzA[k]).add(lzB[k].mul(1 << (h - 1)));
        dat[rk] = dat[rk].mul(lzA[k]).add(lzB[k].mul(1 << (h - 1)));
        if (lk < n) {
            lzA[lk] = lzA[lk].mul(lzA[k]);
            lzB[lk] = lzB[lk].mul(lzA[k]).add(lzB[k]);
        }
        if (rk < n) {
            lzA[rk] = lzA[rk].mul(lzA[k]);
            lzB[rk] = lzB[rk].mul(lzA[k]).add(lzB[k]);
        }
        lzA[k] = fac.create(1);
        lzB[k] = fac.create(0);
    }

    private void pushTo(int k) {
        for (int i = log; i > 0; i--) push(k >> i, i);
    }

    private void pushTo(int lk, int rk) {
        for (int i = log; i > 0; i--) {
            if (((lk >> i) << i) != lk) push(lk >> i, i);
            if (((rk >> i) << i) != rk) push(rk >> i, i);
        }
    }

    private void updateFrom(int k) {
        k >>= 1;
        while (k > 0) {
            dat[k] = dat[k << 1 | 0].add(dat[k << 1 | 1]);
            k >>= 1;
        }
    }

    private void updateFrom(int lk, int rk) {
        for (int i = 1; i <= log; i++) {
            if (((lk >> i) << i) != lk) {
                int lki = lk >> i;
                dat[lki] = dat[lki << 1 | 0].add(dat[lki << 1 | 1]);
            }
            if (((rk >> i) << i) != rk) {
                int rki = (rk - 1) >> i;
                dat[rki] = dat[rki << 1 | 0].add(dat[rki << 1 | 1]);
            }
        }
    }

    public ModIntFactory.ModInt get(int i) {
        pushTo(i + n);
        return dat[i + n];
    }

    public ModIntFactory.ModInt sum(int l, int r) {
        if (l == r) return fac.create(0);
        l += n; r += n;
        pushTo(l, r);
        ModIntFactory.ModInt sum = fac.create(0);
        while (l < r) {
            if ((l & 1) == 1) sum.addAsg(dat[l++]);
            if ((r & 1) == 1) sum.addAsg(dat[--r]);
            l >>= 1; r >>= 1;
        }
        return sum;
    }

    public ModIntFactory.ModInt sum() {
        return fac.create(dat[1].value());
    }

    public void affine(int i, long a, long b) {
        pushTo(i + n);
        dat[i + n] = dat[i + n].mul(a).add(b);
        updateFrom(i + n);
    }

    public void affine(int l, int r, long a, long b) {
        if (l == r) return;
        l += n; r += n;
        pushTo(l, r);
        for (int l2 = l, r2 = r, w = 1; l2 < r2; w <<= 1) {
            if ((l2 & 1) == 1) {
                dat[l2] = dat[l2].mul(a).add(b * w);
                if (l2 < n) {
                    lzA[l2] = lzA[l2].mul(a);
                    lzB[l2] = lzB[l2].mul(a).add(b);
                }
                l2++;
            }
            if ((r2 & 1) == 1) {
                r2--;
                dat[r2] = dat[r2].mul(a).add(b * w);
                if (r2 < n) {
                    lzA[r2] = lzA[r2].mul(a);
                    lzB[r2] = lzB[r2].mul(a).add(b);
                }
            }
            l2 >>= 1; r2 >>= 1;
        }
        updateFrom(l, r);
    }
}

