    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int Q = sc.nextInt();
        ModIntFactory mf = new ModIntFactory(998244353);

        Mods[] a = new Mods[N];
        for(int n=0; n<N; n++) a[n] =  new Mods(mf.create(sc.nextLong()), 1);

        LazySegTree<Mods, ModAffine> seg = 
          new LazySegTree<>(a,
                            Mods::merge,
                            Mods.id,
                            (f,s)->f.apply(s),
                            ModAffine::comp,
                            ModAffine.id(998244353)); 

        for(int q=0; q<Q; q++){
            int t = sc.nextInt();
            if(t==0){
                int l = sc.nextInt();
                int r = sc.nextInt();
                int b = sc.nextInt();
                int c = sc.nextInt();
                seg.apply(l, r, new ModAffine(b,c, 998244353));
            }else{
                int l = sc.nextInt();
                int r = sc.nextInt();
                System.out.println(seg.prod(l,r));
            }
        }
    }
}

