public void solve() {
	int num = ni();
	int query = ni();
	long a[] = nl(num);
	long bit = bitFlag(31) - 1;
	LazySegTree st = new LazySegTree(a,
			0, (ele1, ele2) -> { long ans = ele1 + ele2; return ans >= MOD ? ans - MOD : ans; },
			bitFlag(31), (ele1, ele2) -> {
				long ans1 = (ele1 >> 31) * (ele2 >> 31) % MOD;
				long ans2 = ((ele1 & bit) * (ele2 >> 31) + (ele2 & bit)) % MOD;
				return (ans1 << 31) + ans2; },
			(ele1, ele2, ele3) -> (ele1 * (ele2 >> 31) + (ele2 & bit) * ele3) % MOD);
	for(int q = 0; q < query; q ++) {
		switch(ni()) {
		case 0: st.update(ni(), ni(), (nl() << 31) + nl()); break;
		case 1: prtln(st.find(ni(), ni())); break;
		}
	}
}

@FunctionalInterface
// interface LongLazyOperator { long applyAsLong(long t, long u); }
interface LongLazyOperator { long applyAsLong(long t, long u, int v); }
class LazySegTree {
	long e;
	LongBinaryOperator f;
	long e2;
	LongBinaryOperator g;
	LongLazyOperator h;

	int n;
	int height;
	long nodes[];
	long lazy[];
	int rangeL[];
	int rangeR[];

	LazySegTree(long[] a, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { init(a, e, f, e2, g, h); } // O(N)
	LazySegTree(int len, long x, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { // O(N)
		long a[] = new long[len];
		fill(a, x);
		init(a, e, f, e2, g, h);
	}
	LazySegTree(int len, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { init(len, e, f, e2, g, h); } // O(N)

	void init(long[] a, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { // O(N)
		init(a.length, e, f, e2, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n] = a[i];
		for(int i = n - 1; i > 0; i --) nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
	}
	void init(int len, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { // O(N)
		this.e = e;
		this.f = f;
		this.e2 = e2;
		this.g = g;
		this.h = h;
		n = 1;
		height = 0;
		while(n < len) { n <<= 1; height ++; }
		nodes = new long[n << 1];
		fill(nodes, e);
		lazy = new long[n << 1];
		fill(lazy, e2);
		rangeL = new int[n << 1];
		rangeR = new int[n << 1];
		for(int i = 0; i < n; i ++)  { rangeL[i + n] = i; rangeR[i + n] = i + 1; }
		for(int i = n - 1; i > 0; i --) {
			nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
			rangeL[i] = rangeL[i << 1]; rangeR[i] = rangeR[(i << 1) + 1];
		}
	}

	void eval(int k) { // O(1)
		if(lazy[k] != e2) {
			// nodes[k] = h.applyAsLong(nodes[k], lazy[k]);
			nodes[k] = h.applyAsLong(nodes[k], lazy[k], rangeR[k] - rangeL[k]);
			if(k < n) {
				lazy[k << 1] = g.applyAsLong(lazy[k << 1], lazy[k]);
				lazy[(k << 1) + 1] = g.applyAsLong(lazy[(k << 1) + 1], lazy[k]);
			}
			lazy[k] = e2;
		}
	}

	void update(int l, int r, long val) { // O(logN)
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		int l0 = l;
		int r0 = r;
		r ++;
		while(l < r) {
			if((l & 1) != 0) { lazy[l] = g.applyAsLong(lazy[l], val); eval(l); l ++; }
			if((r & 1) != 0) { r --; lazy[r] = g.applyAsLong(lazy[r], val); eval(r); }
			l >>= 1; r >>= 1;
		}
		while(l0 > 1) {
			l0 >>= 1;
			eval(l0 << 1); eval((l0 << 1) + 1);
			nodes[l0] = f.applyAsLong(nodes[l0 << 1], nodes[(l0 << 1) + 1]);
		}
		while(r0 > 1) {
			r0 >>= 1;
			eval(r0 << 1); eval((r0 << 1) + 1);
			nodes[r0] = f.applyAsLong(nodes[r0 << 1], nodes[(r0 << 1) + 1]);
		}
	}

	long get(int i) { return find(i, i + 1); } // O(logN)
	long find(int l, int r) {
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		r ++;
		long xL = e;
		long xR = e;
		while(l < r) {
			if((l & 1) != 0) { eval(l); xL = f.applyAsLong(xL, nodes[l]); l ++; }
			if((r & 1) != 0) { r --; eval(r); xR = f.applyAsLong(nodes[r], xR); }
			l >>= 1; r >>= 1;
		}
		return f.applyAsLong(xL, xR);
	}

	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(LongPredicate check) { return findLeftmost(0, check); }
	int findLeftmost(int l, LongPredicate check) { return findLeftmost(l, n, check); }
	int findLeftmost(int l, int r, LongPredicate check) {
		long crt = e;
		int idx;
		for(idx = l + n; idx < n << 1 && l < r; ){
			eval(idx);
			long tmp = f.applyAsLong(crt, nodes[idx]);
			if(rangeR[idx] <= r && !check.test(tmp)) {
				crt = tmp;
				l = rangeR[idx ++];
				if((idx & 1) == 0) idx >>= 1;
			}else idx <<= 1;
		}
		return l >= r ? -1 : l;
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(LongPredicate check) { return findRightmost(n, check); }
	int findRightmost(int r, LongPredicate check) { return findRightmost(0, r, check); }
	int findRightmost(int l, int r, LongPredicate check) {
		long crt = e;
		int idx;
		for(idx = r + n - 1; idx < n << 1 && r > l; ){
			eval(idx);
			long tmp = f.applyAsLong(nodes[idx], crt);
			if(rangeL[idx] >= l && !check.test(tmp)) {
				crt = tmp;
				r = rangeL[idx --];
				if((idx & 1) != 0) idx >>= 1;
			}else idx = (idx << 1) + 1;
		}
		return r <= l ? -1 : r;
	}
}

	}
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.function.BiFunction;
import java.util.function.BinaryOperator;
import java.util.function.Supplier;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int Q = sc.nextInt();
        long[][] A = new long[N][2];
        for (int i = 0; i < N; i++) {
            A[i][0] = sc.nextLong();
            A[i][1] = 1;
        }
        cm.setMod998244353();
        Supplier<long[]> et = () -> new long[]{0, 0}; // value, size
        BinaryOperator<long[]> op = (x, y) -> new long[]{cm.add(x[0],y[0]), cm.add(x[1], y[1])};
        Supplier<long[]> es = () -> new long[]{1, 0}; //b, c
        BiFunction<long[], long[], long[]> mapping = (x, y) -> new long[]{cm.add( cm.mul(x[0], y[0]), cm.mul(x[1], y[1]) ), x[1]};
        BinaryOperator<long[]> composition = (old, tgt) -> new long[]{
                cm.mul(old[0], tgt[0]),
                cm.add( cm.mul(old[0], tgt[1]), old[1])
        };
        LazySegTreeK<long[], long[]> seg = new LazySegTreeK<>(A, et, op, es, mapping, composition);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Q; i++) {
            int t = sc.nextInt();
            int l = sc.nextInt(), r = sc.nextInt();
            if(t == 0){
                long b = sc.nextLong(), c = sc.nextLong();
                seg.apply(l, r, new long[]{b, c});
            }else{
                sb.append(seg.query(l, r)[0] + "\n");
            }
        }
        System.out.println(sb.toString());
        sc.close();

    }

}

class LazySegTreeK<T, S> {

    /** 要素数 */
    private final int N;
    /** Nより大きい最小の2の累乗数 */
    private final int SIZE;
    /** 2 ^ LOG = SIZE */
    private final int LOG;
    /**
     * データ配列.
     * 要素全体を含むノードのindex：1.
     * k番目(0-indexed)の要素のindex：k + size
     * ノードkの親要素のindex：k/2.
     * ノードkの子要素のうち左側のindex：k*2.
     * ノードkの子要素のうち右側のindex：k*2+1.
     */
    private final T[] DATA;
    /** 遅延評価配列 */
    private final S[] LAZY;
    /** データの単位元供給関数 */
    private final Supplier<T> ET;
    /** クエリ結果を求める関数 */
    private final BinaryOperator<T> OP;
    /** 遅延評価の単位元供給関数 */
    private final Supplier<S> ES;
    /** 遅延分をデータに適用する関数 */
    private final BiFunction<T, S, T> MAPPING;
    /** 遅延分を合成する関数 */
    private final BinaryOperator<S> COMPOSITION;

    /**
     * 全てのノードを単位元で初期化するコンストラクタ.<br>
     * 計算量：O(N)
     * @param n
     * @param et
     * @param op
     * @param es
     * @param mapping
     * @param composition
     */
    @SuppressWarnings("unchecked")
    public LazySegTreeK(int n, Supplier<T> et, BinaryOperator<T> op, Supplier<S> es,
            BiFunction<T, S, T> mapping, BinaryOperator<S> composition){
        int tmpSize = 1, tmpLog = 0;
        while(tmpSize < n) {
            tmpLog++;
            tmpSize *= 2;
        }
        this.N = n;
        this.SIZE = tmpSize;
        this.LOG = tmpLog;
        this.DATA = (T[]) new Object[SIZE*2];
        this.LAZY = (S[]) new Object[SIZE*2];
        this.ET = et;
        this.OP = op;
        this.ES = es;
        this.MAPPING = mapping;
        this.COMPOSITION = composition;
        Arrays.fill(DATA, ET.get());
        Arrays.fill(LAZY, ES.get());
    }

    /**
     * 引数で指定された配列で初期化するコンストラクタ.<br>
     * 計算量：O(N)
     * @param a
     * @param et
     * @param op
     * @param es
     * @param mapping
     * @param composition
     */
    @SuppressWarnings("unchecked")
    public LazySegTreeK(T[] a, Supplier<T> et, BinaryOperator<T> op, Supplier<S> es,
            BiFunction<T, S, T> mapping, BinaryOperator<S> composition){
        int tmpSize = 1, tmpLog = 0;
        while(tmpSize < a.length) {
            tmpLog++;
            tmpSize *= 2;
        }
        this.N = a.length;
        this.SIZE = tmpSize;
        this.LOG = tmpLog;
        this.DATA = (T[]) new Object[SIZE*2];
        this.LAZY = (S[]) new Object[SIZE*2];
        this.ET = et;
        this.OP = op;
        this.ES = es;
        this.MAPPING = mapping;
        this.COMPOSITION = composition;
        for (int i = 0; i < N; i++) DATA[i + SIZE] = a[i];
        for(int i = N; i < SIZE; i++) DATA[i+SIZE] = ET.get();
        for (int i = SIZE-1; i > 0; i--) update(i);
        Arrays.fill(LAZY, ES.get());
    }

    /**
     * 指定したノードに遅延分を反映し、子ノードの遅延評価待ちを設定する。<br>
     * 計算量：O(1)
     * @param k 自ノードのindex
     */
    public void eval(int k){
        DATA[k] = MAPPING.apply(DATA[k], LAZY[k]);
        if(k < SIZE-1) {
            LAZY[2*k] = COMPOSITION.apply(LAZY[k], LAZY[2*k]);
            LAZY[2*k+1] = COMPOSITION.apply(LAZY[k], LAZY[2*k+1]);
        }
        LAZY[k] = ES.get();
    }

    /**
     * k番目の要素を取得する.<br>
     * 計算量：O(logN)
     * @param k
     * @return k番目の要素の値
     */
    public T get(int k) {
        k += SIZE;
        for(int i = LOG; i >= 0; i--) eval(k >> i);
        return DATA[k];
    }

    /**
     * k番目（0-indexed）の要素をaに更新する.<br>
     * 計算量：O(logN)
     * @param k 変更対象要素のindex（0-indexed）
     * @param v 変更後の値
     */
    public void set(int k, T v){
        k += SIZE;
        for(int i = LOG; i >= 0; i--) eval(k >> i);
        DATA[k] = v;
        for(int i = 1; i <= LOG; i++) update(k >> i);
    }

    /**
     * ノードkに演算を適用する.<br>
     * 計算量：O(1)
     * @param k
     */
    private void update(int k) {
        DATA[k] = OP.apply(DATA[k*2], DATA[k*2+1]);
    }

    /**
     * k番目（0-indexed）の要素に s を適用する.<br>
     * 計算量：O(logN)
     * @param k 変更対象要素のindex（0-indexed）
     * @param s 更新処理
     */
    public void apply(int k, S s) {
        k += SIZE;
        for(int i = LOG; i >= 0; i--) eval(k >> i);
        DATA[k] = MAPPING.apply(DATA[k], s);
        for(int i = 1; i <= LOG; i++) update(k >> i);
    }


    /**
     * 区間[a, b)に s を適用する.<br>
     * 計算量：O(logN)
     * @param l 最終的に適用する区間の下限（含む）
     * @param r 最終的に適用する区間上限（含まない）
     * @param s 更新処理
     */
    public void apply(int l, int r, S s) {
        apply(l, r, 1, 0, SIZE, s);
    }

    /**
     * 区間[a, b)に s を適用する.<br>
     * 計算量：O(logN)
     * @param l 最終的に適用する区間の下限（含む）
     * @param r 最終的に適用する区間上限（含まない）
     * @param k 今見ているノードのindex
     * @param a 今見ているノードの下限（含む）
     * @param b 今見ているノードの上限（含まない）
     * @param s 更新処理
     */
    private void apply(int l, int r, int k, int a, int b, S s){
        eval(k);

        // 区間外
        if(r <= a || b <= l) return;

        // 完全に含む
        if(l <= a && b <= r){
            LAZY[k] = COMPOSITION.apply(LAZY[k], s);
            eval(k);
            return;
        }

        // それ以外
        apply(l, r, 2*k, a, (a+b)/2, s);
        apply(l, r, 2*k+1, (a+b)/2, b, s);
        update(k);
    }

    /**
     * 区間[l, r)の結果を求める.<br>
     * 計算量：O(logN)
     * @param l 求める区間の下限（含む）
     * @param r 求める区間の上限（含まない）
     * @return 区間[l, r)の結果
     */
    public T query(int l, int r){
        return query(l, r, 1, 0, SIZE);
    }

    /**
     * 区間[l, r)の結果を求める.<br>
     * 計算量：O(logN)
     * @param l 求める区間の下限（含む）
     * @param r 求める区間の上限（含まない）
     * @param k 確認するノードのindex
     * @param a 確認するノードの下限（含む）
     * @param b 確認するノードの上限（含まない）
     * @return 区間[l, r)の結果
     */
    private T query(int l, int r, int k, int a, int b){
        // 区間外
        if(r <= a || b <= l) return ET.get();
        eval(k);
        // 完全に含む
        if(l <= a && b <= r) return DATA[k];
        // それ以外
        T vl = query(l, r, 2*k, a, (a+b)/2);
        T vr = query(l, r, 2*k+1, (a+b)/2, b);
        return OP.apply(vl, vr);
    }
}


class cm {
    private static int MOD = 1000000007;

    static public void setMod(int mod) {
        MOD = mod;
    }
    static public void setMod1000000007() {
        MOD = 1000000007;
    }
    static public void setMod998244353() {
        MOD = 998244353;
    }

    // TODO 負の数に対応したメソッド

    static public long add(long x, long y) {
        return (x + y) % MOD;
    }

    static public long sub(long x, long y) {
        return (x - y + MOD) % MOD;
    }

    static public long mul(long x, long y) {
        return x * y % MOD;
    }

    static public long div(long x, long y) {
        return mul(x, inv(y));
    }

    static public long inv(long x) {
        return pow(x, MOD - 2);
    }

    static public int pow(long base, int exp) {
        long ret = 1;
        while(exp > 0){
            if((exp & 1) == 1){
                ret = ret * base %MOD;
            }
            base = base * base %MOD;
            exp >>= 1;
        }
        return (int)ret;
    }

}

public class Main {
    static ModIntFactory fac = new ModIntFactory(998244353);
    public static void main(String[] args) throws Exception {
        var sc = new FastScanner();
        var pw = new FastPrintStream();
        solve(sc, pw);
        sc.close();
        pw.flush();
        pw.close();
    }

    public static void solve(FastScanner sc, FastPrintStream pw) {
        int n = sc.nextInt();
        int q = sc.nextInt();
        var a = new long[n];
        java.util.Arrays.setAll(a, i -> sc.nextLong());
        var t = new RangeAffineRangeSum(a, fac);
        while (q --> 0) {
            if (sc.nextInt() == 0) {
                int l = sc.nextInt();
                int r = sc.nextInt();
                int b = sc.nextInt();
                int c = sc.nextInt();
                t.affine(l, r, b, c);
            } else {
                int l = sc.nextInt();
                int r = sc.nextInt();
                pw.println(t.sum(l, r).value());
            }
        }
    }
}

class RangeAffineRangeSum {

    private final ModIntFactory.ModInt[] dat, lzA, lzB;
    private final int n;
    private final int log;
    private final ModIntFactory fac;
    private final ModIntFactory.ModInt ONE, ZERO;

    public RangeAffineRangeSum(int n, ModIntFactory fac) {
        int k = 1; while (k < n) k <<= 1;
        this.dat = new ModIntFactory.ModInt[k << 1];
        this.lzA = new ModIntFactory.ModInt[k];
        this.lzB = new ModIntFactory.ModInt[k];
        this.fac = fac;
        this.ONE = fac.create(1);
        this.ZERO = fac.create(0);
        this.n = k;
        this.log = Integer.numberOfTrailingZeros(k);
        java.util.Arrays.fill(dat, ZERO);
        java.util.Arrays.fill(lzA, ONE);
        java.util.Arrays.fill(lzB, ZERO);
    }

    public RangeAffineRangeSum(long[] dat, ModIntFactory fac) {
        this(dat.length, fac);
        build(dat);
    }

    private void build(long[] a) {
        for (int i = 0; i < a.length; i++) {
            dat[i + n] = fac.create(a[i]);
        }
        for (int i = n - 1; i > 0; i--) {
            dat[i] = dat[i << 1 | 0].add(dat[i << 1 | 1]);
        }
    }

    private void push(int k, int h) {
        if (lzA[k].equals(ONE) && lzB[k].equals(ZERO)) return;
        int lk = k << 1 | 0, rk = k << 1 | 1;
        dat[lk] = dat[lk].mul(lzA[k]).add(lzB[k].mul(1 << h - 1));
        dat[rk] = dat[rk].mul(lzA[k]).add(lzB[k].mul(1 << h - 1));
        if (lk < n) {
            lzA[lk] = lzA[lk].mul(lzA[k]);
            lzB[lk] = lzA[lk].mul(lzA[k]).add(lzB[k]);
        }
        if (rk < n) {
            lzA[rk] = lzA[rk].mul(lzA[k]);
            lzB[rk] = lzA[rk].mul(lzA[k]).add(lzB[k]);
        }
        lzA[k] = ONE;
        lzB[k] = ZERO;
    }

    private void pushTo(int k) {
        for (int i = log; i > 0; i--) push(k >> i, i);
    }

    private void pushTo(int lk, int rk) {
        for (int i = log; i > 0; i--) {
            if (((lk >> i) << i) != lk) push(lk >> i, i);
            if (((rk >> i) << i) != rk) push(rk >> i, i);
        }
    }

    private void updateFrom(int k) {
        k >>= 1;
        while (k > 0) {
            dat[k] = dat[k << 1 | 0].add(dat[k << 1 | 1]);
            k >>= 1;
        }
    }

    private void updateFrom(int lk, int rk) {
        for (int i = 1; i <= log; i++) {
            if (((lk >> i) << i) != lk) {
                int lki = lk >> i;
                dat[lki] = dat[lki << 1 | 0].add(dat[lki << 1 | 1]);
            }
            if (((rk >> i) << i) != rk) {
                int rki = (rk - 1) >> i;
                dat[rki] = dat[rki << 1 | 0].add(dat[rki << 1 | 1]);
            }
        }
    }

    public ModIntFactory.ModInt get(int i) {
        pushTo(i + n);
        return dat[i + n];
    }

    public ModIntFactory.ModInt sum(int l, int r) {
        if (l == r) return fac.create(0);
        l += n; r += n;
        pushTo(l, r);
        ModIntFactory.ModInt sum = fac.create(0);
        while (l < r) {
            if ((l & 1) == 1) sum = sum.add(dat[l++]);
            if ((r & 1) == 1) sum = sum.add(dat[--r]);
            l >>= 1; r >>= 1;
        }
        return sum;
    }

    public ModIntFactory.ModInt sum() {
        return fac.create(dat[1].value());
    }

    public void affine(int i, long a, long b) {
        pushTo(i + n);
        dat[i + n] = dat[i + n].mul(a).add(b);
        updateFrom(i + n);
    }

    public void affine(int l, int r, long a, long b) {
        if (l == r) return;
        l += n; r += n;
        pushTo(l, r);
        for (int l2 = l, r2 = r, w = 1; l2 < r2; w <<= 1) {
            if ((l2 & 1) == 1) {
                dat[l2] = dat[l2].mul(a).add(b * w);
                if (l2 < n) {
                    lzA[l2] = lzA[l2].mul(a);
                    lzB[l2] = lzB[l2].mul(a).add(b);
                }
                l2++;
            }
            if ((r2 & 1) == 1) {
                r2--;
                dat[r2] = dat[r2].mul(a).add(b * w);
                if (r2 < n) {
                    lzA[r2] = lzA[r2].mul(a);
                    lzB[r2] = lzB[r2].mul(a).add(b);
                }
            }
            l2 >>= 1; r2 >>= 1;
        }
        updateFrom(l, r);
    }
}

