@FunctionalInterface
interface BinaryConsumer<T> extends BiConsumer<T, T> {  }
@FunctionalInterface
interface TriConsumer<S, T, U> {
	void accept(S s, T t, U u);
	default TriConsumer<S, T, U> andThen(TriConsumer<? super S,? super T,? super U> after) {
		Objects.requireNonNull(after);
		return (S s, T t, U u) -> { accept(s, t, u); after.accept(s, t, u); };
	}
}
@FunctionalInterface
interface TriFunction<S, T, U, R> {
	R apply(S s, T t, U u);
	default <V> TriFunction<S, T, U, V> andThen(Function<? super R, ? extends V> after) {
		Objects.requireNonNull(after);
			return (S s, T t, U u) -> after.apply(apply(s, t, u));
	}
}

@FunctionalInterface
interface LazyFunction<T> {
	long apply(long s, T t, int u);
}

class LazySegTree<T> {
	long e;
	LongBinaryOperator f;
	Supplier<T> e2;
	BinaryConsumer<T> g;
	TriFunction<Long, T, Integer, Long> h;

	int n;
	long nodes[];
	T lazy[];

	LazySegTree(long[] a, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, TriFunction<Long, T, Integer, Long> h) { init(a, e, f, e2, g, h); } // O(N)
	LazySegTree(int len, long x, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, TriFunction<Long, T, Integer, Long> h) { // O(N)
		@SuppressWarnings("unchecked")
		long a[] = new long[len];
		fill(a, x);
		init(a, e, f, e2, g, h);
	}
	LazySegTree(int len, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, TriFunction<Long, T, Integer, Long> h) { init(len, e, f, e2, g, h); } // O(N)

	void init(long[] a, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, TriFunction<Long, T, Integer, Long> h) { // O(N)
		init(a.length, e, f, e2, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n - 1] = a[i];
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.applyAsLong(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}
	void init(int len, long e, LongBinaryOperator f, Supplier<T> e2, BinaryConsumer<T> g, TriFunction<Long, T, Integer, Long> h) { // O(N)
		this.e = e;
		this.f = f;
		this.e2 = e2;
		this.g = g;
		this.h = h;
		n = 1;
		while(n < len) n *= 2;
		nodes = new long[n * 2 - 1];
		fill(nodes, e);
		@SuppressWarnings("unchecked")
		T tmp2[] = (T[]) new Object[n * 2 - 1];
		lazy = tmp2;
		for(int i = 0; i < lazy.length; i ++) lazy[i] = e2.get();
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.applyAsLong(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}

	void eval(int k, int l, int r) { // O(1)
		if(!lazy[k].equals(e2.get())) {
			nodes[k] = h.apply(nodes[k], lazy[k], r - l);
			if(r - l > 1) {
				g.accept(lazy[k * 2 + 1], lazy[k]);
				g.accept(lazy[k * 2 + 2], lazy[k]);
			}
			lazy[k] = e2.get();
		}
	}

	void update(int a, int b, T val) { update(a, b, val, 0, 0, n); } // O(logN)
	void update(int a, int b, T val, int k, int l, int r) { // O(logN)
		eval(k, l, r);
		if(b <= l || r <= a) return;
		if(a <= l && r <= b) {
			g.accept(lazy[k], val);
			eval(k, l, r);
			return;
		}
		update(a, b, val, k * 2 + 1, l, (l + r) / 2);
		update(a, b, val, k * 2 + 2, (l + r) / 2, r);
		nodes[k] = f.applyAsLong(nodes[k * 2 + 1], nodes[k * 2 + 2]);
	}

	long get(int i) { return find(i, i + 1); } // O(logN)
	long find(int a, int b) { return find(a, b, 0, 0, n); } // O(logN)
	long find(int a, int b, int k, int l, int r) { // O(logN)
		if(b <= l || r <= a) return e;
		eval(k, l, r);
		if(a <= l && r <= b) return nodes[k];
		return f.applyAsLong(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	long acc;
	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(LongPredicate check) { return findLeftmost(0, check); }
	int findLeftmost(int a, LongPredicate check) { return findLeftmost(a, n, check); }
	int findLeftmost(int a, int b, LongPredicate check) { acc = e; return findLeftmost(a, b, check, 0, 0, n); }
	int findLeftmost(int a, int b, LongPredicate check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		long tmp = f.applyAsLong(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findLeftmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
		return vr >= 0 ? vr : findLeftmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(LongPredicate check) { return findRightmost(n, check); }
	int findRightmost(int b, LongPredicate check) { return findRightmost(0, b, check); }
	int findRightmost(int a, int b, LongPredicate check) { acc = e; return findRightmost(a, b, check, 0, 0, n); }
	int findRightmost(int a, int b, LongPredicate check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		long tmp = f.applyAsLong(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findRightmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
		return vr >= 0 ? vr : findRightmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
	}
}

	}
}

