    private object Calc()
    {
        int N = cr;
        int Q = cr;
        var seg = new AtCoder.LazySegtree<(int v, int size), (int b, int c), Op>(cr.Repeat(N).Select(cr => (cr.Int, 1)));

        for (int q = 0; q < Q; q++)
        {
            if (cr.Int == 0)
            {
                seg.Apply(cr.Int, cr.Int, (cr.Int, cr.Int));
            }
            else
            {
                cw.WriteLine(seg.Prod(cr.Int, cr.Int).v);
            }
        }

        return null;
    }
