		const int MASK = 1073741823;

		static void Main()
		{
			using var cin = new Scanner();
			var (n, q) = cin.Int2();
			var a = cin.ArrayInt(n).Select(x => (uint)x).ToArray();

			var seg = new LazySegtree<uint, ulong, Monoid>(a);
			for (int i = 0; i < q; i++) {
				int t = cin.Int();
				if (t == 0) {
					var (l, r, b, c) = cin.Int4();
					seg.Apply(l, r, ((ulong)b << 31) + (ulong)c);
