		static void Main()
		{
			using var cin = new Scanner();
			var (n, q) = cin.Int2();
			var a = cin.ArrayInt(n).Select(x => (new ModInt(x), 1)).ToArray();

			var seg = new LazySegtree<(ModInt v, int n), (ModInt a, ModInt b), Monoid>(a);
			for (int i = 0; i < q; i++) {
				int t = cin.Int();
				if (t == 0) {
