public struct MulAndAddOperatorMonoid {
    public long Mul;
    public long Add;
}

/// <summary>
/// query       : a1 + a2 + ... + an
/// range-update: a <- a * Mul + Add
/// </summary>
public class LazySegmentTreeMulAndAddMonoidOperator : ILazySegmentTreeMonoidOperator<ModInt, MulAndAddOperatorMonoid> {
    public ModInt Identity => 0;

    public MulAndAddOperatorMonoid OperatorIdentity => new MulAndAddOperatorMonoid { Mul = 1 };

    public ModInt Merge(ModInt left, ModInt right) {
        return (left + right);
    }

    public ModInt Apply(ModInt monoid, int dataNum, MulAndAddOperatorMonoid operation) {
        // (a1 * mul + add) + (a2 * mul + add) + ... (a_n * mul + add)
        // (a1 + .. a_n) * mul + add * n
        return (1L * monoid * operation.Mul + 1L * operation.Add * dataNum);
    }

    public MulAndAddOperatorMonoid MergeOperator(MulAndAddOperatorMonoid current, MulAndAddOperatorMonoid append) {
        // (x * mul1 + add1) * mul2 + add2
        // x * mul1 * mul2 + add1 * mul2 + add2
        return new MulAndAddOperatorMonoid {
            Mul = current.Mul * append.Mul,
            Add = (current.Add * append.Mul + append.Add)
        };
    }
}
