					key = $"[{l}-{r})";
				this.value = value;
				this.lazy = lazy;
			}
			[DebuggerBrowsable(DebuggerBrowsableState.Never)]
			private readonly string key;
			[DebuggerBrowsable(DebuggerBrowsableState.Never)]
			private readonly TValue value;
			[DebuggerBrowsable(DebuggerBrowsableState.Never)]
