				ll d = x.B*y.A+y.B;
				return new P<int,int>((int)(MOD1<=c?c%MOD1:c),(int)(MOD1<=d?d%MOD1:d));
			};
			LazySegmentTree<P<int,int>,P<int,int>> seg = new LazySegmentTree<P<int,int>, P<int, int>>(n,f,g,h,new P<int, int>(0,0),new P<int, int>(1,0));
