class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n, q;
        sc.Multi(out n, out q);
        var a = sc.LongArr;
        var sg = new LazySegtree<long, (long, long)>(n, (x, y) => (x + y) % M, (x, y, l, r) => (x * y.Item1 + y.Item2 * (r - l)) % M, (x, y) => (x.Item1 * y.Item1 % M, (x.Item2 * y.Item1 + y.Item2) % M), 0, (1, 0), a);
        for (int i = 0; i < q; i++)
        {
            var inp = sc.IntArr;
            if (inp[0] == 0) {
                var (l, r, b, c) = (inp[1], inp[2], inp[3], inp[4]);
                sg.update(l, r, (b, c));
            }
            else {
                var (l, r) = (inp[1], inp[2]);
                Prt(sg.run(l, r));
            }
        }


    }
}

