            private static long GetInv(long a)
            {
                a %= Mod;
                if (a < 0) a += Mod;
                if (a == 0) return 0;
                var (s, t, m0, m1) = ((long)Mod, a, 0L, 1L);
                while (t > 1)
                {
                    var u = s / t;
                    s -= t * u;
                    m0 -= m1 * u;
                    (s, t) = (t, s);
                    (m0, m1) = (m1, m0);
                }

                if (m0 < 0) m0 += Mod / s;
                return m0;
            }
        }

        public class LazySegTree<T, U>
