public interface ILazySegmentTreeDefinition<TMonoid, TOperatorMonoid> {
    TMonoid Merge(TMonoid left, TMonoid right);
    TMonoid Apply(TMonoid monoid, int begin, int @end, TOperatorMonoid operation);
    TOperatorMonoid MergeOperator(TOperatorMonoid current, TOperatorMonoid append);

    TMonoid Identity { get; }
    TOperatorMonoid OperatorIdentity { get; }
}
public static class LazySegmentTreeExtension {
    public static LazySegmentTree<TMonoid, TOperatorMonoid> CreateLazySegmentTree<TMonoid, TOperatorMonoid>
        (this ILazySegmentTreeDefinition<TMonoid, TOperatorMonoid> lazySegmentTreeMonoidOperator)
         where TOperatorMonoid : IEquatable<TOperatorMonoid> {
        return new LazySegmentTree<TMonoid, TOperatorMonoid>(
            lazySegmentTreeMonoidOperator.Merge,
            lazySegmentTreeMonoidOperator.Apply,
            lazySegmentTreeMonoidOperator.MergeOperator,
            lazySegmentTreeMonoidOperator.Identity,
            lazySegmentTreeMonoidOperator.OperatorIdentity
        );
    }

    public static bool Check<TMonoid, TOperatorMonoid>
        (this ILazySegmentTreeDefinition<TMonoid, TOperatorMonoid> lazySegmentTreeMonoidOperator, TMonoid m, TOperatorMonoid o1, TOperatorMonoid o2) {
        var r1 = lazySegmentTreeMonoidOperator.Apply(lazySegmentTreeMonoidOperator.Apply(m, 1, 2, o1), 1, 2, o2);
        var r2 = lazySegmentTreeMonoidOperator.Apply(m, 1, 2, lazySegmentTreeMonoidOperator.MergeOperator(o1, o2));
        return r1.Equals(r2);
    }
}

public sealed class LazySegmentTree<TMonoid, TOperatorMonoid> where TOperatorMonoid : IEquatable<TOperatorMonoid> {
    private int Count;

    private TMonoid[] _node;
    private TOperatorMonoid[] _operators;
    private int[] _height;
    private int[] _begin, _end;
    private readonly TMonoid _identity;
    private readonly TOperatorMonoid _operatorIdentity;
    private readonly Func<TMonoid, TMonoid, TMonoid> _merge;
    private readonly Func<TMonoid, int, int, TOperatorMonoid, TMonoid> _apply;
    private readonly Func<TOperatorMonoid, TOperatorMonoid, TOperatorMonoid> _mergeOperator;

    public LazySegmentTree(
        Func<TMonoid, TMonoid, TMonoid> merge,
        Func<TMonoid, int, int, TOperatorMonoid, TMonoid> apply,
        Func<TOperatorMonoid, TOperatorMonoid, TOperatorMonoid> mergeOperator,
        TMonoid identity,
        TOperatorMonoid operatorIdentity) {
        _merge = merge;
        _apply = apply;
        _mergeOperator = mergeOperator;
        _identity = identity;
        _operatorIdentity = operatorIdentity;
    }

    public void Build(IList<TMonoid> array) {
        Build(array.Count, i => array[i]);
    }

    public void Build(int n, Func<int, TMonoid> create) {
        Count = n;

        _node = new TMonoid[2 * Count];
        _operators = new TOperatorMonoid[2 * Count];
        _begin = new int[2 * Count];
        _end = new int[2 * Count];
        _height = new int[2 * Count];
        for (var i = 0; i < _node.Length; i++) {
            _node[i] = _identity;
            _operators[i] = _operatorIdentity;
        }

        for (var i = 0; i < n; i++) {
            _node[i + Count] = create(i);
            _begin[i + Count] = i;
            _end[i + Count] = i + 1;
        }

        for (var i = 2; i < _height.Length; i++) {
            _height[i] = _height[i >> 1] + 1;
        }

        for (var i = Count - 1; i > 0; i--) {
            _node[i] = _merge(_node[i << 1], _node[i << 1 | 1]);
            _begin[i] = _begin[i << 1];
            _end[i] = _end[i << 1 | 1];
        }
    }

    private void Propagate(int k) {
        if (_operators[k].Equals(_operatorIdentity)) return;
        int childL = k << 1, childR = childL | 1;
        _operators[childL] = _mergeOperator(_operators[childL], _operators[k]);
        _operators[childR] = _mergeOperator(_operators[childR], _operators[k]);
        _node[k] = Apply(k);
        _operators[k] = _operatorIdentity;
    }

    public TMonoid Query(int begin, int end) {
        TMonoid lv = _identity, rv = _identity;
        begin += Count;
        end += Count;
        TopDownOperators(begin, end - 1);
        for (int l = begin, r = end - 1; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { lv = _merge(lv, Apply(l++)); }
            if ((r & 1) == 0) { rv = _merge(Apply(r--), rv); }
        }
        return _merge(lv, rv);
    }

    public void LazyUpdate(int begin, int end, TOperatorMonoid @operator) {
        begin += Count;
        end += Count;
        TopDownOperators(begin, end - 1);
        for (int l = begin, r = end - 1; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { _operators[l] = _mergeOperator(_operators[l], @operator); l++; }
            if ((r & 1) == 0) { _operators[r] = _mergeOperator(_operators[r], @operator); r--; }
        }
        BottomUpMonoids(begin, end - 1);
    }

    private void TopDownOperators(int k) {
        for (var i = _height[k]; i > 0; i--) {
            Propagate(k >> i);
        }
    }

    private void TopDownOperators(int l, int r) {
        var lh = _height[l];
        var rh = _height[r];
        while (lh < rh) Propagate(r >> rh--);
        while (lh > rh) Propagate(l >> lh--);
        var h = lh;
        for (; h > 0; h--) {
            Propagate(l >> h);
            if ((l >> h) != (r >> h)) Propagate(r >> h);
        }
    }

    private TMonoid Apply(int k) {
        if (_operators[k].Equals(_operatorIdentity)) return _node[k];
        return _apply(_node[k], _begin[k], _end[k], _operators[k]);
    }

    private void BottomUpMonoids(int k) {
        while ((k >>= 1) > 0) {
            _node[k] = _merge(Apply(k << 1), Apply(k << 1 | 1));
        }
    }

    private void BottomUpMonoids(int l, int r) {
        l >>= 1;
        r >>= 1;
        while ((l > 0 || r > 0) && l != r) {
            if (l < r) {
                _node[r] = _merge(Apply(r << 1), Apply(r << 1 | 1)); r >>= 1;
            } else {
                _node[l] = _merge(Apply(l << 1), Apply(l << 1 | 1)); l >>= 1;
            }
        }
        BottomUpMonoids(l);
    }

    public TMonoid this[int index] {
        get {
            index += Count;
            TopDownOperators(index);
            return Apply(index);
        }
        set {
            index += Count;
            TopDownOperators(index);
            _node[index] = value;
            _operators[index] = _operatorIdentity;
            BottomUpMonoids(index);
        }
    }

    public void Diagonsis() {
        for (var i = 1; i < Count; i++) {
            Propagate(i);
            var ex = _merge(Apply(i << 1), Apply(i << 1 | 1));
            var ex2 = Apply(i);
            if (!ex2.Equals(ex)) throw new Exception();
        }
    }

}



