	public class LazySegmentTree<TData, TUpdate> : IEnumerable<TData>
	{
		private readonly int n_;
		private readonly TData[] data_;
		private readonly TUpdate[] lazy_;
		private readonly Func<TData, TData, TData> operate_;
		private readonly Func<TData, TUpdate, int, TData> update_;
		private readonly Func<TUpdate, TUpdate, TUpdate> compose_;
		private readonly TData unitData_;
		private readonly TUpdate unitUpdate_;

		public int Count { get; }

		public TData this[int index] => Query(index);

		public LazySegmentTree(
			int count,
			TData unitData,
			TUpdate unitUpdate,
			Func<TData, TData, TData> operate,
			Func<TData, TUpdate, int, TData> update,
			Func<TUpdate, TUpdate, TUpdate> compose)
		{
			Count = count;
			n_ = 1;
			while (n_ < count) {
				n_ <<= 1;
			}

			data_ = new TData[n_ << 1];
			for (int i = 0; i < data_.Length; i++) {
				data_[i] = unitData;
			}

			lazy_ = new TUpdate[n_ << 1];
			for (int i = 0; i < lazy_.Length; i++) {
				lazy_[i] = unitUpdate;
			}

			unitData_ = unitData;
			unitUpdate_ = unitUpdate;
			operate_ = operate;
			update_ = update;
			compose_ = compose;
		}

		public LazySegmentTree(
			IReadOnlyList<TData> src,
			TData unitData,
			TUpdate unitUpdate,
			Func<TData, TData, TData> operate,
			Func<TData, TUpdate, int, TData> update,
			Func<TUpdate, TUpdate, TUpdate> compose)
			: this(src.Count, unitData, unitUpdate, operate, update, compose)
		{
			for (int i = 0; i < src.Count; i++) {
				data_[i + n_] = src[i];
			}

			for (int i = n_ - 1; i > 0; --i) {
				data_[i] = operate_(data_[i << 1], data_[(i << 1) + 1]);
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public void Update(int v, TUpdate value)
			=> Update(v, v + 1, value);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public void Update(Range range, TUpdate value)
			=> Update(range.Start.Value, range.End.Value, value);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public void Update(int left, int right, TUpdate value)
			=> UpdateCore(left, right, 1, 0, n_, value);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void UpdateCore(int left, int right, int v, int l, int r, TUpdate value)
		{
			if (left <= l && r <= right) {
				Propagate(v, l, r, value);
			} else if (left < r && l < right) {
				int lc = v << 1;
				int rc = (v << 1) + 1;
				int mid = (l + r) >> 1;
				Propagate(lc, l, mid, v);
				UpdateCore(left, right, lc, l, mid, value);
				Propagate(rc, mid, r, v);
				UpdateCore(left, right, rc, mid, r, value);
				data_[v] = operate_(data_[lc], data_[rc]);
				lazy_[v] = unitUpdate_;
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public TData Query(int v) => Query(v, v + 1);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public TData Query(Range range) => Query(range.Start.Value, range.End.Value);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public TData Query(int left, int right)
			=> QueryCore(left, right, 1, 0, n_);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private TData QueryCore(int left, int right, int v, int l, int r)
		{
			if (left <= l && r <= right) {
				return data_[v];
			} else if (r <= left || right <= l) {
				return unitData_;
			} else {
				int lc = v << 1;
				int rc = (v << 1) + 1;
				int mid = (l + r) >> 1;
				Propagate(lc, l, mid, v);
				Propagate(rc, mid, r, v);
				lazy_[v] = unitUpdate_;
				return operate_(
					QueryCore(left, right, lc, l, mid),
					QueryCore(left, right, rc, mid, r)
				);
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public int FindLeftest(Range range, Func<TData, bool> check)
			=> FindLeftest(range.Start.Value, range.End.Value, check);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public int FindLeftest(int left, int right, Func<TData, bool> check)
			=> FindLeftestCore(left, right, 1, 0, n_, check);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private int FindLeftestCore(int left, int right, int v, int l, int r, Func<TData, bool> check)
		{
			if (check(data_[v]) == false || r <= left || right <= l) {
				return right;
			} else if (v >= n_) {
				return v - n_;
			} else {
				int lc = v << 1;
				int rc = (v << 1) + 1;
				int mid = (l + r) >> 1;
				Propagate(lc, l, mid, v);
				Propagate(rc, mid, r, v);
				lazy_[v] = unitUpdate_;

				int vl = FindLeftestCore(left, right, lc, l, mid, check);
				if (vl != right) {
					return vl;
				} else {
					return FindLeftestCore(left, right, rc, mid, r, check);
				}
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public int FindRightest(Range range, Func<TData, bool> check)
			=> FindRightest(range.Start.Value, range.End.Value, check);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public int FindRightest(int left, int right, Func<TData, bool> check)
			=> FindRightestCore(left, right, 1, 0, n_, check);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private int FindRightestCore(int left, int right, int v, int l, int r, Func<TData, bool> check)
		{
			if (check(data_[v]) == false || r <= left || right <= l) {
				return left - 1;
			} else if (v >= n_) {
				return v - n_;
			} else {
				int lc = v << 1;
				int rc = (v << 1) + 1;
				int mid = (l + r) >> 1;
				Propagate(lc, l, mid, v);
				Propagate(rc, mid, r, v);
				lazy_[v] = unitUpdate_;

				int vr = FindRightestCore(left, right, rc, mid, r, check);
				if (vr != left - 1) {
					return vr;
				} else {
					return FindRightestCore(left, right, lc, l, mid, check);
				}
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void Propagate(int v, int l, int r, int p)
			=> Propagate(v, l, r, lazy_[p]);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void Propagate(int v, int l, int r, TUpdate value)
		{
			data_[v] = update_(data_[v], value, r - l);
			lazy_[v] = compose_(lazy_[v], value);
		}

		public IEnumerator<TData> GetEnumerator()
		{
			for (int i = 0; i < Count; i++) {
				yield return this[i];
			}
		}

		IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
	};

	public class HashMap<TKey, TValue> : Dictionary<TKey, TValue>
	{
		private readonly Func<TKey, TValue> initialzier_;
		public HashMap(Func<TKey, TValue> initialzier)
			: base()
		{
			initialzier_ = initialzier;
		}

		public HashMap(Func<TKey, TValue> initialzier, int capacity)
			: base(capacity)
		{
			initialzier_ = initialzier;
		}

		new public TValue this[TKey key]
		{
			get
			{
				if (ContainsKey(key) == false) {
					base[key] = initialzier_(key);
				}

				return base[key];
			}

			set { base[key] = value; }
		}
	}

	public struct ModInt
	{
		//public const long P = 1000000007;
		public const long P = 998244353;
		public const long ROOT = 3;

		// (924844033, 5)
		// (998244353, 3)
		// (1012924417, 5)
		// (167772161, 3)
		// (469762049, 3)
		// (1224736769, 3)

		private long value_;

		public ModInt(long value)
			=> value_ = value;
		public ModInt(long value, bool mods)
		{
			if (mods) {
				value %= P;
				if (value < 0) {
					value += P;
				}
			}

			value_ = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (lhs.value_ + rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator +(long lhs, ModInt rhs)
		{
			rhs.value_ = (lhs + rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator +(ModInt lhs, long rhs)
		{
			lhs.value_ = (lhs.value_ + rhs) % P;
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator -(long lhs, ModInt rhs)
		{
			rhs.value_ = (P + lhs - rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator -(ModInt lhs, long rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs) % P;
			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = lhs.value_ * rhs.value_ % P;
			return lhs;
		}
		public static ModInt operator *(long lhs, ModInt rhs)
		{
			rhs.value_ = lhs * rhs.value_ % P;
			return rhs;
		}
		public static ModInt operator *(ModInt lhs, long rhs)
		{
			lhs.value_ = lhs.value_ * rhs % P;
			return lhs;
		}

		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n) => new ModInt(n, true);

		public static ModInt Inverse(ModInt value) => Pow(value, P - 2);
		public static ModInt Pow(ModInt value, long k) => Pow(value.value_, k);
		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}


		public static Span<ModInt> NumberTheoreticTransform(
			Span<int> values, bool inverses = false)
		{
			var mods = new ModInt[values.Length];
			for (int i = 0; i < mods.Length; i++) {
				mods[i] = new ModInt(values[i]);
			}

			return NumberTheoreticTransform(mods, inverses);
		}

		public static Span<ModInt> NumberTheoreticTransform(
			Span<long> values, bool inverses = false)
		{
			var mods = new ModInt[values.Length];
			for (int i = 0; i < mods.Length; i++) {
				mods[i] = new ModInt(values[i]);
			}

			return NumberTheoreticTransform(mods, inverses);
		}

		public static Span<ModInt> NumberTheoreticTransform(
			Span<ModInt> a, bool inverses = false)
		{
			int n = a.Length;
			if (n == 1) {
				return a;
			}

			var b = new ModInt[n].AsSpan();
			int r = inverses
				? (int)((P - 1 - (P - 1) / n))
				: (int)((P - 1) / n);
			ModInt s = Pow(ROOT, r);
			var kp = new ModInt[n / 2 + 1];
			kp.AsSpan().Fill(1);

			for (int i = 0; i < n / 2; ++i) {
				kp[i + 1] = kp[i] * s;
			}

			int l = n / 2;
			for (int i = 1; i < n; i <<= 1, l >>= 1) {
				r = 0;
				for (int j = 0; j < l; ++j, r += i) {
					s = kp[i * j];
					for (int k = 0; k < i; ++k) {
						var p = a[k + r];
						var q = a[k + r + n / 2];
						b[k + 2 * r] = p + q;
						b[k + 2 * r + i] = (p - q) * s;
					}
				}

				var temp = a;
				a = b;
				b = temp;
			}

			if (inverses) {
				s = Inverse(n);
				for (int i = 0; i < n; i++) {
					a[i] = a[i] * s;
				}
			}

			return a;
		}

		public static Span<ModInt> Convolve(ReadOnlySpan<ModInt> a, ReadOnlySpan<ModInt> b)
		{
			int resultLength = a.Length + b.Length - 1;
			int nttLenght = 1;
			while (nttLenght < resultLength) {
				nttLenght <<= 1;
			}

			var aa = new ModInt[nttLenght];
			a.CopyTo(aa);
			var bb = new ModInt[nttLenght];
			b.CopyTo(bb);

			var fa = NumberTheoreticTransform(aa);
			var fb = NumberTheoreticTransform(bb);
			for (int i = 0; i < nttLenght; i++) {
				fa[i] *= fb[i];
			}

			var convolved = NumberTheoreticTransform(fa, true);
			return convolved.Slice(0, resultLength);
		}

