namespace Contest_K {

public static class Entry
{

	public static void Main() {
		checked{
			long n, q;
			Lib_IO.rm(out n, out q);
			int[] a;
			ra(out a);
			int[][] t;
			rx(q,out t);

			Func<P<ll,int>,P<ll,int>,P<ll,int>> f = (x,y)=>new P<ll,int>((x.A+y.A)%MOD1,x.B+y.B);
			Func<P<ll,int>,S,P<ll,int>> g = (x,y)=>new P<ll,int>((x.A*y.A+y.B*x.B)%MOD1,x.B);
			Func<S,S,S> h = (x,y)=> new S((x.A*y.A)%MOD1,(x.B*y.A+y.B)%MOD1);

			LazySegmentTree<P<ll,int>,S> seg = new LazySegmentTree<P<ll,int>, S>(n,f,g,h,new P<ll, int>(0,0),new S(1,0));
			for (int i = 0; i < n; i++)
			{
				seg[i] = new P<ll, int>(a[i],1);
			}
			seg.Build();
			List<ll> ans = new List<ll>();
			foreach (var e in t)
			{
				if(e[0]==0){
					seg.Update(e[1],e[2],new S(e[3],e[4]));
				}
				if(e[0]==1){
					ans.Add(seg.Query(e[1],e[2]).A);
				}
			}

			Lib_IO.wl(ans);
		}
	}

struct S : IEquatable<S>
{
	public ll A;
	public ll B;
	public S (ll a, ll b){
		A=a;
		B=b;
	}
	public bool Equals(S other) => A == other.A && B == other.B;
}

public class LazySegmentTree<TM, TO> where TO: IEquatable<TO>  {
	private int sz, height;
	private TM[] data;
	private TO[] lazy;
	private Func<TM, TM, TM> f;
	private Func<TM, TO, TM> g;
	private Func<TO, TO, TO> h;
	private Func<TO, long, TO> p;
	private TM M1;
	private TO O1;

	public LazySegmentTree(long n, Func<TM, TM, TM> F, Func<TM, TO, TM> G, Func<TO, TO, TO> H, TM M1, TO O1, Func<TO, long, TO> P=null) {
		f = F; g = G; h = H;
		p = (P==null?((x,y)=>x):P);
		this.M1 = M1; this.O1 = O1;
		sz = 1;
		height = 0;
		while(sz < n) {sz <<= 1; height++; }
		data = Enumerable.Repeat(M1, 2 * sz).ToArray();
		lazy = Enumerable.Repeat(O1, 2 * sz).ToArray();
	}
	public TM this[long k] {
		get { return Query(k, k + 1); }
		set { data[k + sz - 1] = value; }
	}
	public void Build() {
		for(int k = sz - 2; k >= 0; k--) {
			data[k] = f(data[2 * k + 1], data[2 * k + 2]);
		}
	}

	private void eval(int k, int len) {
		if(lazy[k].Equals(O1)) return;  // 更新するものが無ければ終了
		if (k < sz - 1) {            // 葉でなければ子に伝搬
			lazy[2 * k + 1] = h(lazy[2 * k + 1], lazy[k]);
			lazy[2 * k + 2] = h(lazy[2 * k + 2], lazy[k]);
		}
		// 自身を更新
		data[k] = g(data[k], p(lazy[k], len));
		lazy[k] = O1;
	}

	private void Update(long a, long b, TO x, int k, int l, int r ){
		eval(k, r-l);
        if (a <= l && r <= b) {  // 完全に内側の時
            lazy[k] = h(lazy[k], x);
            eval(k, r-l);
        } else if (a < r && l < b) {                     // 一部区間が被る時
            Update(a, b, x, k * 2 + 1, l, (l + r) / 2);  // 左の子
            Update(a, b, x, k * 2 + 2, (l + r) / 2, r);  // 右の子
            data[k] = f(data[k * 2 + 1], data[k * 2 + 2]);
        }
	}
	public void Update(int a, int b, TO x) => Update(a, b, x, 0, 0, sz);

	private TM Query(long a, long b, int k, int l, int r) {
		eval(k, r-l);
        if (r <= a || b <= l) {  // 完全に外側の時
            return M1;
        } else if (a <= l && r <= b) {  // 完全に内側の時
            return data[k];
        } else {  // 一部区間が被る時
            TM vl = Query(a, b, k * 2 + 1, l, (l + r) / 2);
            TM vr = Query(a, b, k * 2 + 2, (l + r) / 2, r);
            return f(vl, vr);
        }
	}
	public TM Query(long a, long b) => Query(a, b, 0, 0, sz);

    public long FindRightest(long a, long b, Func<TM,bool> c) => FindRightest(a, b, c, 0, 0, sz);
    public long FindLeftest(long a, long b, Func<TM,bool> c) => FindLeftest(a, b, c, 0, 0, sz);
    private long FindRightest(long a, long b, Func<TM,bool> c, int k, int l, int r) {
		eval(k, r-l);
        if (!c(data[k]) || r <= a || b <= l) {  // 自分の値が条件を満たさない or [a,b)が[l,r)の範囲外ならreturn a-1
            return a - 1;
        } else if (k >= sz - 1) {  // 自分が葉ならその位置をreturn
            return (k - (sz - 1));
        } else {
            var vr = FindRightest(a, b, c, 2 * k + 2, (l + r) / 2, r);
            if (vr != a - 1) {  // 右の部分木を見て a-1 以外ならreturn
                return vr;
            } else {  // 左の部分木を見て値をreturn
                return FindRightest(a, b, c, 2 * k + 1, l, (l + r) / 2);
            }
        }
    }
    private long FindLeftest(long a, long b, Func<TM,bool> c, int k, int l, int r) {
		eval(k, r-l);
        if (!c(data[k]) || r <= a || b <= l) {  // 自分の値が条件を満たさない or [a,b)が[l,r)の範囲外ならreturn b
            return b;
        } else if (k >= sz - 1) {  // 自分が葉ならその位置をreturn
            return (k - (sz - 1));
        } else {
            var vl = FindLeftest(a, b, c, 2 * k + 1, l, (l + r) / 2);
            if (vl != b) {  // 左の部分木を見て b 以外ならreturn
                return vl;
            } else {  // 右の部分木を見て値をreturn
                return FindLeftest(a, b, c, 2 * k + 2, (l + r) / 2, r);
            }
        }
    }

}














