public static class Entry
{

	public static void Main() {
		checked{
			long n, q;
			Lib_IO.rm(out n, out q);
			int[] a;
			ra(out a);
			int[][] t;
			rx(q,out t);

			Func<ll,ll,ll> f = (x,y)=>(x+y)%MOD1;
			Func<ll,S,ll> g = (x,y)=>(x*y.A+y.B)%MOD1;
			Func<S,S,S> h = (x,y)=> new S((x.A*y.A)%MOD1,(x.B*y.A+y.B)%MOD1);
			Func<S,ll,S> p = (x,l)=>new S((x.A)%MOD1,(x.B*l)%MOD1);

			LazySegmentTree<ll,S> seg = new LazySegmentTree<ll, S>(n,f,g,h,0,new S(1,0),p);
			for (int i = 0; i < n; i++)
			{
				seg[i] = a[i];
			}
			seg.Build();
			List<ll> ans = new List<ll>();
			foreach (var e in t)
			{
				if(e[0]==0){
					seg.Update(e[1],e[2],new S(e[3],e[4]));
				}
				if(e[0]==1){
					ans.Add(seg.Query(e[1],e[2]));
				}
			}

			Lib_IO.wl(ans);
		}
	}

