using CompLib.Collections.Generic;
using CompLib.Mathematics;
using CompLib.Util;
using System;

public class Program
{

    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int q = sc.NextInt();
        (ModInt num, int len)[] a = new (ModInt num, int len)[n];
        for (int i = 0; i < n; i++)
        {
            a[i] = (sc.NextInt(), 1);
        }

        var lst = new LazySegmentTree<(ModInt num, int len), (ModInt b, ModInt c)>(
            a,
            (l, r) => (l.num + r.num, l.len + r.len),
            (0, 0),
            (l, r) => (r.num * l.b + r.len * l.c, r.len),
            (l, r) => (l.b * r.b, r.c * l.b + l.c)
            , (1, 0));

        // Console.SetOut(new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
        for (int i = 0; i < q; i++)
        {
            int t = sc.NextInt();
            if (t == 0)
            {
                int l = sc.NextInt();
                int r = sc.NextInt();
                int b = sc.NextInt();
                int c = sc.NextInt();
                lst.Apply(l, r, (b, c));
            }
            if (t == 1)
            {
                int l = sc.NextInt();
                int r = sc.NextInt();
                Console.WriteLine(lst.Query(l, r).num);
