        // (u,v,a) => (x,y,d)となっている
        // dは最終的にaとbのgcdとなる
        long b = mod, u = 1, v = 0;
        while (b > 0)
        {
            long t = a / b;
            (a, b) = (b, a - t * b);
            (u, v) = (v, u - t * v);
        }
        return (u, v, a);
    }

    static long[] MakeInverseCache()
    {
        var res = new long[1 + (int)Math.Sqrt(mod)];
        res[1] = 1;
        for (int i = 2; i < res.Length; i++)
        {
