        long b = mod, u = 1, v = 0;
        while (b > 0)
        {
            if (0 <= a && a < cache.Length)
                return cache[a] * u;
            long t = a / b;
            (a, b) = (b, a - t * b);
            (u, v) = (v, u - t * v);
        }
        return u;
    }
