        {
            public readonly ModuloInteger A;
            public readonly int Size;

            public S(ModuloInteger a, int size)
            {
                A = a;
                Size = size;
            }
        }

        public readonly struct F
        {
            public readonly ModuloInteger A;
            public readonly ModuloInteger B;

            public F(ModuloInteger a, ModuloInteger b)
            {
                A = a;
                B = b;
            }
        }
    }
