public struct MulAndAddOperatorMonoid : IEquatable<MulAndAddOperatorMonoid> {
    public long Mul;
    public long Add;

    public bool Equals(MulAndAddOperatorMonoid other) {
        return Mul == other.Mul && Add == other.Add;
    }
}

/// <summary>
/// query       : a1 + a2 + ... + an
/// range-update: a <- a * Mul + Add
/// </summary>
public class LazySegmentTreeMulAndAddMonoidOperator : ILazySegmentTreeDefinition<long, MulAndAddOperatorMonoid> {
    private readonly int _mod;

    public long Identity { get { return 0; } }
    public MulAndAddOperatorMonoid OperatorIdentity { get { return new MulAndAddOperatorMonoid { Mul = 1 }; } }

    public LazySegmentTreeMulAndAddMonoidOperator(int mod) {
        _mod = mod;
    }

    public long Merge(long left, long right) {
        return (left + right) % _mod;
    }

    public long Apply(long monoid, int begin, int end, MulAndAddOperatorMonoid operation) {
        if (operation.Mul == 1 && operation.Add == 0) return monoid;
        // (a1 * mul + add) + (a2 * mul + add) + ... (a_n * mul + add)
        // (a1 + .. a_n) * mul + add * n
        return (1L * monoid * operation.Mul + 1L * operation.Add * (end - begin)) % _mod;
    }

    public MulAndAddOperatorMonoid MergeOperator(MulAndAddOperatorMonoid current, MulAndAddOperatorMonoid append) {
        if (current.Mul == 1 && current.Add == 0) return append;
        // (x * mul1 + add1) * mul2 + add2
        // x * mul1 * mul2 + add1 * mul2 + add2
        return new MulAndAddOperatorMonoid {
            Mul = current.Mul * append.Mul % _mod,
            Add = (current.Add * append.Mul + append.Add) % _mod,
        };
    }
}
