public class LazySegmentTree<T, E>
{
    protected readonly int size, _N, log;
    protected readonly T idT;
    protected readonly T[] dat;
    protected readonly E idE;
    protected readonly E[] lazy;
    protected readonly Func<T, T, T> mergeT;
    protected readonly Func<T, E, T> update;
    protected readonly Func<E, E, E> mergeE;

    public T this[int i]
    {
        get { return dat[i + size]; }
        set { dat[i + size] = value; }
    }

    public LazySegmentTree(int N, T idT, E idE, Func<T, T, T> mergeT, Func<T, E, T> update = null, Func<E, E, E> mergeE = null)
    {
        _N = N;
        this.size = 1;
        this.idT = idT;
        this.idE = idE;
        this.mergeT = mergeT;
        this.update = update ?? ((a, b) => a);
        this.mergeE = mergeE ?? ((a, b) => b);
        while ((1 << log) < N) log++;
        size = 1 << log;
        dat = new T[2 * size];
        lazy = new E[size];
        for (var i = 0; i < dat.Length; i++) dat[i] = idT;
        for (int i = 0; i < lazy.Length; i++) lazy[i] = idE;
    }
    public void Build()
    {
        for (int i = size - 1; i >= 1; i--) Update(i);
    }
    public void Set(int p, T t)
    {
        p += size;
        for (int i = log; i >= 1; i--) Push(p >> i);
        dat[p] = t;
        for (int i = 1; i <= log; i++) Update(p >> i);
    }
    public T Get(int p)
    {
        p += size;
        for (int i = log; i >= 1; i--) Push(p >> i);
        return dat[p];
    }
    public T Query(int l, int r)
    {
        if (r <= l) return idT;
        l += size; r += size;
        for (int i = log; i >= 1; i--)
        {
            if (((l >> i) << i) != l) Push(l >> i);
            if (((r >> i) << i) != r) Push(r >> i);
        }
        var sml = idT; var smr = idT;
        while (l < r)
        {
            if ((l & 1) == 1) sml = mergeT(sml, dat[l++]);
            if ((r & 1) == 1) smr = mergeT(dat[--r], smr);
            l >>= 1; r >>= 1;
        }
        return mergeT(sml, smr);
    }
    public void Update(int l, int r, E e)
    {
        if (l == r) return;
        l += size; r += size;

        for (int i = log; i >= 1; i--)
        {
            if (((l >> i) << i) != l) Push(l >> i);
            if (((r >> i) << i) != r) Push((r - 1) >> i);
        }
        int l2 = l, r2 = r;
        while (l < r)
        {
            if ((l & 1) == 1) Apply(l++, e);
            if ((r & 1) == 1) Apply(--r, e);
            l >>= 1;
            r >>= 1;
        }
        l = l2;
        r = r2;
        for (int i = 1; i <= log; i++)
        {
            if (((l >> i) << i) != l) Update(l >> i);
            if (((r >> i) << i) != r) Update((r - 1) >> i);
        }
    }
    public int MaxRight(int l, Func<T, bool> f)
    {
        if (l == _N) return _N;
        l += size;
        for (int i = log; i >= 1; i--) Push(l >> i);
        var sm = idT;
        do
        {
            while (l % 2 == 0) l >>= 1;
            if (!f(mergeT(sm, dat[l])))
            {
                while (l < size)
                {
                    Push(l);
                    l <<= 1;
                    if (f(mergeT(sm, dat[l])))
                    {
                        sm = mergeT(sm, dat[l]);
                        l++;
                    }
                }
                return l - size;
            }
            sm = mergeT(sm, dat[l]);
            l++;
        } while ((l & -l) != l);
        return _N;
    }
    public int MinLeft(int r, Func<T, bool> f)
    {
        if (r == 0) return 0;
        r += size;
        for (int i = log; i >= 1; i--) Push((r - 1) >> i);
        var sm = idT;
        do
        {
            r--;
            while (r > 1 && (r & 1) == 1) r >>= 1;
            if (!f(mergeT(dat[r], sm)))
            {
                while (r < size)
                {
                    Push(r);
                    r = (r << 1) | 1;
                    if (f(mergeT(dat[r], sm)))
                    {
                        sm = mergeT(dat[r], sm);
                        r--;
                    }
                }
                return r + 1 - size;
            }
            sm = mergeT(dat[r], sm);
        } while ((r & -r) != r);
        return 0;
    }
    void Apply(int k, E e)
    {
        dat[k] = update(dat[k], e);
        if (k < size) lazy[k] = mergeE(e, lazy[k]);
    }
    void Push(int k)
    {
        Apply(k << 1, lazy[k]);
        Apply((k << 1) | 1, lazy[k]);
        lazy[k] = idE;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    void Update(int k) => dat[k] = mergeT(dat[k << 1], dat[(k << 1) | 1]);
}

public struct ModInt
{
    public const long MOD = (int)1e9 + 7;
    //public const long MOD = 998244353;
    public long Value { get; set; }
    public ModInt(long n = 0) { Value = n; }
    private static ModInt[] fac, inv, facinv;
    public override string ToString() => Value.ToString();
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt operator +(ModInt l, ModInt r)
    {
        l.Value += r.Value;
        if (l.Value >= MOD) l.Value -= MOD;
        return l;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt operator -(ModInt l, ModInt r)
    {
        l.Value -= r.Value;
        if (l.Value < 0) l.Value += MOD;
        return l;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt operator *(ModInt l, ModInt r) => new ModInt(l.Value * r.Value % MOD);
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt operator /(ModInt l, ModInt r) => l * Pow(r, MOD - 2);
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static implicit operator long(ModInt l) => l.Value;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static implicit operator ModInt(long n)
    {
        n %= MOD; if (n < 0) n += MOD;
        return new ModInt(n);
    }

    public static ModInt Pow(ModInt m, long n)
    {
        if (n == 0) return 1;
        if (n % 2 == 0) return Pow(m * m, n >> 1);
        else return Pow(m * m, n >> 1) * m;
    }

    public static void Build(int n)
    {
        fac = new ModInt[n + 1];
        facinv = new ModInt[n + 1];
        inv = new ModInt[n + 1];
        inv[1] = fac[0] = fac[1] = facinv[0] = facinv[1] = 1;
        for (var i = 2; i <= n; i++)
        {
            fac[i] = fac[i - 1] * i;
            inv[i] = MOD - inv[MOD % i] * (MOD / i);
            facinv[i] = facinv[i - 1] * inv[i];
        }
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt Fac(int n) => fac[n];
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt Inv(int n) => inv[n];
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt FacInv(int n) => facinv[n];
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ModInt Comb(int n, int r)
    {
        if (n < r) return 0;
        if (n == r) return 1;
        return fac[n] * facinv[r] * facinv[n - r];
    }
    public static ModInt Perm(int n, int r)
    {
        if (n < r) return 0;
        return fac[n] * facinv[n - r];
    }

}

public class FastScanner
{
    //0x0a:LF 0x20:SPC 0x2d:- 0x30 ~ 0x39: 0 ~ 9
    static System.IO.Stream str = System.Console.OpenStandardInput();
    const int size = 1 << 10;
    static byte[] buffer = new byte[size];
    static int ptr;
    static int len;
    public int Int
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    public long Long
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0L;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    byte Read()
    {
        if (ptr == len)
        {
            len = str.Read(buffer, 0, size);
            if (len == 0) return 0;
            ptr = 0;
        }
        return buffer[ptr++];
    }
}

