            {
                xor >>= 1; l >>= 1; r >>= 1;
                dat[l] = f(Reflect((l << 1) | 0), Reflect((l << 1) | 1));
                dat[r] = f(Reflect((r << 1) | 0), Reflect((r << 1) | 1));
            }
            while (l > 1)
