        {
            if (l < 0 || r < l || _n < r) throw new IndexOutOfRangeException();
            if (l == r) return;
            l += _size;
            r += _size;
            for (var i = _log; i >= 1; i--)
            {
                if ((l >> i) << i != l) Push(l >> i);
                if ((r >> i) << i != r) Push((r - 1) >> i);
            }

            var (l2, r2) = (l, r);
            while (l2 < r2)
