    public class LazySegmentTree<T, TOperator> where TOperator : IEquatable<TOperator>
    {
        public int Size { get; }

        readonly int _height;

        readonly T[] _data;
        readonly TOperator[] _lazy;

        readonly Func<T, T, T> _f;
        readonly Func<T, TOperator, T> _g;
        readonly Func<TOperator, TOperator, TOperator> _h;
        readonly T _identity;
        readonly TOperator _operatorIdentity;

        public LazySegmentTree(int n,
            Func<T, T, T> f,
            Func<T, TOperator, T> g,
            Func<TOperator, TOperator, TOperator> h,
            T identity = default,
            TOperator operatorIdentity = default
        ) {
            int sz = 1;
            int height = 0;
            while (sz < n) {
                sz <<= 1;
                height++;
            }

            Size = sz;
            _height = height;
            _data = Enumerable.Repeat(identity, 2 * sz).ToArray();
            _lazy = Enumerable.Repeat(operatorIdentity, 2 * sz).ToArray();
            (_f, _g, _h) = (f, g, h);
            _identity = identity;
            _operatorIdentity = operatorIdentity;
        }

        public void Set(int i, T x) => _data[i + Size] = x;

        public void Build() {
            for (int i = Size - 1; i > 0; i--) _data[i] = _f(_data[2 * i + 0], _data[2 * i + 1]);
        }

        [MethodImpl(256)] public void Propagate(int i) {
            if (_lazy[i].Equals(_operatorIdentity)) return;
            _lazy[2 * i + 0] = _h(_lazy[2 * i + 0], _lazy[i]);
            _lazy[2 * i + 1] = _h(_lazy[2 * i + 1], _lazy[i]);
            _data[i] = Reflect(i);
            _lazy[i] = _operatorIdentity;
        }

        [MethodImpl(256)]
        T Reflect(int i) => _lazy[i].Equals(_operatorIdentity) ? _data[i] : _g(_data[i], _lazy[i]);

        [MethodImpl(256)] void Recalc(int i) {
            while ((i >>= 1) > 0) _data[i] = _f(Reflect(2 * i + 0), Reflect(2 * i + 1));
        }

        [MethodImpl(256)] void Thrust(int i) { for (int j = _height; j > 0; j--) Propagate(i >> j); }

        public void Update(int a, int b, TOperator x) {
            Thrust(a += Size);
            Thrust(b += Size - 1);
            for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
                if ((l & 1) != 0) { _lazy[l] = _h(_lazy[l], x); ++l; }
                if ((r & 1) != 0) { --r; _lazy[r] = _h(_lazy[r], x); }
            }

            Recalc(a);
            Recalc(b);
        }

        public T Query(int a, int b) {
            Thrust(a += Size);
            Thrust(b += Size - 1);
            T L = _identity, R = _identity;
            for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
                if ((l & 1) != 0) L = _f(L, Reflect(l++));
                if ((r & 1) != 0) R = _f(Reflect(--r), R);
            }

            return _f(L, R);
        }

        public T this[int k] {
            get => Query(k, k + 1);
            set => Set(k, value);
        }
    }

    [DebuggerDisplay("{" + nameof(_value) + "}")]
    public struct ModInt : IEquatable<ModInt>, IComparable<ModInt>
    {
        public const int MOD = 998244353;
        private long _value;
        public static readonly ModInt Zero = new ModInt(0);
        public static readonly ModInt One = new ModInt(1);
        public ModInt(in long value) => _value = (value % MOD + MOD) % MOD;
        public int Value => (int) _value;
        public ModInt Invert => ModPow(this, MOD - 2);
        public static ModInt operator -(ModInt value) {
            value._value = MOD - value._value;
            return value;
        }
        public static ModInt operator +(ModInt left, in ModInt right) {
            left._value += right._value;
            if (left._value >= MOD) left._value -= MOD;
            return left;
        }
        public static ModInt operator -(ModInt left, in ModInt right) {
            left._value -= right._value;
            if (left._value < 0) left._value += MOD;
            return left;
        }
        public static ModInt operator *(ModInt left, in ModInt right) => left._value * right._value % MOD;
        public static ModInt operator /(ModInt left, in ModInt right) => left * right.Invert;
        public static ModInt operator ++(ModInt value) {
            if (value._value == MOD - 1) value._value = 0;
            else value._value++;
            return value;
        }
        public static ModInt operator --(ModInt value) {
            if (value._value == 0) value._value = MOD - 1;
            else value._value--;
            return value;
        }
        public static bool operator ==(ModInt left, in ModInt right) => left.Equals(right);
        public static bool operator !=(ModInt left, in ModInt right) => !left.Equals(right);
        public static implicit operator ModInt(in int value) => new ModInt(value);
        public static implicit operator ModInt(in long value) => new ModInt(value);
        public static explicit operator int(ModInt m) => m.Value;
        public static ModInt ModPow(ModInt value, long exponent) {
            var r = new ModInt(1);
            for (; exponent > 0; value *= value, exponent >>= 1)
                if ((exponent & 1) == 1)
                    r *= value;
            return r;
        }
        public static ModInt ModFact(int value) {
            var r = new ModInt(1);
            for (var i = 2; i <= value; i++) r *= value;
            return r;
        }
        public bool Equals(ModInt other) => _value == other._value;
        public override bool Equals(object obj) => obj is ModInt m && Equals(m);
        public override int GetHashCode() => _value.GetHashCode();
        public override string ToString() => _value.ToString();
        public int CompareTo(ModInt other) => _value.CompareTo(other._value);
    }
