		const uint P = 998244353;
		const int MASK = 1073741823;

		static void Main()
		{
			using var cin = new Scanner();
			var (n, q) = cin.Int2();
			var a = cin.ArrayInt(n).Select(x => (uint)x).ToArray();

			var seg = new LazySegmentTree<uint, ulong>(
				a,
				0,
				1UL << 31,
				(x, y) => { 
					var ret = x + y;
					if (ret > P) {
						ret -= P;
					}

					return ret;
				},
				(x, y, n) => (uint)((x * (y >> 31) + (y & MASK) * (ulong)n) % P),
				(g, f) => ((((f >> 31) * (g >> 31)) % P) << 31) | (((f & MASK) * (g >> 31) + (g & MASK)) % P));
			for (int i = 0; i < q; i++) {
				int t = cin.Int();
				if (t == 0) {
					var (l, r, b, c) = cin.Int4();
					seg.Update(l, r, ((ulong)b << 31) + (ulong)c);
				} else {
					var (l, r) = cin.Int2();
