        public override string ToString() => Value.ToString();

        public ModuloInteger Inverse() => Inverse(Value);

        public static ModuloInteger Inverse(long a)
        {
            a %= Modulo;
            if (a < 0) a += Modulo;
            if (a == 0) return 0;
            var (s, t, m0, m1) = (Modulo, a, 0L, 1L);
            while (t > 1)
            {
                var u = s / t;
                s -= t * u;
                m0 -= m1 * u;
                (s, t) = (t, s);
                (m0, m1) = (m1, m0);
            }

            if (m0 < 0) m0 += Modulo / s;
            return m0;
        }

