public class LazySegmentTree<TM, TO> {
	private int sz, height;
	private TM[] data;
	private TO[] lazy;
	private Func<TM, TM, TM> f;
	private Func<TM, TO, TM> g;
	private Func<TO, TO, TO> h;
	private TM M1;
	private TO OM0;

	public LazySegmentTree(long n, Func<TM, TM, TM> F, Func<TM, TO, TM> G, Func<TO, TO, TO> H, TM M1, TO OM0) {
		f = F; g = G; h = H;
		this.M1 = M1; this.OM0 = OM0;
		sz = 1;
		height = 0;
		while(sz < n) {sz <<= 1; height++; }
		data = new TM[2*sz];
		lazy = new TO[2*sz];
		for (int i = 0; i < 2*sz; i++)
		{
			data[i] = M1;
			lazy[i] = OM0;
		}
		//data = Enumerable.Repeat(M1, 2 * sz).ToArray();
		//lazy = Enumerable.Repeat(OM0, 2 * sz).ToArray();
	}

	public void Build() {
		for(int k = sz - 1; k > 0; k--) {
			data[k] = f(data[2 * k + 0], data[2 * k + 1]);
		}
	}

	private void propagate(long k) {
		if(!lazy[k].Equals(OM0)) {
			lazy[2 * k + 0] = h(lazy[2 * k + 0], lazy[k]);
			lazy[2 * k + 1] = h(lazy[2 * k + 1], lazy[k]);
			data[k] = reflect(k);
			lazy[k] = OM0;
		}
	}
	[CS.MethodImpl(256)] private TM reflect(long k) {
		return lazy[k].Equals(OM0) ? data[k] : g(data[k], lazy[k]);
	}
	[CS.MethodImpl(256)] private void recalc(long k) {
		while(0<(k >>= 1)) data[k] = f(reflect(2 * k + 0), reflect(2 * k + 1));
	}
	[CS.MethodImpl(256)] private void thrust(long k) {
		for(int i = height; i > 0; i--) propagate(k >> i);
	}

	public void Update(long a, long b, TO x) {
		thrust(a += sz);
		thrust(b += sz - 1);
		for(long l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
			if((l & 1)==1) { lazy[l] = h(lazy[l], x); ++l; }
			if((r & 1)==1) { --r; lazy[r] = h(lazy[r], x); }
		}
		recalc(a);
		recalc(b);
	}
	public TM Query(long a, long b) {
		thrust(a += sz);
		thrust(b += sz - 1);
		TM L = M1, R = M1;
		for(long l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
			if((l & 1)==1) L = f(L, reflect(l++));
			if((r & 1)==1) R = f(reflect(--r), R);
		}
		return f(L, R);
	}

	public TM this[long k] {
		get { return Query(k, k + 1); }
		set { data[k + sz] = value; }
	}

}

















