class SegmentTreeLazy : SegmentTreeLazyAbstract<(int v, int size), (int b, int c)>
{
    const long mod = 998244353;
    static int ModAdd(long v1, long v2)
    {
        var r = v1 + v2;
        return (int)(r % mod);
    }
    static int ModMul(long v1, long v2)
    {
        return (int)(v1 * v2 % mod);
    }
    protected override (int v, int size) DefaultValue => (0, 0);
    protected override (int b, int c) DefaultLazy => (1, 0);
    protected override (int v, int size) Operate((int v, int size) v1, (int v, int size) v2) => (ModAdd(v1.v, v2.v), v1.size + v2.size);
    protected override (int v, int size) ApplyLazy((int v, int size) v, (int b, int c) l) => (ModMul(l.b, v.v) + ModMul(l.c, v.size), v.size);
    protected override (int b, int c) Merge((int b, int c) l1, (int b, int c) l2) => (ModMul(l1.b, l2.b), ModAdd(ModMul(l1.b, l2.c), l1.c));
    public SegmentTreeLazy((int v, int size)[] initArray) : base(initArray) { }
    public SegmentTreeLazy(int size) : base(size) { }
}
