public interface ILazySegmentTreeMonoidOperator<TMonoid, TOperatorMonoid> {
    TMonoid Merge(TMonoid left, TMonoid right);
    TMonoid Apply(TMonoid monoid, int dataNum, TOperatorMonoid operation);
    TOperatorMonoid MergeOperator(TOperatorMonoid current, TOperatorMonoid append);

    TMonoid Identity { get; }
    TOperatorMonoid OperatorIdentity { get; }
}

public static class LazySegmentTreeExtension {
    public static LazySegmentTree<TMonoid, TOperatorMonoid> CreateLazySegmentTree<TMonoid, TOperatorMonoid>
        (this ILazySegmentTreeMonoidOperator<TMonoid, TOperatorMonoid> lazySegmentTreeMonoidOperator) {
        return new LazySegmentTree<TMonoid, TOperatorMonoid>(
            lazySegmentTreeMonoidOperator.Merge,
            lazySegmentTreeMonoidOperator.Apply,
            lazySegmentTreeMonoidOperator.MergeOperator,
            lazySegmentTreeMonoidOperator.Identity,
            lazySegmentTreeMonoidOperator.OperatorIdentity
        );
    }

    public static bool Check<TMonoid, TOperatorMonoid>
        (this ILazySegmentTreeMonoidOperator<TMonoid, TOperatorMonoid> lazySegmentTreeMonoidOperator, TMonoid m, TOperatorMonoid o1, TOperatorMonoid o2) {
        var r1 = lazySegmentTreeMonoidOperator.Apply(lazySegmentTreeMonoidOperator.Apply(m, 1, o1), 1, o2);
        var r2 = lazySegmentTreeMonoidOperator.Apply(m, 1, lazySegmentTreeMonoidOperator.MergeOperator(o1, o2));
        return r1.Equals(r2);
    }
}

public sealed class LazySegmentTree<TMonoid, TOperatorMonoid> {
    private int Count;
    private TMonoid[] _node;
    private TOperatorMonoid[] _operators;
    private int[] _height;
    private int[] _dataNum;
    private readonly TMonoid _identity;
    private readonly TOperatorMonoid _operatorIdentity;
    private readonly Func<TMonoid, TMonoid, TMonoid> _merge;
    private readonly Func<TMonoid, int, TOperatorMonoid, TMonoid> _apply;
    private readonly Func<TOperatorMonoid, TOperatorMonoid, TOperatorMonoid> _mergeOperator;

    public LazySegmentTree(
        Func<TMonoid, TMonoid, TMonoid> merge,
        Func<TMonoid, int, TOperatorMonoid, TMonoid> apply,
        Func<TOperatorMonoid, TOperatorMonoid, TOperatorMonoid> mergeOperator,
        TMonoid identity,
        TOperatorMonoid operatorIdentity) {
        _merge = merge;
        _apply = apply;
        _mergeOperator = mergeOperator;
        _identity = identity;
        _operatorIdentity = operatorIdentity;
    }

    public void Build(IList<TMonoid> array) {
        Build(array.Count, i => array[i]);
    }

    public void Build(int n, Func<int, TMonoid> create) {
        Count = n;

        _node = new TMonoid[2 * Count];
        _operators = new TOperatorMonoid[Count];
        _dataNum = new int[2 * Count];
        _height = new int[2 * Count];
        for (var i = 0; i < _node.Length; i++) {
            _node[i] = _identity;
        }
        for (int i = 0; i < _operators.Length; i++) {
            _operators[i] = _operatorIdentity;
        }

        for (var i = 0; i < n; i++) {
            _node[i + Count] = create(i);
            _dataNum[i + Count] = 1;
        }

        for (var i = 2; i < _height.Length; i++) {
            _height[i] = _height[i >> 1] + 1;
        }

        for (var i = Count - 1; i > 0; i--) {
            _node[i] = _merge(_node[i << 1], _node[i << 1 | 1]);
            _dataNum[i] = _dataNum[i << 1] + _dataNum[i << 1 | 1];
        }
    }

    public TMonoid Query(int begin, int end) {
        TMonoid lv = _identity, rv = _identity;
        begin += Count;
        end += Count;
        TopDownOperators(begin);
        TopDownOperators(end - 1);
        for (int l = begin, r = end; l < r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { lv = _merge(lv, _node[l++]); }
            if ((r & 1) == 1) { rv = _merge(_node[--r], rv); }
        }
        return _merge(lv, rv);
    }

    public void LazyUpdate(int begin, int end, in TOperatorMonoid @operator) {
        begin += Count;
        end += Count;
        TopDownOperators(begin);
        TopDownOperators(end - 1);
        for (int l = begin, r = end; l < r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { Apply(l, @operator); l++; }
            if ((r & 1) == 1) { Apply(r - 1, @operator); r--; }
        }

        var height = _height[_height.Length - 1];
        for (var i = 1; i <= height; ++i) {
            if (((begin >> i) << i) != begin) Up(begin >> i);
            if (((end >> i) << i) != end) Up((end - 1) >> i);
        }
    }

    private void TopDownOperators(int k) {
        for (var i = _height[k]; i > 0; i--) {
            Propagate(k >> i);
        }
    }

    private void Propagate(int k) {
        var @operator = _operators[k];
        int childL = k << 1, childR = childL | 1;
        Apply(childL, @operator);
        Apply(childR, @operator);
        _operators[k] = _operatorIdentity;
    }

    public void Up(int k) {
        _node[k] = _merge(_node[k << 1], _node[k << 1 | 1]);
    }

    private void Apply(int k, in TOperatorMonoid @operator) {
        _node[k] = _apply(_node[k], _dataNum[k], @operator);
        if (k < Count) {
            _operators[k] = _mergeOperator(_operators[k], @operator);
        }
    }

    private void BottomUpMonoids(int k) {
        while (k > 0 && (k & 1) == 0) k >>= 1;
        while ((k >>= 1) > 0) {
            _node[k] = _merge(_node[k << 1], _node[k << 1 | 1]);
        }
    }

    public TMonoid this[int index] {
        get {
            index += Count;
            TopDownOperators(index);
            return _node[index];
        }
        set {
            index += Count;
            TopDownOperators(index);
            _node[index] = value;
            BottomUpMonoids(index);
        }
    }
}



