def op(s, t)
  sv, sn = s >> 32, s % (1 << 32)
  tv, tn = t >> 32, t % (1 << 32)
  (((sv + tv) % MOD) << 32) + sn + tn
end

def mapping(f, a)
  fb, fc = (f >> 32), (f % (1 << 32))
  av, an = (a >> 32), (a % (1 << 32))
  (((fb * av + fc * an) % MOD) << 32) + an
end

def composition(f, g)
  fb, fc = f >> 32, f % (1 << 32)
  gb, gc = g >> 32, g % (1 << 32)
  ((fb * gb % MOD) << 32) + ((gc * fb + fc) % MOD)
end

