        while l < r
            (sml = @op.call(sml, @d[l]); l += 1) if l[0] == 1
            smr = @op.call(@d[r -= 1], smr) if r[0] == 1
            l >>= 1
            r >>= 1
        end

        @op.call(sml, smr)
    end

    def all_prod; @d[1]; end

    def all_apply(k, f) 
        @d[k] = @mapping.call(f, @d[k])
        @lz[k] = @composition.call(f, @lz[k]) if k < @size
    end

