        return if l == r
        l += @size
        r += @size

        @log.downto(1) do |i|
            push(l >> i) if (l >> i) << i != l
            push((r - 1) >> i) if (r >> i) << i != r
        end

        l2, r2 = l, r
        while l < r
            (all_apply(l, f); l += 1) if l[0] == 1
            all_apply(r -= 1, f) if r[0] == 1
            l >>= 1
            r >>= 1
        end

        l, r = l2, r2
        1.upto(@log) do |i|
            update(l >> i) if (l >> i) << i != l
            update((r - 1) >> i) if (r >> i) << i != r
        end
    end

    def max_right(l, &g)
        return @n if l == @n
        l += @size
        @log.downto(1) {|i| push(l >> i)}
        sm = @e

        loop do
            l >>= 1 while l[0] == 0
            if !g.call(@op.call(sm, @d[l]))
                while l < @size
                    push(l)
                    l <<= 1
                    if g.call(@op.call(sm, @d[l]))
                        sm = @op.call(sm, @d[l])
                        l += 1
                    end
                end
                return l - @size
            end
            sm = @op.call(sm, @d[l])
            l += 1
            break if l & -l == l
        end
        return @n
    end

    def min_left(r, &g)
        return 0 if r == 0
        r += @size
        @log.downto(1) {|i| push((r - 1) >> i)}
        sm = @e

        loop do
            r -= 1
            r >>= 1 while r > 1 && r[0] == 1
            if !g.call(@op.call(@d[r], sm))
                while r < @size
                    push(r)
                    r = 2 * r + 1
                    if g.call(@op.call(@d[r], sm))
                        sm = @op.call(@d[r], sm)
                        r -= 1
                    end
                end
                return r + 1 - @size
            end
            sm = @op.call(@d[r], sm)
            break if r & -r == r
        end
        return 0
    end
end

