func newLazySegmentTree(n int, e node, id onode, f func(a, b node) node, g func(a node, b onode) node, h func(a, b onode) onode) *lazySegmentTree {
	sz, log := 1, 0
	for sz < n {
		sz <<= 1
		log++
	}
	d := make([]node, 2*sz)
	lz := make([]onode, 2*sz)
	for i := 0; i < 2*sz; i++ {
