	}
	AffineMerger := func(l, r S) S {
		return S{(l.a + r.a) % lp2, (l.size + r.size) % lp2}
	}
	AffineMapper := func(l F, r S) S {
		return S{(r.a*l.a + r.size*l.b) % lp2, r.size % lp2}
	}
	AffineComp := func(l, r F) F {
		return F{r.a * l.a % lp2, ((r.b * l.a) + l.b) % lp2}
	}
	AffineId := func() F {
		return F{1, 0}
	}
	lseg := newLazySegtree(a, AffineE, AffineMerger, AffineMapper, AffineComp, AffineId)
	for i := 0; i < q; i++ {
		t := iScan()
		if t == 0 {
			l, r, c, d := iScan(), iScan(), iScan(), iScan()
