class lazySegTree(object):
	# N:処理する区間の長さ
	def __init__(self, N):
		self.N = N
		self.LV = (N - 1).bit_length()
		self.N0 = 2 ** self.LV
		self.initVal = 0
		self.data = [0] * (2 * self.N0)
		self.lazybeta = [0] * (2 * self.N0)
		self.lazy = [0] * (2 * self.N0)

	def calc(self, a, b):
		return a + b

	def initialize(self, A):
		for i in range(self.N):
			self.data[self.N0 - 1 + i] = A[i]
		for i in range(self.N0 - 2, -1, -1):
			self.data[i] = self.calc(self.data[2 * i + 1], self.data[2 * i + 2])

	def gindex(self, l, r):
		L = (l + self.N0) >> 1; R = (r + self.N0) >> 1
		lc = 0 if l & 1 else (L & -L).bit_length()
		rc = 0 if r & 1 else (R & -R).bit_length()
		for i in range(self.LV):
			if rc <= i:
				yield R
			if L < R and lc <= i:
				yield L
			L >>= 1; R >>= 1

	def propagates(self, *ids):
		for i in reversed(ids):
			w = self.lazybeta[i - 1]
			v = self.lazy[i - 1]
			if not w:
				continue
			val = v >> 1
			self.lazybeta[2 * i - 1] += w; self.lazybeta[2 * i] += w
			self.data[2 * i - 1] = (self.data[2 * i - 1] * w) % mod
			self.data[2 * i] = (self.data[2 * i] * w) % mod
			self.lazy[2 * i - 1] += val; self.lazy[2 * i] += val
			self.data[2 * i - 1] += val; self.data[2 * i] += val
			self.lazybeta[i - 1] = 0
			self.lazy[i - 1] = 0

	def update(self, l, r, b, c):
		# 1行にまとめてよい？
		*ids, = self.gindex(l, r + 1)
		self.propagates(*ids)

		L = self.N0 + l; R = self.N0 + r + 1
		v = c
		w = b
		while L < R:
			if R & 1:
				R -= 1
				self.lazybeta[R - 1] += w; self.data[R - 1] = (self.data[R - 1] * w) % mod
				self.lazy[R - 1] += v; self.data[R - 1] += v
			if L & 1:
				self.lazybeta[L - 1] += w; self.data[L - 1] = (self.data[L - 1] * w) % mod
				self.lazy[L - 1] += v; self.data[L - 1] += v
				L += 1
			L >>= 1; R >>= 1; v <<= 1
		for i in ids:
			self.data[i - 1] = self.calc(self.data[2 * i - 1], self.data[2 * i])

	def query(self, l, r):
		self.propagates(*self.gindex(l, r + 1))
		L = self.N0 + l; R = self.N0 + r + 1

		s = self.initVal
		while L < R:
			if R & 1:
				R -= 1
				s = self.calc(s, self.data[R - 1])
			if L & 1:
				s = self.calc(s, self.data[L - 1])
				L += 1
			L >>= 1; R >>= 1
		return s

def main():
