class LazySegmentTree:
    def __init__(self, n, func1, func2, func3, func4, e1, e2, arrange=None):
        self.init(n)
        self.func1 = func1
        self.func2 = func2
        self.func3 = func3
        self.func4 = func4
        self.e1 = e1
        self.e2 = e2
        self.make_arrange(arrange)
        self.lazy = [self.e2]*self.size

    def init(self, n):
        self.inf = pow(2, 32)
        self.n = n
        self.N = 1
        while self.N < self.n:
            self.N *= 2
        self.size = self.N * 2 - 1
        self.N -= 1

    def make_arrange(self, arrange):
        self.set_arrange(arrange)
        self.construct(arrange)

    def set_arrange(self, arrange):
        if arrange == None:
            self.segment = [self.e1]*self.size
            return
        self.segment = [0]*(self.N) + arrange + [self.e1]*(self.size-self.N-self.n)

    def construct(self, arrange):
        if arrange == None:
            return
        for i in range(self.N-1, -1, -1):
            self.segment[i] = self.func1(self.segment[2*i+1], self.segment[2*i+2])

    def evaluate(self, i, length):
        if self.lazy[i] == self.e2:
            return
        if i < self.size-self.N-1:
            self.lazy[2*i+1] = self.func2(self.lazy[2*i+1], self.lazy[i])
            self.lazy[2*i+2] = self.func2(self.lazy[2*i+2], self.lazy[i])
        self.segment[i] = self.func3(self.segment[i], self.func4(self.lazy[i], length))
        self.lazy[i] = self.e2

    def update_sub(self, a, b, x, k, l, r):
        self.evaluate(k, r-l)
        if a <= l and r <= b:
            self.lazy[k] = self.func2(self.lazy[k], x)
            self.evaluate(k, r-l)
        elif a < r and l < b:
            self.update_sub(a, b, x, 2*k+1, l, (l+r)//2)
            self.update_sub(a, b, x, 2*k+2, (l+r)//2, r)
            self.segment[k] = self.func1(self.segment[k*2+1], self.segment[k*2+2])

    def update(self, a, b, x):
        self.update_sub(a-1, b, x, 0, 0, self.size-self.N)

    def find(self, a, b, k, l, r):
        self.evaluate(k, r-l)
        if r <= a or b <= l:
            return self.e1
        elif a <= l and r <= b:
            return self.segment[k]
        else:
            find_l = self.find(a, b, 2*k+1, l, (l+r)//2)
            find_r = self.find(a, b, 2*k+2, (l+r)//2, r)
            res = self.func1(find_l, find_r)
            return res

    def count(self, l, r):
        return self.find(l-1, r, 0, 0, self.size-self.N)


def main():
