    a = list(map(int, input().split()))

    mod = 998244353
    lim = 1 << 32

    func1 = lambda x, y: (x + y) % mod
    func2 = lambda a1, a2: (((a1 >> 32) * (a2 >> 32) % mod) << 32) + (((a1 % lim) * (a2 >> 32) + (a2 % lim)) % mod)
    func3 = lambda x, a: ((a >> 32) * x + (a % lim)) % mod
    func4 = lambda x, n: ((x >> 32) << 32) + (x % lim) * n % mod
    e1 = 0
    e2 = (1 << 32)

