        for i in range(self.log, 0, -1): self.__push(p >> i)
        self.data[p] = x
        for i in range(1, self.log + 1): self.__update(p >> i)

    def point_get(self, p):
        p += self.N0
        for i in range(self.log, 0, -1): self.__push(p >> i)
        return self.data[p]

    def prod(self, l, r):
        assert 0 <= l and l <= r and r <= self.N
        if l == r: return self.e_X
        l += self.N0; r += self.N0

        for i in range(self.log, 0, -1):
            if ((l >> i) << i) != l: self.__push(l >> i)
            if ((r >> i) << i) != r: self.__push(r >> i)

        sml, smr = self.e_X, self.e_X
        while l < r:
            if l & 1: sml = self.op_X(sml, self.data[l]); l += 1
            if r & 1: r -= 1; smr = self.op_X(self.data[r], smr)
            l >>= 1; r >>= 1

        return self.op_X(sml, smr)

    def all_prod(self): return self.data[1]

    def apply(self, p, f):
        assert 0 <= p and p < self.N
        p += self.N0
        for i in range(self.log, 0, -1): self.__push(p >> i)
        self.data[p] = self.mapping(f, self.data[p])
        for i in range(1, self.log + 1): self.__update(p >> 1)

    def apply(self, l, r, f):
        assert 0 <= l and l <= r and r <= self.N
        if l == r: return
        l += self.N0; r += self.N0

        for i in range(self.log, 0, -1):
            if ((l >> i) << i) != l: self.__push(l >> i)
            if ((r >> i) << i) != r: self.__push((r - 1) >> i)

        l2, r2 = l, r
        while l < r:
            if l & 1: self.__all_apply(l, f); l += 1
            if r & 1: r -= 1; self.__all_apply(r, f)
            l >>= 1; r >>= 1
        l, r = l2, r2

        for i in range(1, self.log + 1):
            if ((l >> i) << i) != l: self.__update(l >> i)
            if ((r >> i) << i) != r: self.__update(r >> i)

    def max_right(self, l, g):
        assert 0 <= l and l <= self.N
        if l == self.N: return self.N
        l += self.N0
        for i in range(self.log, 0, -1): self.__push(l >> i)
        sm = self.e_X
        while True:
            while l % 2 == 0: l >>= 1
            if not g(self.op_X(sm, self.data[l])):
                while l < self.N0:
                    self.__push(l)
                    l = 2 * l
                    if g(self.op_X(sm, self.data[l])):
                        sm = self.op_X(sm, self.data[l])
                        l += 1
                return l - self.N0
            sm = self.op_X(sm, self.data[l])
            l += 1
            if (l & -l) != l: break
        return self.N

    def min_left(self, r, g):
        assert 0 <= r and r <= self.N
        if r == 0: return 0
        r += self.N0
        for i in range(self.log, 0, -1): self.__push(r >> i)
        sm = self.e_X
        while True:
            r -= 1
            while r > 1 and r % 2: r >>= 1
            if not g(self.op_X(self.data[r], sm)):
                while r < self.N0:
                    self.__push(r)
                    r = 2 * r + 1
                    if g(self.op_X(self.data[r], sm)):
                        sm = self.op_X(self.data[r], sm)
                        r += 1
                return r + 1 - self.N0
            sm = self.op_X(self.data[r], sm)
            if (r & -r) != r: break
        return 0

    # private
    def __update(self, k): self.data[k] = self.op_X(self.data[k * 2], self.data[k * 2 + 1])

    def __all_apply(self, k, f):
        self.data[k] = self.mapping(f, self.data[k])
        if k < self.N0: self.lazy[k] = self.compose(f, self.lazy[k])

    def __push(self, k):
        self.__all_apply(2 * k, self.lazy[k])
        self.__all_apply(2 * k + 1, self.lazy[k])
        self.lazy[k] = self.id_M





