use proconio::*;

use modint::*;

type M = ModInt<Mod>;

struct R;
impl TE for R {
    type T = (M, M);
    type E = (M, M);
    fn fold(l: &Self::T, r: &Self::T) -> Self::T {
        (l.0 + r.0, l.1 + r.1)
    }
    fn eval(x: &Self::T, f: &Self::E) -> Self::T {
        (f.0 * x.0 + f.1 * x.1, x.1)
    }
    fn merge(g: &Self::E, h: &Self::E) -> Self::E {
        (g.0 * h.0, h.0 * g.1 + h.1)
    }
    fn e() -> Self::T {
        (M::zero(), M::zero())
    }
    fn id() -> Self::E {
        (M::one(), M::zero())
    }
}

#[fastout]
fn run() {
    input! {
        n: usize,
        q: usize,
        a: [M; n],
    }
    let a: Vec<_> = a.into_iter().map(|a| (a, M::one())).collect();
    let mut seg = LazySegmentTree::<R>::build_by(&a);
    for _ in 0..q {
        input! {
            op: u8,
            l: usize,
            r: usize,
        }
        if op == 0 {
            input! {
                f: (M, M),
            }
            seg.update(l, r, f);
        } else {
            let ans = seg.find(l, r).0;
            println!("{}", ans);
        }
    }
}

fn main() {
    run();
}

