struct Sum;
impl Monoid for Sum {
    type S = (ModInt998244353, isize);
    fn identity() -> Self::S {
        (ModInt998244353::new(0), 1)
    }
    fn binary_operation(a: &Self::S, b: &Self::S) -> Self::S {
        (a.0 + b.0, a.1 + b.1)
    }
}

struct AffineRangeSum;
impl MapMonoid for AffineRangeSum {
    type M = Sum;
    type F = (ModInt998244353, ModInt998244353);
    fn identity_map() -> Self::F {
        (ModInt998244353::new(1), ModInt998244353::new(0))
    }
    fn mapping(l: &Self::F, r: &<Self::M as Monoid>::S) -> <Self::M as Monoid>::S {
        (r.0 * l.0 + ModInt998244353::new(r.1) * l.1, r.1)
    }
    fn composition(l: &Self::F, r: &Self::F) -> Self::F {
        (r.0 * l.0, r.1 * l.0 + l.1)
    }
}

#[fastout]
fn main() {
    input! {
        n:usize,q:usize,
        a:[isize;n]
    }
    let mut ls: LazySegtree<AffineRangeSum> = LazySegtree::from(
        a.iter()
