const MOD: usize = 998244353;
//const LEN: usize = 524288;
const LEN: usize = 8;
#[fastout]
fn main() {
    input! {
        n:usize,q:usize,
        a:[usize;n]
    }
    let mut s = SegTreeLazy::new(
        LEN,
        (0, 0),
        (1, 0),
        |a, b| ((a.0 + b.0) % MOD, 0),
        |a, b| ((a.0 * b.0 + b.1) % MOD, 0),
        |a, b| ((a.0 * b.0) % MOD, (b.0 * a.1 + b.1 * 499122177) % MOD),
    );
    for (i, x) in a.iter().enumerate() {
        s.update(i, i + 1, (0, x * LEN * 2));
    }
    for _ in 0..q {
        input! {
            t:usize
        }
        if t == 0 {
            input! {
                l:usize,r:usize,b:usize,c:usize
            }
            s.update(l, r, (b, c * LEN * 2));
        } else {
            input! {
                l:usize,
                r:usize,
            }
            println!("{}", s.get(l, r).0);
        }
    }
}

