#[derive(Debug, Clone, Copy)]
struct Average(ModInt);

impl std::ops::Mul for Average {
    type Output = Self;
    fn mul(self, other: Self) -> Self {
        Average((self.0 + other.0) / 2)
    }
}

impl Monoid for Average {
    fn unit() -> Self {
        Average(ModInt::new(0, 998244353))
    }
}

#[derive(Debug, Clone, Copy)]
struct Affine(i64, i64);

impl std::ops::Mul for Affine {
    type Output = Self;
    fn mul(self, other: Self) -> Self {
        Affine(self.0 * other.0, self.1 * other.0 + other.1)
    }
}

impl Monoid for Affine {
    fn unit() -> Self {
        Affine(1, 0)
    }
}

impl Act<Average> for Affine {
    fn act(&self, other: Average) -> Average {
        Average(other.0 * self.0 + self.1)
    }
}

