#[derive(Debug, Clone, Copy)]
struct Sum(ModInt, i64);

impl std::ops::Mul for Sum {
    type Output = Self;
    fn mul(self, other: Self) -> Self {
        Sum(self.0 + other.0, self.1 + other.1)
    }
}

const MOD: i64 = 998244353;

impl Monoid for Sum {
    fn unit() -> Self {
        Sum(ModInt::new(0, MOD), 0)
    }
}

#[derive(Debug, Clone, Copy)]
struct Affine(ModInt, ModInt);

impl std::ops::Mul for Affine {
    type Output = Self;
    fn mul(self, other: Self) -> Self {
        let Affine(b1, c1) = self;
        let Affine(b2, c2) = other;
        Affine(b1 * b2, b2 * c1 + c2)
    }
}

impl Monoid for Affine {
    fn unit() -> Self {
        Affine(ModInt(1, MOD), ModInt(0, MOD))
    }
}

impl Act<Sum> for Affine {
    fn act(&self, other: Sum) -> Sum {
        let &Affine(b, c) = self;
        let Sum(s, len) = other;
        Sum(s * b + c * len, len)
    }
}

